function clamp(v, lo, hi) {
  return Math.max(lo, Math.min(hi, v));
}

function cap(s) {
  return s.charAt(0).toUpperCase() + s.slice(1);
}

function statBlock(base) {
  const maxHp = Math.floor(((2 * base.hp + 31) * 50) / 100 + 50 + 10);
  const out = { maxHp };
  for (const key of ['atk', 'def', 'spa', 'spd', 'spe']) {
    out[key] = Math.floor(((2 * base[key] + 31) * 50) / 100 + 5);
  }
  return out;
}

function makeAbility(rng, type) {
  const entry = rng.weighted(ABILITIES.map((a) => [a, a.weight]));
  const name = entry.key === 'typeDamage' ? ABILITY_TYPE_NAMES[type] : entry.name;
  return {
    ...entry,
    name,
    desc: entry.desc.replace('{type}', TYPES[type].name),
  };
}

function makeMove(rng, creatureType, group, index, usedNames) {
  const moveType = rng.chance(0.72) ? creatureType : rng.pick(TYPE_ORDER.filter((t) => t !== creatureType));
  const typeData = TYPES[moveType];
  const adjectives = typeData.adjectives;
  const nouns = MOVE_WORDS[group][moveType];
  let name = '';
  for (let attempt = 0; attempt < 24; attempt++) {
    const adj = rng.pick(adjectives);
    const noun = rng.pick(nouns);
    name = rng.chance(0.35) ? `${adj}${noun.toLowerCase()}` : `${adj} ${noun}`;
    if (!usedNames.has(name)) break;
  }
  if (usedNames.has(name)) name = `${name} ${['I', 'II', 'III'][index] || ''}`.trim();
  usedNames.add(name);

  const arche = creatureType === moveType ? 1.08 : 1;

  if (group === 'status') {
    const effects = [];
    const statusKind = STATUS_FOR_TYPE[moveType];
    const primary = rng.weighted([
      ['buff', 30],
      ['inflict', 20],
      ['barrier', 15],
      ['heal', 15],
      ['debuff', 15],
      ['cleanse', 5],
    ]);
    const usedStats = new Set();
    const addBuff = () => {
      const stat = rng.pick(['atk', 'spa', 'def', 'spd', 'spe'].filter((s) => !usedStats.has(s)));
      if (!stat) return;
      usedStats.add(stat);
      effects.push({ kind: 'buff', target: 'self', stat, stages: rng.chance(0.24) ? 2 : 1 });
    };
    const addDebuff = () => {
      const stat = rng.pick(['atk', 'spa', 'def', 'spd', 'spe'].filter((s) => !usedStats.has(s)));
      if (!stat) return;
      usedStats.add(stat);
      effects.push({ kind: 'debuff', target: 'foe', stat, stages: rng.chance(0.2) ? 2 : 1 });
    };
    const addInflict = () => effects.push({ kind: 'status', target: 'foe', status: statusKind, chance: rng.chance(0.4) ? 1 : rng.float(0.72, 0.92) });

    if (primary === 'buff') addBuff();
    else if (primary === 'debuff') addDebuff();
    else if (primary === 'inflict') addInflict();
    else if (primary === 'heal') effects.push({ kind: 'heal', target: 'self', amount: rng.float(0.26, 0.42) });
    else if (primary === 'barrier') effects.push({ kind: 'barrier', target: 'self', amount: rng.float(0.2, 0.34) });
    else effects.push({ kind: 'cleanse', target: 'self' });

    if (rng.chance(0.46)) {
      const extra = rng.pick(['buff', 'debuff', 'inflict', 'cleanse']);
      if (extra === 'buff') addBuff();
      else if (extra === 'debuff') addDebuff();
      else if (extra === 'inflict' && !effects.some((e) => e.kind === 'status')) addInflict();
      else if (extra === 'cleanse' && !effects.some((e) => e.kind === 'cleanse')) effects.push({ kind: 'cleanse', target: 'self' });
    }

    return {
      name,
      group,
      type: moveType,
      power: 0,
      accuracy: effects.some((e) => e.kind === 'status') && rng.chance(0.35) ? 90 : 100,
      maxPp: rng.int(9, 15),
      pp: 0,
      priority: effects.some((e) => e.kind === 'heal' || e.kind === 'barrier') ? 1 : 0,
      effects,
      desc: describeEffects(effects),
      flavor: 'Status',
      id: `${group}-${index}-${moveType}`,
    };
  }

  let power = 48 + rng.float(0, 56);
  const arch = ARCHETYPES[creatureType] || ARCHETYPES.balanced;
  if (group === 'physical') power *= 0.9 + arch.atk * 0.12;
  else power *= 0.9 + arch.spa * 0.12;
  power = Math.round(clamp(power * arche, 42, 124));
  const accuracy = Math.round(clamp(100 - Math.max(0, power - 55) * 0.32 + rng.float(-4, 4), 78, 100));
  const maxPp = Math.round(clamp(14 - (power - 45) / 12 + rng.int(-1, 1), 5, 16));
  const secondary = [];
  if (rng.chance(0.34)) {
    if (rng.chance(0.55)) {
      secondary.push({
        kind: 'debuff', target: 'foe', chance: 0.28,
        stat: rng.pick(['def', 'spd', 'spe', 'atk', 'spa']), stages: 1,
      });
    } else {
      secondary.push({ kind: 'status', target: 'foe', status: STATUS_FOR_TYPE[moveType], chance: 0.18 });
    }
  }

  return {
    name,
    group,
    type: moveType,
    power,
    accuracy,
    maxPp,
    pp: 0,
    priority: 0,
    effects: secondary,
    desc: secondary.length ? `A ${TYPES[moveType].name.toLowerCase()} ${group} attack. ${describeEffects(secondary, true)}` : `A ${TYPES[moveType].name.toLowerCase()} ${group} attack with no extra effect.`,
    flavor: group === 'physical' ? 'Contact' : 'Ranged',
    id: `${group}-${index}-${moveType}`,
  };
}

export function describeEffects(effects, chanceOnly = false) {
  const statName = (s) => ({ atk: 'Attack', def: 'Defense', spa: 'Spirit', spd: 'Ward', spe: 'Speed' }[s]);
  const parts = effects.map((e) => {
    const prefix = chanceOnly || (e.chance !== undefined && e.chance < 1) ? 'May ' : '';
    if (e.kind === 'buff') return `${prefix}raise the user's ${statName(e.stat)} by ${e.stages} stage${e.stages > 1 ? 's' : ''}`;
    if (e.kind === 'debuff') return `${prefix}lower the target's ${statName(e.stat)} by ${e.stages} stage${e.stages > 1 ? 's' : ''}`;
    if (e.kind === 'heal') return `restore ${Math.round(e.amount * 100)}% of the user's max HP`;
    if (e.kind === 'barrier') return `grant a barrier absorbing ${Math.round(e.amount * 100)}% max HP`;
    if (e.kind === 'status') return `${prefix}${STATUS_INFO[e.status].name.toLowerCase()} the target`;
    if (e.kind === 'cleanse') return `cure the user's status`;
    return '';
  }).filter(Boolean);
  let text = parts.join(' and ');
  return text.charAt(0).toUpperCase() + text.slice(1) + '.';
}

function makeCreature(rng, type, usedNames, side, index) {
  const typeData = TYPES[type];
  const archetypeKey = rng.weighted([
    ['striker', 22], ['caster', 22], ['guardian', 20], ['trickster', 18], ['balanced', 18],
  ]);
  const arch = ARCHETYPES[archetypeKey];
  const body = rng.weighted(BODY_BY_TYPE[type]);

  let name = '';
  for (let attempt = 0; attempt < 30; attempt++) {
    const [a, b] = typeData.syllables;
    name = cap(rng.pick(a)) + rng.pick(b);
    if (!usedNames.has(name)) break;
  }
  if (usedNames.has(name)) name = name + ['a', 'or', 'ix', 'en'][index % 4];
  usedNames.add(name);

  const base = {};
  for (const key of ['hp', 'atk', 'def', 'spa', 'spd', 'spe']) {
    const raw = key === 'hp' ? 62 + rng.float(0, 52) : 54 + rng.float(0, 68);
    base[key] = Math.round(clamp(raw * arch[key] * rng.float(0.95, 1.08), 38, 156));
  }
  const stats = statBlock(base);
  const ability = makeAbility(rng, type);
  if (ability.key === 'speed') stats.spe = Math.round(stats.spe * 1.15);
  if (ability.key === 'barrierStart') stats.startBarrier = Math.round(stats.maxHp * 0.18);

  const usedMoveNames = new Set();
  const moves = [];
  for (const group of GROUP_ORDER) {
    for (let i = 0; i < 2; i++) {
      const move = makeMove(rng, type, group, i, usedMoveNames);
      move.pp = move.maxPp;
      moves.push(move);
    }
  }

  return {
    id: `${side}-${index}-${rng.int(1000, 9999)}`,
    side,
    index,
    name,
    species: `${rng.pick(typeData.adjectives)} ${rng.pick(typeData.nouns)}`,
    type,
    archetype: archetypeKey,
    archetypeLabel: arch.label,
    body,
    level: 50,
    stats,
    base,
    hp: stats.maxHp,
    maxHp: stats.maxHp,
    ability,
    moves,
    status: null,
    barrier: stats.startBarrier || 0,
    stages: { atk: 0, def: 0, spa: 0, spd: 0, spe: 0 },
    fainted: false,
    scale: rng.float(0.88, 1.12),
    seed: rng.int(1, 999999),
    colors: typeData.palette,
  };
}

export function generateTeam(rng, side, count = 3, options = {}) {
  const types = rng.shuffle(TYPE_ORDER).slice(0, count);
  const usedNames = new Set();
  return types.map((type, i) => makeCreature(rng, type, usedNames, side, i));
}

export function generateRoom(rng) {
  const themeKey = rng.pick(Object.keys(ROOM_THEMES));
  const theme = ROOM_THEMES[themeKey];
  const [nameA, nameB] = rng.pick(theme.names);
  const useAdjective = rng.chance(0.35);
  const name = useAdjective
    ? `${rng.pick(ROOM_ADJECTIVES)} ${nameB}`
    : `${nameA} ${nameB}`;
  return {
    key: themeKey,
    theme,
    name,
    seed: rng.int(1, 999999),
    pillarCount: rng.pick([6, 8, 8, 10]),
    crystalCount: rng.int(8, 14),
    bannerCount: rng.pick([3, 4, 4, 5]),
    ringCount: rng.int(3, 5),
    motes: rng.int(90, 160),
    fogDensity: rng.float(0.015, 0.024),
    rotation: rng.float(0, Math.PI * 2),
  };
}

export function generateWarden(rng) {
  const first = rng.pick(['Veyra', 'Orin', 'Sable', 'Kael', 'Nyx', 'Aurel', 'Morrow', 'Thane', 'Iri', 'Voss']);
  const titles = ['Rift Warden', 'Arena Sovereign', 'Keeper of the Gate', 'Champion of the Rift', 'The Unbroken'];
  return { name: `Warden ${first}`, title: rng.pick(titles) };
}

export function generateRun(seed) {
  const rng = new RNG(seed);
  const room = generateRoom(rng.child('room'));
  const playerTeam = generateTeam(rng.child('player'), 'player', 3);
  const enemyTeam = generateTeam(rng.child('enemy'), 'enemy', 3);
  const warden = generateWarden(rng.child('warden'));
  return {
    seed,
    room,
    playerTeam,
    enemyTeam,
    warden,
    createdAt: Date.now(),
  };
}

export function generateShowcase(seed) {
  const rng = new RNG(seed + ':showcase');
  const type = rng.pick(TYPE_ORDER);
  const creature = makeCreature(rng, type, new Set(), 'showcase', 0);
  creature.scale = 1.22;
  return creature;
}

export function restoreTeam(team) {
  for (const c of team) {
    c.hp = c.maxHp;
    c.maxHp = c.stats.maxHp;
    c.status = null;
    c.barrier = c.stats.startBarrier || 0;
    c.stages = { atk: 0, def: 0, spa: 0, spd: 0, spe: 0 };
    c.fainted = false;
    for (const m of c.moves) m.pp = m.maxPp;
  }
}

import * as THREE from 'three';
import { RNG } from './rng.js';

const S = {
  sphere: new THREE.SphereGeometry(1, 14, 10),
  sphereLow: new THREE.SphereGeometry(1, 10, 8),
  cone: new THREE.ConeGeometry(1, 1, 7),
  cone4: new THREE.ConeGeometry(1, 1, 4),
  cyl: new THREE.CylinderGeometry(1, 1, 1, 8),
  cylTaper: new THREE.CylinderGeometry(0.6, 1, 1, 7),
  capsule: new THREE.CapsuleGeometry(1, 1.4, 3, 8),
  octa: new THREE.OctahedronGeometry(1, 0),
  box: new THREE.BoxGeometry(1, 1, 1),
  torus: new THREE.TorusGeometry(1, 0.1, 6, 24),
  circle: new THREE.CircleGeometry(1, 24),
  plane: new THREE.PlaneGeometry(1, 1),
};

function makeWingGeometry() {
  const shape = new THREE.Shape();
  shape.moveTo(0, 0);
  shape.quadraticCurveTo(0.55, 0.5, 1.25, 0.34);
  shape.quadraticCurveTo(0.92, 0.02, 1.02, -0.36);
  shape.quadraticCurveTo(0.48, -0.2, 0, -0.1);
  shape.lineTo(0, 0);
  return new THREE.ShapeGeometry(shape);
}

function makeBoltGeometry() {
  const shape = new THREE.Shape();
  shape.moveTo(0.05, 0.5);
  shape.lineTo(-0.16, 0.08);
  shape.lineTo(0.02, 0.08);
  shape.lineTo(-0.08, -0.5);
  shape.lineTo(0.2, -0.04);
  shape.lineTo(0.02, -0.04);
  shape.lineTo(0.05, 0.5);
  return new THREE.ExtrudeGeometry(shape, { depth: 0.05, bevelEnabled: false });
}

S.wing = makeWingGeometry();
S.bolt = makeBoltGeometry();

let shadowTexture = null;
function getShadowTexture() {
  if (shadowTexture) return shadowTexture;
  const c = document.createElement('canvas');
  c.width = c.height = 128;
  const g = c.getContext('2d');
  const grad = g.createRadialGradient(64, 64, 2, 64, 64, 62);
  grad.addColorStop(0, 'rgba(0,0,0,0.62)');
  grad.addColorStop(0.55, 'rgba(0,0,0,0.25)');
  grad.addColorStop(1, 'rgba(0,0,0,0)');
  g.fillStyle = grad;
  g.fillRect(0, 0, 128, 128);
  shadowTexture = new THREE.CanvasTexture(c);
  return shadowTexture;
}

function makeMaterial(color, opts = {}) {
  const m = new THREE.MeshStandardMaterial({
    color,
    roughness: opts.roughness ?? 0.62,
    metalness: opts.metalness ?? 0.06,
    flatShading: opts.flatShading ?? true,
    side: opts.side ?? THREE.FrontSide,
    transparent: false,
    emissive: opts.emissive ?? 0x000000,
    emissiveIntensity: opts.emissiveIntensity ?? 0,
  });
  m.userData.baseEmissive = new THREE.Color(opts.emissive ?? 0x000000);
  m.userData.baseIntensity = opts.emissiveIntensity ?? 0;
  return m;
}

function part(ctx, geo, mat, parent, pos = [0, 0, 0], scale = [1, 1, 1], rot = [0, 0, 0]) {
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.set(pos[0], pos[1], pos[2]);
  mesh.scale.set(scale[0], scale[1], scale[2]);
  mesh.rotation.set(rot[0], rot[1], rot[2]);
  mesh.castShadow = false;
  mesh.receiveShadow = false;
  parent.add(mesh);
  return mesh;
}

function buildMaterials(colors) {
  return {
    primary: makeMaterial(colors.primary),
    secondary: makeMaterial(colors.secondary),
    accent: makeMaterial(colors.accent, { emissive: colors.accent, emissiveIntensity: 0.22, roughness: 0.4 }),
    belly: makeMaterial(colors.belly, { roughness: 0.8 }),
    dark: makeMaterial(colors.dark, { roughness: 0.75 }),
    glow: makeMaterial(colors.glow, { emissive: colors.glow, emissiveIntensity: 1.1, roughness: 0.3 }),
    eyeWhite: makeMaterial('#fffaf0', { flatShading: false, roughness: 0.35 }),
    pupil: makeMaterial('#0a0710', { flatShading: false, roughness: 0.3 }),
    wing: makeMaterial(colors.secondary, { side: THREE.DoubleSide, roughness: 0.7 }),
    wingAccent: makeMaterial(colors.accent, { side: THREE.DoubleSide, emissive: colors.accent, emissiveIntensity: 0.18 }),
  };
}

function addEyes(ctx, head, r = 0.42, opts = {}) {
  const { mats, type } = ctx;
  const eyeZ = r * 0.78;
  const eyeX = r * 0.42;
  const glowing = type === 'umbra' || type === 'volt';
  for (const side of [-1, 1]) {
    const eye = part(ctx, S.sphere, glowing ? mats.glow : mats.eyeWhite, head, [side * eyeX, r * 0.14, eyeZ], [0.105, 0.125, 0.08]);
    const pupil = part(ctx, S.sphere, glowing ? mats.dark : mats.pupil, head, [side * eyeX, r * 0.14, eyeZ + 0.055], [0.052, 0.075, 0.035]);
    if (!glowing) {
      part(ctx, S.sphere, mats.eyeWhite, head, [side * eyeX + 0.018, r * 0.19, eyeZ + 0.082], [0.018, 0.022, 0.012]);
    }
    ctx.parts.eyes.push(eye, pupil);
  }
  if (opts.brow) {
    for (const side of [-1, 1]) {
      part(ctx, S.box, mats.dark, head, [side * eyeX, r * 0.35, eyeZ + 0.015], [0.16, 0.035, 0.05], [0, 0, side * -0.25]);
    }
  }
}

function addSnout(ctx, head, r, opts = {}) {
  const { mats } = ctx;
  const snout = part(ctx, S.sphere, mats.secondary, head, [0, -r * 0.18, r * 0.82], [r * 0.55, r * 0.38, r * 0.5]);
  part(ctx, S.sphere, mats.dark, head, [0, -r * 0.3, r * 1.02], [r * 0.3, r * 0.12, r * 0.12]);
  if (opts.fangs) {
    for (const side of [-1, 1]) {
      part(ctx, S.cone, mats.eyeWhite, head, [side * r * 0.2, -r * 0.4, r * 1.0], [r * 0.05, r * 0.16, r * 0.05], [Math.PI, 0, 0]);
    }
  }
  if (opts.nose) {
    part(ctx, S.sphere, mats.dark, head, [0, -r * 0.06, r * 1.16], [r * 0.12, r * 0.08, r * 0.08]);
  }
  return snout;
}

function addHornPair(ctx, head, r, style) {
  const { mats } = ctx;
  for (const side of [-1, 1]) {
    if (style === 'antler') {
      const g = new THREE.Group();
      g.position.set(side * r * 0.38, r * 0.55, -r * 0.08);
      g.rotation.z = side * -0.5;
      g.rotation.x = -0.2;
      head.add(g);
      part(ctx, S.cylTaper, mats.secondary, g, [0, 0.18, 0], [0.035, 0.35, 0.035]);
      part(ctx, S.cylTaper, mats.secondary, g, [side * 0.09, 0.38, 0.02], [0.028, 0.22, 0.028], [0, 0, side * -0.5]);
      part(ctx, S.cylTaper, mats.secondary, g, [side * -0.03, 0.42, -0.06], [0.024, 0.18, 0.024], [0.35, 0, side * 0.2]);
    } else if (style === 'fin') {
      part(ctx, S.cone4, mats.accent, head, [side * r * 0.55, r * 0.25, -r * 0.15], [r * 0.22, r * 0.55, r * 0.06], [0.2, 0, side * -0.8]);
    } else if (style === 'crystal') {
      part(ctx, S.octa, mats.accent, head, [side * r * 0.38, r * 0.55, -r * 0.05], [r * 0.14, r * 0.3, r * 0.14], [0, 0, side * 0.2]);
    } else if (style === 'ear') {
      part(ctx, S.cone, mats.primary, head, [side * r * 0.42, r * 0.52, -r * 0.02], [r * 0.2, r * 0.4, r * 0.12], [0.1, 0, side * -0.3]);
      part(ctx, S.cone, mats.belly, head, [side * r * 0.42, r * 0.5, r * 0.03], [r * 0.1, r * 0.25, r * 0.06], [0.1, 0, side * -0.3]);
    } else {
      part(ctx, S.cone, mats.secondary, head, [side * r * 0.34, r * 0.58, -r * 0.08], [r * 0.13, r * 0.5, r * 0.13], [-0.25, 0, side * -0.32]);
    }
  }
}

function addCrest(ctx, head, r) {
  const { mats, type } = ctx;
  if (type === 'lumen') {
    part(ctx, S.torus, mats.glow, head, [0, r * 0.72, 0], [r * 0.62, r * 0.62, r * 0.5], [Math.PI / 2, 0, 0]);
    part(ctx, S.octa, mats.accent, head, [0, r * 0.1, r * 0.72], [r * 0.14, r * 0.24, r * 0.12], [0.2, 0, 0]);
  } else if (type === 'umbra') {
    part(ctx, S.cone, mats.secondary, head, [0, r * 0.52, -r * 0.12], [r * 0.38, r * 0.7, r * 0.28], [-0.5, 0, 0]);
    for (let i = 0; i < 2; i++) {
      part(ctx, S.sphere, mats.glow, head, [(i ? 1 : -1) * r * 0.8, r * 0.15, -r * 0.1], [0.045, 0.045, 0.045]);
    }
  } else if (type === 'tide') {
    part(ctx, S.cone4, mats.accent, head, [0, r * 0.62, -r * 0.05], [r * 0.1, r * 0.52, r * 0.34], [0.1, 0, 0]);
  } else if (type === 'verdant') {
    for (let i = 0; i < 3; i++) {
      const a = (i - 1) * 0.55;
      part(ctx, S.octa, mats.secondary, head, [Math.sin(a) * r * 0.45, r * 0.58, Math.cos(a) * r * 0.1 - r * 0.1], [r * 0.18, r * 0.34, r * 0.08], [0.25, 0, -a * 0.6]);
    }
  } else if (type === 'volt') {
    part(ctx, S.bolt, mats.glow, head, [0, r * 0.56, -r * 0.08], [r * 0.65, r * 0.65, r * 0.65], [0, 0, 0.25]);
  } else {
    part(ctx, S.cone, mats.accent, head, [0, r * 0.62, -r * 0.12], [r * 0.16, r * 0.42, r * 0.16], [-0.2, 0, 0]);
  }
}

function addSpots(ctx, body, dims) {
  const { mats, rng, colors } = ctx;
  const count = rng.int(2, 5);
  for (let i = 0; i < count; i++) {
    const side = rng.chance(0.5) ? 1 : -1;
    const y = rng.float(-dims.y * 0.45, dims.y * 0.55);
    const z = rng.float(-dims.z * 0.7, dims.z * 0.35);
    const x = side * dims.x * (0.7 + rng.float(0, 0.2));
    part(ctx, S.sphere, i % 3 === 0 ? mats.belly : mats.accent, body,
      [x, y, z], [dims.x * 0.18, dims.y * 0.14, dims.z * 0.12]);
  }
}

function addTail(ctx, anchor, opts = {}) {
  const { mats, type } = ctx;
  const group = new THREE.Group();
  group.position.copy(anchor);
  ctx.body.add(group);
  ctx.parts.tails.push(group);
  const segments = opts.segments ?? 4;
  let parent = group;
  for (let i = 0; i < segments; i++) {
    const g = new THREE.Group();
    g.position.set(0, i === 0 ? 0 : -0.02, i === 0 ? 0 : -0.24);
    g.rotation.x = opts.droop ?? 0.1;
    parent.add(g);
    const size = (1 - i / (segments + 1)) * (opts.width ?? 0.16);
    part(ctx, S.sphere, i % 2 ? mats.secondary : mats.primary, g, [0, 0, -0.12], [size, size * 0.9, 0.2]);
    parent = g;
  }
  if (type === 'ember') {
    part(ctx, S.cone, mats.glow, parent, [0, 0.03, -0.3], [0.14, 0.34, 0.14], [-Math.PI / 2, 0, 0]);
  } else if (type === 'tide') {
    part(ctx, S.cone4, mats.accent, parent, [0, 0.03, -0.28], [0.22, 0.5, 0.05], [-Math.PI / 2, 0, 0]);
  } else if (type === 'verdant') {
    part(ctx, S.octa, mats.secondary, parent, [0, 0.02, -0.3], [0.18, 0.3, 0.1], [0.4, 0, 0]);
  } else if (type === 'volt') {
    part(ctx, S.bolt, mats.glow, parent, [0, 0.04, -0.3], [0.5, 0.5, 0.5], [0, 0, 0.3]);
  } else if (type === 'umbra' || type === 'lumen') {
    part(ctx, S.sphere, mats.glow, parent, [0, 0.02, -0.3], [0.09, 0.09, 0.09]);
  }
  return group;
}

function addWings(ctx, y, z, scale = 1) {
  const { mats, type } = ctx;
  for (const side of [-1, 1]) {
    const group = new THREE.Group();
    group.position.set(side * 0.25, y, z);
    group.rotation.y = side * -0.75;
    group.rotation.z = side * 0.15;
    ctx.body.add(group);
    const mesh = part(ctx, S.wing, mats.wing, group, [0, 0, 0], [scale * side, scale, 1]);
    const mesh2 = part(ctx, S.wing, mats.wingAccent, group, [0.02 * side, -0.02, 0.02], [scale * side * 0.72, scale * 0.72, 1]);
    ctx.parts.wings.push({ group, baseZ: group.rotation.z, side, mesh, mesh2 });
  }
}

function buildBiped(ctx) {
  const { body, mats, rng } = ctx;
  const torsoW = rng.float(0.48, 0.58);
  const torsoH = rng.float(0.62, 0.76);
  const torsoD = rng.float(0.38, 0.46);
  part(ctx, S.sphere, mats.primary, body, [0, 1.18, 0], [torsoW, torsoH, torsoD]);
  part(ctx, S.sphere, mats.belly, body, [0, 1.08, torsoD * 0.72], [torsoW * 0.6, torsoH * 0.72, torsoD * 0.32]);
  addSpots(ctx, body, { x: torsoW, y: torsoH, z: torsoD });

  const headY = 1.18 + torsoH * 0.92;
  const headGroup = new THREE.Group();
  headGroup.position.set(0, headY, torsoD * 0.2);
  body.add(headGroup);
  ctx.parts.head = headGroup;
  const r = rng.float(0.38, 0.45);
  part(ctx, S.sphere, mats.primary, headGroup, [0, 0, 0], [r, r * 0.94, r * 0.9]);
  part(ctx, S.sphere, mats.secondary, headGroup, [0, -r * 0.32, r * 0.32], [r * 0.58, r * 0.36, r * 0.46]);
  addEyes(ctx, headGroup, r, { brow: true });
  addSnout(ctx, headGroup, r, { fangs: ctx.type === 'ember' || ctx.type === 'umbra', nose: true });
  addHornPair(ctx, headGroup, r, ctx.type === 'verdant' || ctx.type === 'lumen' ? 'antler' : ctx.type === 'tide' ? 'fin' : 'ear');
  addCrest(ctx, headGroup, r);
  ctx.headR = r;

  for (const side of [-1, 1]) {
    const arm = new THREE.Group();
    arm.position.set(side * (torsoW * 0.94), 1.42, torsoD * 0.1);
    arm.rotation.z = side * 0.28;
    body.add(arm);
    part(ctx, S.capsule, mats.secondary, arm, [0, -0.24, 0], [0.095, 0.15, 0.095]);
    part(ctx, S.sphere, mats.primary, arm, [0, -0.46, 0.02], [0.13, 0.12, 0.13]);
    ctx.parts.arms.push({ group: arm, baseZ: arm.rotation.z, side });
  }

  for (const side of [-1, 1]) {
    const leg = new THREE.Group();
    leg.position.set(side * torsoW * 0.48, 0.64, 0);
    body.add(leg);
    part(ctx, S.capsule, mats.secondary, leg, [0, -0.22, 0], [0.13, 0.18, 0.13]);
    part(ctx, S.sphere, mats.primary, leg, [0, -0.5, 0.1], [0.18, 0.11, 0.27]);
    ctx.parts.legs.push({ group: leg, side });
  }

  addTail(ctx, new THREE.Vector3(0, 0.95, -torsoD * 0.9), { segments: 4, width: 0.15, droop: 0.1 });
  if (ctx.type === 'lumen' || ctx.type === 'umbra' || (ctx.type === 'volt' && rng.chance(0.5))) {
    addWings(ctx, 1.48, -torsoD * 0.6, 0.95);
  }
  return { height: headY + r };
}

function buildQuadruped(ctx) {
  const { body, mats, rng } = ctx;
  const w = rng.float(0.5, 0.62);
  const h = rng.float(0.46, 0.56);
  const d = rng.float(0.9, 1.08);
  part(ctx, S.sphere, mats.primary, body, [0, 1.02, 0], [w, h, d]);
  part(ctx, S.sphere, mats.belly, body, [0, 0.86, 0.05], [w * 0.72, h * 0.55, d * 0.72]);
  addSpots(ctx, body, { x: w, y: h, z: d });

  const headGroup = new THREE.Group();
  headGroup.position.set(0, 1.28, d * 0.78);
  body.add(headGroup);
  ctx.parts.head = headGroup;
  const r = rng.float(0.36, 0.44);
  part(ctx, S.sphere, mats.primary, headGroup, [0, 0, 0], [r, r * 0.92, r * 0.88]);
  addEyes(ctx, headGroup, r, { brow: true });
  addSnout(ctx, headGroup, r, { fangs: ctx.type === 'ember' || ctx.type === 'umbra', nose: true });
  addHornPair(ctx, headGroup, r, ctx.type === 'verdant' || ctx.type === 'lumen' ? 'antler' : ctx.type === 'tide' ? 'fin' : 'ear');
  addCrest(ctx, headGroup, r);
  ctx.headR = r;

  for (const side of [-1, 1]) {
    for (const z of [0.48, -0.48]) {
      const leg = new THREE.Group();
      leg.position.set(side * w * 0.62, 0.62, z * d);
      body.add(leg);
      part(ctx, S.capsule, mats.secondary, leg, [0, -0.22, 0], [0.105, 0.16, 0.105]);
      part(ctx, S.sphere, mats.primary, leg, [0, -0.5, 0.06], [0.14, 0.09, 0.2]);
      ctx.parts.legs.push({ group: leg, side });
    }
  }

  // Back spikes / fin
  const spikeCount = rng.int(2, 4);
  for (let i = 0; i < spikeCount; i++) {
    const z = d * 0.4 - i * (d * 0.3);
    if (ctx.type === 'verdant') {
      part(ctx, S.octa, mats.secondary, body, [0, 1.45, z], [0.12, 0.3, 0.08], [0.2, 0, 0]);
    } else if (ctx.type === 'tide') {
      part(ctx, S.cone4, mats.accent, body, [0, 1.46, z], [0.05, 0.32, 0.26], [0.15, 0, 0]);
    } else {
      part(ctx, S.cone, mats.secondary, body, [0, 1.42, z], [0.1, 0.28, 0.1], [-0.15, 0, 0]);
    }
  }

  addTail(ctx, new THREE.Vector3(0, 1.05, -d * 0.9), { segments: 4, width: 0.16, droop: 0.15 });
  if (ctx.type === 'lumen' || ctx.type === 'umbra' || ctx.type === 'verdant') {
    addWings(ctx, 1.36, -d * 0.3, 0.75);
  }
  return { height: 1.7 };
}

function buildSerpent(ctx) {
  const { body, mats, rng } = ctx;
  const group = new THREE.Group();
  body.add(group);
  ctx.parts.serpent = group;
  const count = rng.int(6, 8);
  let parent = group;
  const segs = [];
  for (let i = 0; i < count; i++) {
    const g = new THREE.Group();
    g.position.set(0, i === 0 ? 0.34 : 0.28, i === 0 ? 0 : 0.05);
    g.rotation.z = Math.sin(i * 0.9) * 0.16;
    g.rotation.x = i * 0.1;
    parent.add(g);
    const t = i / count;
    const size = 0.26 + Math.sin(t * Math.PI) * 0.18;
    part(ctx, S.sphere, i % 2 ? mats.secondary : mats.primary, g, [Math.sin(i * 1.1) * 0.12, 0, 0], [size, size * 0.92, size * 0.95]);
    segs.push(g);
    parent = g;
  }
  const headGroup = new THREE.Group();
  headGroup.position.set(0, 0.32, 0.06);
  parent.add(headGroup);
  ctx.parts.head = headGroup;
  const r = rng.float(0.34, 0.42);
  part(ctx, S.sphere, mats.primary, headGroup, [0, 0, 0], [r, r * 0.92, r * 0.9]);
  part(ctx, S.sphere, mats.secondary, headGroup, [0, -r * 0.24, r * 0.45], [r * 0.55, r * 0.32, r * 0.55]);
  addEyes(ctx, headGroup, r, { brow: false });
  addSnout(ctx, headGroup, r, { fangs: ctx.type === 'umbra' || ctx.type === 'tide', nose: true });
  addHornPair(ctx, headGroup, r, ctx.type === 'tide' ? 'fin' : 'crystal');
  addCrest(ctx, headGroup, r);
  ctx.headR = r;

  for (const side of [-1, 1]) {
    const fin = part(ctx, S.cone4, mats.accent, headGroup, [side * r * 0.72, r * 0.1, -r * 0.1], [r * 0.28, r * 0.55, r * 0.05], [0, 0, side * -1.1]);
    ctx.parts.ears = ctx.parts.ears || [];
    ctx.parts.ears.push(fin);
  }
  for (let i = 0; i < 3; i++) {
    part(ctx, S.octa, mats.accent, body, [0, 0.4 + i * 0.5, -0.1 - i * 0.06], [0.06, 0.18, 0.06], [0.2, 0, 0]);
  }
  return { height: 2.3 };
}

function buildFloater(ctx) {
  const { body, mats, rng } = ctx;
  const r = rng.float(0.48, 0.58);
  const coreY = 1.25;
  part(ctx, S.sphere, mats.primary, body, [0, coreY, 0], [r, r * 0.95, r]);
  part(ctx, S.sphere, mats.belly, body, [0, coreY - r * 0.2, r * 0.55], [r * 0.62, r * 0.55, r * 0.3]);
  addSpots(ctx, body, { x: r, y: r, z: r });

  const headGroup = new THREE.Group();
  headGroup.position.set(0, coreY + r * 0.92, 0);
  body.add(headGroup);
  ctx.parts.head = headGroup;
  const hr = rng.float(0.36, 0.42);
  part(ctx, S.sphere, mats.primary, headGroup, [0, 0, 0], [hr, hr * 0.95, hr * 0.9]);
  addEyes(ctx, headGroup, hr, { brow: false });
  addSnout(ctx, headGroup, hr * 0.85, { fangs: ctx.type === 'umbra', nose: true });
  addCrest(ctx, headGroup, hr);
  addHornPair(ctx, headGroup, hr, ctx.type === 'lumen' ? 'crystal' : 'fin');
  ctx.headR = hr;

  for (const side of [-1, 1]) {
    const arm = new THREE.Group();
    arm.position.set(side * r * 0.9, coreY + r * 0.1, 0.05);
    body.add(arm);
    part(ctx, S.capsule, mats.secondary, arm, [0, -0.18, 0], [0.08, 0.12, 0.08], [0, 0, side * 0.5]);
    part(ctx, S.sphere, mats.accent, arm, [side * 0.04, -0.34, 0], [0.09, 0.09, 0.09]);
    ctx.parts.arms.push({ group: arm, baseZ: 0, side });
  }

  // Wispy tail / lower body
  const tailGroup = new THREE.Group();
  tailGroup.position.set(0, coreY - r * 0.8, -0.05);
  body.add(tailGroup);
  ctx.parts.tails.push(tailGroup);
  for (let i = 0; i < 4; i++) {
    part(ctx, S.cone, i % 2 ? mats.secondary : mats.primary, tailGroup, [Math.sin(i * 1.2) * 0.1, -i * 0.24, -i * 0.03], [0.17 - i * 0.025, 0.26, 0.17 - i * 0.025], [Math.PI, 0, Math.sin(i) * 0.2]);
  }
  if (ctx.type === 'umbra' || ctx.type === 'lumen') addWings(ctx, coreY + 0.2, -r * 0.55, 0.95);

  // Orbiting motes
  const aura = new THREE.Group();
  aura.position.set(0, coreY, 0);
  body.add(aura);
  ctx.parts.aura = aura;
  const motes = rng.int(3, 5);
  for (let i = 0; i < motes; i++) {
    const a = (i / motes) * Math.PI * 2;
    const mote = part(ctx, S.sphere, mats.glow, aura, [Math.cos(a) * (r + 0.4), Math.sin(a * 2) * 0.4, Math.sin(a) * (r + 0.4)], [0.05, 0.05, 0.05]);
    mote.userData.orbit = a;
    mote.userData.radius = r + 0.35 + rng.float(0, 0.2);
    mote.userData.speed = rng.float(0.5, 1.2);
  }
  return { height: coreY + r + 0.9, float: true };
}

function buildInsect(ctx) {
  const { body, mats, rng } = ctx;
  const thoraxY = 1.12;
  part(ctx, S.sphere, mats.primary, body, [0, thoraxY, 0], [0.4, 0.42, 0.55]);
  part(ctx, S.sphere, mats.secondary, body, [0, thoraxY + 0.02, -0.62], [0.34, 0.3, 0.5]);
  part(ctx, S.sphere, mats.belly, body, [0, thoraxY - 0.24, 0.08], [0.28, 0.2, 0.42]);
  addSpots(ctx, body, { x: 0.4, y: 0.42, z: 0.55 });

  const headGroup = new THREE.Group();
  headGroup.position.set(0, thoraxY + 0.38, 0.5);
  body.add(headGroup);
  ctx.parts.head = headGroup;
  const r = rng.float(0.3, 0.36);
  part(ctx, S.sphere, mats.primary, headGroup, [0, 0, 0], [r, r, r * 0.92]);
  addEyes(ctx, headGroup, r, { brow: false });
  addSnout(ctx, headGroup, r * 0.9, { fangs: true, nose: true });
  addCrest(ctx, headGroup, r);
  ctx.headR = r;

  for (const side of [-1, 1]) {
    const antenna = new THREE.Group();
    antenna.position.set(side * r * 0.4, r * 0.6, 0);
    antenna.rotation.z = side * -0.4;
    headGroup.add(antenna);
    part(ctx, S.cylTaper, mats.secondary, antenna, [0, 0.22, 0], [0.025, 0.45, 0.025]);
    part(ctx, S.sphere, mats.glow, antenna, [0, 0.48, 0], [0.06, 0.06, 0.06]);
  }

  for (const side of [-1, 1]) {
    for (let i = 0; i < 2; i++) {
      const leg = new THREE.Group();
      leg.position.set(side * 0.3, thoraxY - 0.2, i === 0 ? 0.2 : -0.18);
      leg.rotation.z = side * 0.55;
      body.add(leg);
      part(ctx, S.capsule, mats.secondary, leg, [0, -0.2, 0], [0.05, 0.15, 0.05]);
      part(ctx, S.sphere, mats.primary, leg, [0, -0.38, 0.04], [0.07, 0.06, 0.12]);
      ctx.parts.legs.push({ group: leg, side });
    }
  }
  addWings(ctx, thoraxY + 0.3, -0.35, 1.05);
  addTail(ctx, new THREE.Vector3(0, thoraxY - 0.05, -0.9), { segments: 3, width: 0.14, droop: 0.12 });
  return { height: 1.85, float: true };
}

function decorate(ctx, bodyInfo) {
  const { body, mats, type, rng } = ctx;
  if (type === 'ember') {
    part(ctx, S.octa, mats.glow, body, [0, bodyInfo.height * 0.48, -0.15], [0.08, 0.16, 0.08]);
  } else if (type === 'verdant') {
    for (let i = 0; i < 2; i++) {
      part(ctx, S.octa, mats.secondary, body, [(i ? 1 : -1) * 0.38, bodyInfo.height * 0.52, -0.2], [0.14, 0.28, 0.07], [0.3, 0, (i ? 1 : -1) * 0.6]);
    }
  } else if (type === 'tide') {
    for (let i = 0; i < 3; i++) {
      part(ctx, S.box, mats.dark, body, [0.22, bodyInfo.height * 0.42 + i * 0.09, 0.22], [0.02, 0.015, 0.12]);
    }
  } else if (type === 'volt') {
    part(ctx, S.bolt, mats.glow, body, [-0.36, bodyInfo.height * 0.5, 0.1], [0.45, 0.45, 0.45], [0, 0, 0.3]);
  } else if (type === 'lumen') {
    part(ctx, S.torus, mats.glow, body, [0, bodyInfo.height * 0.3, -0.1], [0.36, 0.36, 0.3], [Math.PI / 2, 0, 0]);
  } else if (type === 'umbra') {
    for (let i = 0; i < 3; i++) {
      part(ctx, S.sphere, mats.glow, body, [rng.float(-0.4, 0.4), bodyInfo.height * rng.float(0.3, 0.6), -0.2], [0.035, 0.035, 0.035]);
    }
  }
}

export function createCreatureModel(creature) {
  const rng = new RNG(creature.seed + ':' + creature.id);
  const mats = buildMaterials(creature.colors);
  const root = new THREE.Group();
  root.name = `creature-${creature.name}`;
  const body = new THREE.Group();
  root.add(body);

  const ctx = {
    rng,
    mats,
    body,
    type: creature.type,
    parts: { arms: [], legs: [], tails: [], wings: [], eyes: [], aura: null },
    creature,
  };

  let info;
  switch (creature.body) {
    case 'quadruped': info = buildQuadruped(ctx); break;
    case 'serpent': info = buildSerpent(ctx); break;
    case 'floater': info = buildFloater(ctx); break;
    case 'insect': info = buildInsect(ctx); break;
    default: info = buildBiped(ctx);
  }
  decorate(ctx, info);

  const shadowMat = new THREE.MeshBasicMaterial({
    map: getShadowTexture(), transparent: true, opacity: 0.75, depthWrite: false,
  });
  const shadow = new THREE.Mesh(S.circle, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = 0.02;
  shadow.scale.setScalar(0.95);
  root.add(shadow);

  root.scale.setScalar(creature.scale || 1);

  const parts = ctx.parts;
  const phase = (creature.seed % 100) / 12;
  const baseBodyY = 0;
  const float = info.float;
  const hoverBase = float ? 0.06 : 0;

  const materials = Object.values(mats);

  function update(t, dt) {
    const bob = Math.sin(t * 1.7 + phase) * (float ? 0.06 : 0.035);
    body.position.y = hoverBase + bob;
    body.rotation.z = Math.sin(t * 1.05 + phase) * 0.018;
    if (parts.head) {
      parts.head.rotation.y = Math.sin(t * 0.75 + phase) * 0.09;
      parts.head.rotation.x = Math.sin(t * 1.25 + phase * 1.3) * 0.03;
    }
    for (const tail of parts.tails) {
      tail.rotation.y = Math.sin(t * 1.5 + phase) * 0.28;
      tail.rotation.z = Math.sin(t * 1.1 + phase * 0.7) * 0.08;
    }
    for (const arm of parts.arms) {
      arm.group.rotation.x = Math.sin(t * 1.5 + phase + arm.side) * 0.12;
      arm.group.rotation.z = arm.baseZ + Math.sin(t * 1.2 + phase) * 0.05;
    }
    for (const leg of parts.legs) {
      leg.group.rotation.x = Math.sin(t * 1.5 + phase + leg.side * 1.2) * 0.04;
    }
    for (const wing of parts.wings) {
      wing.group.rotation.z = wing.baseZ + Math.sin(t * 2.3 + phase) * 0.16 * wing.side;
      wing.group.rotation.y = wing.side * -0.75 + Math.sin(t * 1.7 + phase) * 0.08;
    }
    if (parts.serpent) {
      parts.serpent.rotation.y = Math.sin(t * 0.9 + phase) * 0.08;
      parts.serpent.rotation.z = Math.sin(t * 0.7 + phase) * 0.03;
    }
    if (parts.aura) {
      for (const mote of parts.aura.children) {
        const a = mote.userData.orbit + t * mote.userData.speed;
        const rr = mote.userData.radius;
        mote.position.set(Math.cos(a) * rr, Math.sin(a * 2 + phase) * 0.35, Math.sin(a) * rr);
      }
      parts.aura.rotation.y = t * 0.35;
    }
    const blink = (t + phase * 2.7) % 4.6;
    const eyeScale = blink > 4.45 ? 0.12 : 1;
    for (const eye of parts.eyes) {
      eye.scale.y = (eye.userData.baseScaleY ?? (eye.userData.baseScaleY = eye.scale.y)) * eyeScale;
    }
    const pulse = 0.92 + Math.sin(t * 2 + phase) * 0.18;
    for (const mat of [mats.accent, mats.glow]) {
      mat.emissiveIntensity = (mat.userData.baseIntensity || 0.5) * pulse;
    }
  }

  function setOpacity(o) {
    for (const m of materials) {
      if (!m.transparent) {
        m.transparent = true;
        m.depthWrite = o > 0.9;
      }
      m.opacity = o;
    }
  }

  function flash(color = '#ffffff', intensity = 0.9) {
    for (const m of materials) {
      m.emissive.set(color);
      m.emissiveIntensity = intensity;
    }
    setTimeout(() => {
      for (const m of materials) {
        m.emissive.copy(m.userData.baseEmissive);
        m.emissiveIntensity = m.userData.baseIntensity;
      }
    }, 130);
  }

  function dispose() {
    for (const m of materials) m.dispose();
    shadowMat.dispose();
  }

  return {
    creature,
    root,
    body,
    parts,
    materials,
    height: info.height,
    float: !!float,
    update,
    setOpacity,
    flash,
    dispose,
  };
}

export function disposeCreatureModel(model) {
  model.dispose();
  model.root.removeFromParent();
}

import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { RNG } from './rng.js';

let particleTexture = null;
export function getParticleTexture() {
  if (particleTexture) return particleTexture;
  const c = document.createElement('canvas');
  c.width = c.height = 64;
  const g = c.getContext('2d');
  const grad = g.createRadialGradient(32, 32, 0, 32, 32, 30);
  grad.addColorStop(0, 'rgba(255,255,255,1)');
  grad.addColorStop(0.3, 'rgba(255,255,255,0.85)');
  grad.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = grad;
  g.fillRect(0, 0, 64, 64);
  particleTexture = new THREE.CanvasTexture(c);
  return particleTexture;
}

function makeFloorTexture(theme, rng) {
  const size = 1024;
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const g = c.getContext('2d');
  g.clearRect(0, 0, size, size);
  const cx = size / 2;
  const cy = size / 2;
  const accent = theme.accent;
  const glow = theme.glow;

  const grad = g.createRadialGradient(cx, cy, 0, cx, cy, size / 2);
  grad.addColorStop(0, hexA(glow, 0.28));
  grad.addColorStop(0.28, hexA(accent, 0.1));
  grad.addColorStop(0.7, hexA(accent, 0.03));
  grad.addColorStop(1, 'rgba(0,0,0,0)');
  g.fillStyle = grad;
  g.fillRect(0, 0, size, size);

  g.strokeStyle = hexA(glow, 0.5);
  g.lineWidth = 3;
  for (let i = 0; i < 5; i++) {
    const r = 120 + i * 82;
    g.beginPath();
    g.arc(cx, cy, r, 0, Math.PI * 2);
    g.stroke();
  }

  // Radial spokes
  const spokes = 16;
  for (let i = 0; i < spokes; i++) {
    const a = (i / spokes) * Math.PI * 2;
    const inner = i % 2 === 0 ? 150 : 330;
    const outer = 470;
    g.strokeStyle = hexA(i % 4 === 0 ? glow : accent, 0.35);
    g.lineWidth = i % 4 === 0 ? 4 : 2;
    g.beginPath();
    g.moveTo(cx + Math.cos(a) * inner, cy + Math.sin(a) * inner);
    g.lineTo(cx + Math.cos(a) * outer, cy + Math.sin(a) * outer);
    g.stroke();
    // tick
    g.beginPath();
    g.arc(cx, cy, 460, a - 0.02, a + 0.02);
    g.lineWidth = 8;
    g.strokeStyle = hexA(accent, 0.4);
    g.stroke();
  }

  // Outer glyph ring
  for (let i = 0; i < 32; i++) {
    const a = (i / 32) * Math.PI * 2;
    const r = 420;
    const x = cx + Math.cos(a) * r;
    const y = cy + Math.sin(a) * r;
    g.save();
    g.translate(x, y);
    g.rotate(a + Math.PI / 2);
    g.strokeStyle = hexA(glow, 0.55);
    g.lineWidth = 2.5;
    g.beginPath();
    const kind = i % 4;
    if (kind === 0) { g.moveTo(-9, -12); g.lineTo(9, -12); g.lineTo(0, 12); g.closePath(); }
    else if (kind === 1) { g.moveTo(-8, 8); g.lineTo(0, -12); g.lineTo(8, 8); }
    else if (kind === 2) { g.arc(0, 0, 9, 0, Math.PI * 2); }
    else { g.moveTo(-10, 0); g.lineTo(10, 0); g.moveTo(0, -10); g.lineTo(0, 10); }
    g.stroke();
    g.restore();
  }

  // Center sigil: procedural polygon + inner rune
  const sides = rng.int(3, 6);
  const radius = 150;
  g.strokeStyle = hexA(glow, 0.85);
  g.lineWidth = 5;
  g.beginPath();
  for (let i = 0; i <= sides; i++) {
    const a = (i / sides) * Math.PI * 2 - Math.PI / 2;
    const x = cx + Math.cos(a) * radius;
    const y = cy + Math.sin(a) * radius;
    if (i === 0) g.moveTo(x, y);
    else g.lineTo(x, y);
  }
  g.stroke();
  g.strokeStyle = hexA(accent, 0.75);
  g.lineWidth = 3;
  for (let i = 0; i < sides; i++) {
    const a = (i / sides) * Math.PI * 2 - Math.PI / 2;
    const a2 = ((i + 2) / sides) * Math.PI * 2 - Math.PI / 2;
    g.beginPath();
    g.moveTo(cx + Math.cos(a) * radius, cy + Math.sin(a) * radius);
    g.lineTo(cx + Math.cos(a2) * radius, cy + Math.sin(a2) * radius);
    g.stroke();
  }
  g.beginPath();
  g.arc(cx, cy, 62, 0, Math.PI * 2);
  g.strokeStyle = hexA(glow, 0.9);
  g.lineWidth = 4;
  g.stroke();
  g.beginPath();
  g.arc(cx, cy, 22, 0, Math.PI * 2);
  g.fillStyle = hexA(glow, 0.18);
  g.fill();

  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  return tex;
}

function hexA(hex, alpha) {
  const h = hex.replace('#', '');
  const r = parseInt(h.slice(0, 2), 16);
  const g = parseInt(h.slice(2, 4), 16);
  const b = parseInt(h.slice(4, 6), 16);
  return `rgba(${r},${g},${b},${alpha})`;
}

function makeBannerTexture(theme, rng, index) {
  const w = 256;
  const h = 512;
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  const g = c.getContext('2d');
  const grad = g.createLinearGradient(0, 0, 0, h);
  grad.addColorStop(0, theme.stoneDark);
  grad.addColorStop(0.5, theme.stone);
  grad.addColorStop(1, theme.stoneDark);
  g.fillStyle = grad;
  g.fillRect(0, 0, w, h);

  g.strokeStyle = hexA(theme.accent, 0.55);
  g.lineWidth = 6;
  g.strokeRect(14, 14, w - 28, h - 28);
  g.lineWidth = 2;
  g.strokeRect(26, 26, w - 52, h - 52);

  g.strokeStyle = hexA(theme.glow, 0.8);
  g.lineWidth = 4;
  g.beginPath();
  g.arc(w / 2, 160, 72, 0, Math.PI * 2);
  g.stroke();

  const sides = rng.int(3, 6);
  g.beginPath();
  for (let i = 0; i <= sides; i++) {
    const a = (i / sides) * Math.PI * 2 - Math.PI / 2;
    const x = w / 2 + Math.cos(a) * 58;
    const y = 160 + Math.sin(a) * 58;
    if (i === 0) g.moveTo(x, y);
    else g.lineTo(x, y);
  }
  g.strokeStyle = hexA(theme.accent, 0.9);
  g.lineWidth = 3;
  g.stroke();

  g.fillStyle = hexA(theme.glow, 0.9);
  g.beginPath();
  g.arc(w / 2, 160, 14, 0, Math.PI * 2);
  g.fill();

  for (let i = 0; i < 5; i++) {
    const y = 285 + i * 34;
    g.strokeStyle = hexA(theme.accent, 0.45 - i * 0.05);
    g.lineWidth = 2;
    g.beginPath();
    g.moveTo(50, y);
    g.lineTo(w - 50, y);
    g.stroke();
    g.beginPath();
    g.moveTo(50, y - 6);
    g.lineTo(50, y + 6);
    g.moveTo(w - 50, y - 6);
    g.lineTo(w - 50, y + 6);
    g.stroke();
  }

  for (let i = 0; i < 7; i++) {
    const x = 32 + i * 32;
    g.strokeStyle = hexA(theme.glow, 0.4);
    g.lineWidth = 2;
    g.beginPath();
    g.moveTo(x, h - 60);
    g.lineTo(x + 8, h - 24);
    g.stroke();
  }

  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function makePortalTexture(theme, rng) {
  const size = 512;
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const g = c.getContext('2d');
  const cx = size / 2;
  const cy = size / 2;
  const grad = g.createRadialGradient(cx, cy, 10, cx, cy, 250);
  grad.addColorStop(0, hexA(theme.glow, 0.95));
  grad.addColorStop(0.22, hexA(theme.accent, 0.6));
  grad.addColorStop(0.5, hexA(theme.accent, 0.18));
  grad.addColorStop(0.8, hexA(theme.stoneDark, 0.05));
  grad.addColorStop(1, 'rgba(0,0,0,0)');
  g.fillStyle = grad;
  g.fillRect(0, 0, size, size);

  for (let i = 0; i < 9; i++) {
    const r = 30 + i * 23;
    g.strokeStyle = hexA(i % 2 ? theme.glow : theme.accent, 0.5 - i * 0.03);
    g.lineWidth = 1.5 + (i % 3);
    g.beginPath();
    const start = rng.float(0, Math.PI * 2);
    g.arc(cx, cy, r, start, start + rng.float(1.6, 4.6));
    g.stroke();
  }
  for (let i = 0; i < 22; i++) {
    const a = rng.float(0, Math.PI * 2);
    const r = rng.float(50, 235);
    g.fillStyle = hexA(theme.glow, rng.float(0.25, 0.8));
    g.beginPath();
    g.arc(cx + Math.cos(a) * r, cy + Math.sin(a) * r, rng.float(1, 3.5), 0, Math.PI * 2);
    g.fill();
  }
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function makeStarTexture() {
  const c = document.createElement('canvas');
  c.width = c.height = 32;
  const g = c.getContext('2d');
  const grad = g.createRadialGradient(16, 16, 0, 16, 16, 15);
  grad.addColorStop(0, 'rgba(255,255,255,1)');
  grad.addColorStop(0.4, 'rgba(255,255,255,0.5)');
  grad.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = grad;
  g.fillRect(0, 0, 32, 32);
  return new THREE.CanvasTexture(c);
}

function makeStoneMat(color, roughness = 0.85) {
  return new THREE.MeshStandardMaterial({ color, roughness, metalness: 0.08, flatShading: true });
}

export function createRoom(scene, config) {
  const rng = new RNG(config.seed + ':geometry');
  const theme = config.theme;
  const group = new THREE.Group();
  group.name = 'rift-room';
  scene.add(group);

  const stoneMat = makeStoneMat(theme.stone);
  const stoneDarkMat = makeStoneMat(theme.stoneDark, 0.92);
  const accentMat = new THREE.MeshStandardMaterial({
    color: theme.accent, emissive: theme.accent, emissiveIntensity: 0.7, roughness: 0.4, metalness: 0.3,
  });
  const glowMat = new THREE.MeshStandardMaterial({
    color: theme.glow, emissive: theme.glow, emissiveIntensity: 1.4, roughness: 0.3,
  });
  const metalMat = new THREE.MeshStandardMaterial({
    color: theme.secondary, roughness: 0.35, metalness: 0.65,
  });

  // Lighting
  const hemi = new THREE.HemisphereLight(theme.light, theme.stoneDark, 0.85);
  group.add(hemi);
  const key = new THREE.DirectionalLight(theme.light, theme.lightIntensity);
  key.position.set(7, 15, 9);
  group.add(key);
  const rim = new THREE.DirectionalLight(theme.accent, 1.1);
  rim.position.set(-9, 7, -11);
  group.add(rim);
  const portalLight = new THREE.PointLight(theme.accent, 90, 34, 2);
  portalLight.position.set(0, 4.8, -8.6);
  group.add(portalLight);

  // Dome & backdrop
  const dome = new THREE.Mesh(
    new THREE.SphereGeometry(23, 24, 14, 0, Math.PI * 2, 0, Math.PI / 2),
    new THREE.MeshStandardMaterial({ color: theme.sky, roughness: 1, side: THREE.BackSide }),
  );
  dome.position.y = -0.4;
  group.add(dome);

  // Floor
  const floor = new THREE.Mesh(new THREE.CylinderGeometry(9.6, 10.1, 0.8, 48), stoneMat);
  floor.position.y = -0.4;
  group.add(floor);
  const floorTop = new THREE.Mesh(new THREE.CircleGeometry(9.55, 64), stoneDarkMat);
  floorTop.rotation.x = -Math.PI / 2;
  floorTop.position.y = 0.005;
  group.add(floorTop);

  const floorTex = makeFloorTexture(theme, rng);
  const runeDisc = new THREE.Mesh(
    new THREE.CircleGeometry(9.4, 64),
    new THREE.MeshBasicMaterial({ map: floorTex, transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending, depthWrite: false }),
  );
  runeDisc.rotation.x = -Math.PI / 2;
  runeDisc.position.y = 0.018;
  group.add(runeDisc);

  const rimRing = new THREE.Mesh(new THREE.TorusGeometry(9.55, 0.14, 8, 64), accentMat);
  rimRing.rotation.x = -Math.PI / 2;
  rimRing.position.y = 0.14;
  group.add(rimRing);

  const walkway = new THREE.Mesh(new THREE.RingGeometry(9.6, 14.6, 64), stoneDarkMat);
  walkway.rotation.x = -Math.PI / 2;
  walkway.position.y = -0.12;
  group.add(walkway);

  // Outer wall
  const wall = new THREE.Mesh(
    new THREE.CylinderGeometry(15.1, 15.1, 13, 48, 1, true),
    new THREE.MeshStandardMaterial({ color: theme.stoneDark, roughness: 0.96, side: THREE.BackSide, flatShading: true }),
  );
  wall.position.y = 6.4;
  group.add(wall);

  const wallRibs = new THREE.InstancedMesh(new THREE.BoxGeometry(0.45, 12, 0.9), stoneMat, 24);
  const m4 = new THREE.Matrix4();
  const q = new THREE.Quaternion();
  for (let i = 0; i < 24; i++) {
    const a = (i / 24) * Math.PI * 2;
    const x = Math.cos(a) * 14.7;
    const z = Math.sin(a) * 14.7;
    q.setFromEuler(new THREE.Euler(0, -a + Math.PI / 2, 0));
    m4.compose(new THREE.Vector3(x, 6, z), q, new THREE.Vector3(1, 1, 1));
    wallRibs.setMatrixAt(i, m4);
  }
  group.add(wallRibs);

  const upperRing = new THREE.Mesh(new THREE.TorusGeometry(14.5, 0.22, 8, 64), metalMat);
  upperRing.rotation.x = -Math.PI / 2;
  upperRing.position.y = 7.8;
  group.add(upperRing);
  const midRing = new THREE.Mesh(new THREE.TorusGeometry(14.8, 0.12, 6, 64), accentMat);
  midRing.rotation.x = -Math.PI / 2;
  midRing.position.y = 4.2;
  group.add(midRing);

  // Pillars (merged stone geometry)
  const pillarGeos = [];
  const pillarPositions = [];
  const count = config.pillarCount;
  for (let i = 0; i < count; i++) {
    const a = (i / count) * Math.PI * 2 + 0.15;
    const r = 11.9;
    const x = Math.cos(a) * r;
    const z = Math.sin(a) * r;
    pillarPositions.push({ x, z, a });
    const base = new THREE.BoxGeometry(1.6, 0.5, 1.6);
    base.translate(x, 0.25, z);
    pillarGeos.push(base);
    const column = new THREE.CylinderGeometry(0.34, 0.44, 6.4, 8);
    column.translate(x, 3.45, z);
    pillarGeos.push(column);
    const cap = new THREE.BoxGeometry(1.25, 0.38, 1.25);
    cap.translate(x, 6.75, z);
    pillarGeos.push(cap);
    const cap2 = new THREE.BoxGeometry(0.9, 0.3, 0.9);
    cap2.translate(x, 7.06, z);
    pillarGeos.push(cap2);
  }
  const pillarMesh = new THREE.Mesh(mergeGeometries(pillarGeos), stoneMat);
  group.add(pillarMesh);

  const orbGeo = new THREE.SphereGeometry(0.24, 10, 8);
  const orbs = new THREE.InstancedMesh(orbGeo, glowMat, count);
  for (let i = 0; i < count; i++) {
    const p = pillarPositions[i];
    m4.makeTranslation(p.x, 7.4, p.z);
    orbs.setMatrixAt(i, m4);
  }
  group.add(orbs);

  const torchPositions = [];
  for (let i = 0; i < count; i += 2) {
    const p = pillarPositions[i];
    torchPositions.push(p);
  }

  // Banners
  const banners = [];
  const bannerCount = Math.min(config.bannerCount, count);
  for (let i = 0; i < bannerCount; i++) {
    const p = pillarPositions[(i * 2 + 1) % count];
    const tex = makeBannerTexture(theme, rng, i);
    const mat = new THREE.MeshBasicMaterial({ map: tex, side: THREE.DoubleSide, transparent: true, opacity: 0.96 });
    const banner = new THREE.Mesh(new THREE.PlaneGeometry(2.6, 5.2, 1, 4), mat);
    const a = p.a + (Math.PI / count);
    banner.position.set(Math.cos(a) * 14.25, 4.9, Math.sin(a) * 14.25);
    banner.rotation.y = -a + Math.PI / 2;
    banner.userData.phase = rng.float(0, 6);
    banner.userData.baseRot = banner.rotation.y;
    group.add(banner);
    banners.push(banner);
  }

  // Portal
  const portal = new THREE.Group();
  portal.position.set(0, 4.7, -10.8);
  group.add(portal);
  const portalRing = new THREE.Mesh(new THREE.TorusGeometry(3.15, 0.3, 10, 48), accentMat);
  portal.add(portalRing);
  const portalRing2 = new THREE.Mesh(new THREE.TorusGeometry(3.65, 0.1, 6, 48), metalMat);
  portal.add(portalRing2);
  const portalTex = makePortalTexture(theme, rng);
  const portalDisc = new THREE.Mesh(
    new THREE.CircleGeometry(2.98, 48),
    new THREE.MeshBasicMaterial({ map: portalTex, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0.9 }),
  );
  portal.add(portalDisc);
  const portalRunes = [];
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * Math.PI * 2;
    const rune = new THREE.Mesh(new THREE.OctahedronGeometry(0.16, 0), glowMat);
    rune.position.set(Math.cos(a) * 3.9, Math.sin(a) * 3.9, 0.1);
    rune.userData.a = a;
    portal.add(rune);
    portalRunes.push(rune);
  }

  // Floating crystals
  const crystals = [];
  const crystalMats = [accentMat, glowMat, metalMat];
  for (let i = 0; i < config.crystalCount; i++) {
    const a = rng.float(0, Math.PI * 2);
    const r = rng.float(4.6, 12.6);
    const geo = rng.chance(0.5) ? new THREE.OctahedronGeometry(rng.float(0.18, 0.5), 0) : new THREE.ConeGeometry(rng.float(0.15, 0.3), rng.float(0.5, 1.2), 5);
    const crystal = new THREE.Mesh(geo, crystalMats[i % 3]);
    crystal.position.set(Math.cos(a) * r, rng.float(1.4, 8.6), Math.sin(a) * r);
    crystal.rotation.set(rng.float(0, 3), rng.float(0, 3), rng.float(0, 3));
    crystal.userData.baseY = crystal.position.y;
    crystal.userData.phase = rng.float(0, 6.28);
    crystal.userData.spin = rng.float(0.15, 0.5);
    group.add(crystal);
    crystals.push(crystal);
  }

  // Braziers with flame + light
  const flames = [];
  const torchLights = [];
  for (let i = 0; i < Math.min(4, torchPositions.length); i++) {
    const p = torchPositions[i];
    const a = Math.atan2(p.z, p.x);
    const x = Math.cos(a) * 9.0;
    const z = Math.sin(a) * 9.0;
    const stand = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.3, 1.3, 6), metalMat);
    stand.position.set(x, 0.65, z);
    group.add(stand);
    const bowl = new THREE.Mesh(new THREE.CylinderGeometry(0.55, 0.3, 0.35, 8), stoneMat);
    bowl.position.set(x, 1.36, z);
    group.add(bowl);
    const flame = new THREE.Mesh(new THREE.ConeGeometry(0.3, 0.85, 6), glowMat);
    flame.position.set(x, 1.95, z);
    group.add(flame);
    flame.userData.phase = rng.float(0, 6.28);
    flames.push(flame);
    if (i < 2) {
      const light = new THREE.PointLight(theme.accent, 26, 14, 2);
      light.position.set(x, 2.3, z);
      light.userData.base = 26;
      light.userData.phase = rng.float(0, 6.28);
      group.add(light);
      torchLights.push(light);
    }
  }

  // Stars
  const starGeo = new THREE.BufferGeometry();
  const starPos = [];
  for (let i = 0; i < 260; i++) {
    const a = rng.float(0, Math.PI * 2);
    const r = rng.float(12, 21);
    const y = rng.float(8, 20);
    starPos.push(Math.cos(a) * r, y, Math.sin(a) * r);
  }
  starGeo.setAttribute('position', new THREE.Float32BufferAttribute(starPos, 3));
  const starMat = new THREE.PointsMaterial({
    size: 0.18, map: makeStarTexture(), transparent: true, opacity: 0.85,
    blending: THREE.AdditiveBlending, depthWrite: false, color: theme.glow, sizeAttenuation: true,
  });
  const stars = new THREE.Points(starGeo, starMat);
  group.add(stars);

  // Dust motes
  const moteGeo = new THREE.BufferGeometry();
  const motePos = [];
  for (let i = 0; i < config.motes; i++) {
    const a = rng.float(0, Math.PI * 2);
    const r = rng.float(2, 13);
    motePos.push(Math.cos(a) * r, rng.float(0.4, 10), Math.sin(a) * r);
  }
  moteGeo.setAttribute('position', new THREE.Float32BufferAttribute(motePos, 3));
  const moteMat = new THREE.PointsMaterial({
    size: 0.09, map: getParticleTexture(), transparent: true, opacity: 0.55,
    blending: THREE.AdditiveBlending, depthWrite: false, color: theme.glow, sizeAttenuation: true,
  });
  const motes = new THREE.Points(moteGeo, moteMat);
  group.add(motes);

  const textures = [floorTex, portalTex, starMat.map, moteMat.map];

  function update(t, dt) {
    portalDisc.rotation.z += dt * 0.16;
    portalRing.rotation.z -= dt * 0.05;
    portalDisc.scale.setScalar(1 + Math.sin(t * 0.8) * 0.015);
    for (const rune of portalRunes) {
      const a = rune.userData.a + t * 0.12;
      rune.position.set(Math.cos(a) * 3.9, Math.sin(a) * 3.9, 0.1);
      rune.rotation.y = t * 0.5;
    }
    for (const crystal of crystals) {
      crystal.position.y = crystal.userData.baseY + Math.sin(t * 0.8 + crystal.userData.phase) * 0.25;
      crystal.rotation.y += dt * crystal.userData.spin;
      crystal.rotation.x += dt * crystal.userData.spin * 0.4;
    }
    for (const flame of flames) {
      const s = 1 + Math.sin(t * 7 + flame.userData.phase) * 0.16;
      flame.scale.set(s, s * (1 + Math.sin(t * 9) * 0.1), s);
      flame.rotation.y = t * 0.7;
    }
    for (const light of torchLights) {
      light.intensity = light.userData.base * (0.86 + Math.sin(t * 7.5 + light.userData.phase) * 0.16);
    }
    for (const banner of banners) {
      banner.rotation.y = banner.userData.baseRot + Math.sin(t * 0.7 + banner.userData.phase) * 0.012;
    }
    motes.rotation.y = t * 0.012;
    stars.rotation.y = t * 0.004;
    runeDisc.material.opacity = 0.85 + Math.sin(t * 1.2) * 0.08;
    rimRing.material.emissiveIntensity = 0.55 + Math.sin(t * 1.6) * 0.18;
  }

  function dispose() {
    scene.remove(group);
    group.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
        for (const m of mats) {
          if (m.map) m.map.dispose();
          m.dispose();
        }
      }
    });
    for (const tex of textures) tex.dispose();
  }

  return { group, update, dispose, theme, portal, crystals };
}

export function createSelectStage(scene, config) {
  const theme = config.theme;
  const group = new THREE.Group();
  scene.add(group);
  const stoneMat = makeStoneMat(theme.stone);
  const darkMat = makeStoneMat(theme.stoneDark);
  const accentMat = new THREE.MeshStandardMaterial({
    color: theme.accent, emissive: theme.accent, emissiveIntensity: 0.9, roughness: 0.4,
  });
  const glowMat = new THREE.MeshStandardMaterial({
    color: theme.glow, emissive: theme.glow, emissiveIntensity: 1.5, roughness: 0.3,
  });
  const pedestals = [];
  const positions = [-4.6, 0, 4.6];
  for (let i = 0; i < 3; i++) {
    const g = new THREE.Group();
    g.position.set(positions[i], 0, -1.6);
    const base = new THREE.Mesh(new THREE.CylinderGeometry(1.15, 1.35, 0.5, 8), stoneMat);
    base.position.y = 0.25;
    g.add(base);
    const top = new THREE.Mesh(new THREE.CylinderGeometry(1.0, 1.1, 0.25, 8), darkMat);
    top.position.y = 0.62;
    g.add(top);
    const ring = new THREE.Mesh(new THREE.TorusGeometry(0.88, 0.05, 6, 32), accentMat.clone());
    ring.rotation.x = -Math.PI / 2;
    ring.position.y = 0.76;
    g.add(ring);
    const glow = new THREE.Mesh(new THREE.CircleGeometry(0.72, 24), new THREE.MeshBasicMaterial({
      color: theme.glow, transparent: true, opacity: 0.28, blending: THREE.AdditiveBlending, depthWrite: false,
    }));
    glow.rotation.x = -Math.PI / 2;
    glow.position.y = 0.755;
    g.add(glow);
    group.add(g);
    pedestals.push({ group: g, ring, glow, baseY: 0.75, selected: false });
  }

  function update(t) {
    for (const p of pedestals) {
      const pulse = p.selected ? 1.4 + Math.sin(t * 4) * 0.5 : 0.7 + Math.sin(t * 1.6) * 0.2;
      p.ring.material.emissiveIntensity = pulse;
      p.glow.material.opacity = p.selected ? 0.5 + Math.sin(t * 3) * 0.15 : 0.2;
    }
  }

  function dispose() {
    scene.remove(group);
    group.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) obj.material.dispose();
    });
  }

  return { group, pedestals, update, dispose };
}

import * as THREE from 'three';
import { getParticleTexture } from './room.js';

function hexToRgb(hex) {
  const h = hex.replace('#', '');
  return {
    r: parseInt(h.slice(0, 2), 16) / 255,
    g: parseInt(h.slice(2, 4), 16) / 255,
    b: parseInt(h.slice(4, 6), 16) / 255,
  };
}

export class Effects {
  constructor(scene, camera, floaterLayer) {
    this.scene = scene;
    this.camera = camera;
    this.floaterLayer = floaterLayer;
    this.bursts = [];
    this.rings = [];
    this.beams = [];
    this.projectiles = [];
    this.slashes = [];
    this.trailTimer = 0;
  }

  burst(position, color, opts = {}) {
    const count = opts.count ?? 26;
    const speed = opts.speed ?? 3.2;
    const life = opts.life ?? 0.8;
    const size = opts.size ?? 0.14;
    const gravity = opts.gravity ?? 3.2;
    const spread = opts.spread ?? 1;
    const positions = new Float32Array(count * 3);
    const velocities = new Float32Array(count * 3);
    for (let i = 0; i < count; i++) {
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(2 * Math.random() - 1);
      const v = speed * (0.35 + Math.random() * 0.9);
      velocities[i * 3] = Math.sin(phi) * Math.cos(theta) * v * spread;
      velocities[i * 3 + 1] = Math.cos(phi) * v * 0.75 + (opts.up ?? 1.2);
      velocities[i * 3 + 2] = Math.sin(phi) * Math.sin(theta) * v * spread;
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const mat = new THREE.PointsMaterial({
      map: getParticleTexture(), color, size, transparent: true, opacity: 1,
      blending: THREE.AdditiveBlending, depthWrite: false, sizeAttenuation: true,
    });
    const points = new THREE.Points(geo, mat);
    points.position.copy(position);
    this.scene.add(points);
    this.bursts.push({ points, velocities, life, age: 0, gravity, baseSize: size });
  }

  aura(position, color, opts = {}) {
    const count = opts.count ?? 22;
    const life = opts.life ?? 1.2;
    const radius = opts.radius ?? 0.8;
    const positions = new Float32Array(count * 3);
    const velocities = new Float32Array(count * 3);
    const phases = new Float32Array(count);
    for (let i = 0; i < count; i++) {
      const a = Math.random() * Math.PI * 2;
      const r = radius * (0.4 + Math.random() * 0.6);
      positions[i * 3] = Math.cos(a) * r;
      positions[i * 3 + 1] = Math.random() * 0.4;
      positions[i * 3 + 2] = Math.sin(a) * r;
      velocities[i * 3] = Math.cos(a) * 0.2;
      velocities[i * 3 + 1] = 0.9 + Math.random() * 1.5;
      velocities[i * 3 + 2] = Math.sin(a) * 0.2;
      phases[i] = Math.random() * Math.PI * 2;
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const mat = new THREE.PointsMaterial({
      map: getParticleTexture(), color, size: opts.size ?? 0.1, transparent: true, opacity: 1,
      blending: THREE.AdditiveBlending, depthWrite: false, sizeAttenuation: true,
    });
    const points = new THREE.Points(geo, mat);
    points.position.copy(position);
    this.scene.add(points);
    this.bursts.push({ points, velocities, life, age: 0, gravity: -0.2, baseSize: opts.size ?? 0.1, phases, spiral: true });
  }

  ring(position, color, opts = {}) {
    const life = opts.life ?? 0.6;
    const radius = opts.radius ?? 1.2;
    const mat = new THREE.MeshBasicMaterial({
      color, transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending,
      side: THREE.DoubleSide, depthWrite: false,
    });
    const mesh = new THREE.Mesh(new THREE.RingGeometry(0.72, 1, 48), mat);
    mesh.position.copy(position);
    if (opts.flat) {
      mesh.rotation.x = -Math.PI / 2;
    } else {
      mesh.quaternion.copy(this.camera.quaternion);
    }
    mesh.scale.setScalar(0.2);
    this.scene.add(mesh);
    this.rings.push({ mesh, life, age: 0, radius, flat: !!opts.flat });
  }

  beam(from, to, color, opts = {}) {
    const start = from.clone();
    const end = to.clone();
    const dir = end.clone().sub(start);
    const len = dir.length();
    const mat = new THREE.MeshBasicMaterial({
      color, transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending, depthWrite: false,
    });
    const mesh = new THREE.Mesh(new THREE.CylinderGeometry(opts.width ?? 0.12, opts.width ?? 0.12, 1, 6, 1, true), mat);
    mesh.position.copy(start).add(end).multiplyScalar(0.5);
    mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
    mesh.scale.set(1, len, 1);
    this.scene.add(mesh);
    this.beams.push({ mesh, life: opts.life ?? 0.32, age: 0 });
    this.burst(start, color, { count: 10, speed: 2, size: 0.1, life: 0.4, up: 0.5 });
    this.burst(end, color, { count: 18, speed: 3, size: 0.12, life: 0.5 });
  }

  slash(position, color, dir = 1) {
    for (let i = 0; i < 3; i++) {
      const mat = new THREE.MeshBasicMaterial({
        color, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending,
        side: THREE.DoubleSide, depthWrite: false,
      });
      const mesh = new THREE.Mesh(new THREE.PlaneGeometry(2.1, 0.12), mat);
      mesh.position.copy(position);
      mesh.position.y += (i - 1) * 0.22;
      mesh.position.z += 0.15;
      mesh.rotation.z = (0.7 + i * 0.22) * dir;
      mesh.quaternion.copy(this.camera.quaternion).multiply(mesh.quaternion);
      mesh.scale.set(0.2, 1, 1);
      this.scene.add(mesh);
      this.slashes.push({ mesh, life: 0.3, age: 0, delay: i * 0.035 });
    }
    this.burst(position, color, { count: 16, speed: 4, size: 0.1, life: 0.4 });
  }

  projectile(from, to, color, opts = {}) {
    const duration = opts.duration ?? 0.5;
    const size = opts.size ?? 0.18;
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1 });
    const mesh = new THREE.Mesh(new THREE.SphereGeometry(size, 10, 8), mat);
    const glow = new THREE.Mesh(
      new THREE.SphereGeometry(size * 2.1, 10, 8),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.22, blending: THREE.AdditiveBlending, depthWrite: false }),
    );
    mesh.add(glow);
    mesh.position.copy(from);
    this.scene.add(mesh);
    return new Promise((resolve) => {
      this.projectiles.push({
        mesh, from: from.clone(), to: to.clone(), color, duration, age: 0, resolve,
        arc: opts.arc ?? 1.6, trail: 0,
      });
    });
  }

  floater(worldPos, text, className = '') {
    const v = worldPos.clone().project(this.camera);
    const x = (v.x * 0.5 + 0.5) * window.innerWidth;
    const y = (-v.y * 0.5 + 0.5) * window.innerHeight;
    const el = document.createElement('div');
    el.className = `floater ${className}`;
    el.textContent = text;
    el.style.left = `${x}px`;
    el.style.top = `${y}px`;
    this.floaterLayer.appendChild(el);
    setTimeout(() => el.remove(), 1500);
  }

  update(dt) {
    for (let i = this.bursts.length - 1; i >= 0; i--) {
      const b = this.bursts[i];
      b.age += dt;
      const p = b.age / b.life;
      if (p >= 1) {
        this.scene.remove(b.points);
        b.points.geometry.dispose();
        b.points.material.dispose();
        this.bursts.splice(i, 1);
        continue;
      }
      const arr = b.points.geometry.attributes.position.array;
      for (let j = 0; j < arr.length / 3; j++) {
        arr[j * 3] += b.velocities[j * 3] * dt;
        arr[j * 3 + 1] += b.velocities[j * 3 + 1] * dt;
        arr[j * 3 + 2] += b.velocities[j * 3 + 2] * dt;
        if (b.spiral) {
          const a = b.phases[j] + b.age * 2.2;
          arr[j * 3] += Math.cos(a) * dt * 0.4;
          arr[j * 3 + 2] += Math.sin(a) * dt * 0.4;
        }
        b.velocities[j * 3 + 1] -= b.gravity * dt;
      }
      b.points.geometry.attributes.position.needsUpdate = true;
      b.points.material.opacity = Math.pow(1 - p, 1.4);
      b.points.material.size = b.baseSize * (1 - p * 0.4);
    }

    for (let i = this.rings.length - 1; i >= 0; i--) {
      const r = this.rings[i];
      r.age += dt;
      const p = r.age / r.life;
      if (p >= 1) {
        this.scene.remove(r.mesh);
        r.mesh.geometry.dispose();
        r.mesh.material.dispose();
        this.rings.splice(i, 1);
        continue;
      }
      r.mesh.scale.setScalar(0.2 + p * r.radius * 2.4);
      r.mesh.material.opacity = (1 - p) * 0.9;
    }

    for (let i = this.beams.length - 1; i >= 0; i--) {
      const b = this.beams[i];
      b.age += dt;
      const p = b.age / b.life;
      if (p >= 1) {
        this.scene.remove(b.mesh);
        b.mesh.geometry.dispose();
        b.mesh.material.dispose();
        this.beams.splice(i, 1);
        continue;
      }
      b.mesh.material.opacity = (1 - p) * 0.95;
      b.mesh.scale.x = 1 + Math.sin(p * Math.PI) * 0.8;
      b.mesh.scale.z = 1 + Math.sin(p * Math.PI) * 0.8;
    }

    for (let i = this.slashes.length - 1; i >= 0; i--) {
      const s = this.slashes[i];
      s.age += dt;
      const local = s.age - s.delay;
      if (local < 0) continue;
      const p = local / s.life;
      if (p >= 1) {
        this.scene.remove(s.mesh);
        s.mesh.geometry.dispose();
        s.mesh.material.dispose();
        this.slashes.splice(i, 1);
        continue;
      }
      s.mesh.scale.x = 0.2 + p * 1.1;
      s.mesh.material.opacity = (1 - p) * 0.9;
    }

    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i];
      p.age += dt;
      const t = Math.min(1, p.age / p.duration);
      const ease = t * t * (3 - 2 * t);
      const mid = p.from.clone().add(p.to).multiplyScalar(0.5);
      mid.y += p.arc;
      const a = p.from.clone().lerp(mid, ease);
      const b = mid.clone().lerp(p.to, ease);
      p.mesh.position.copy(a.lerp(b, ease));
      p.trail += dt;
      if (p.trail > 0.035) {
        p.trail = 0;
        this.burst(p.mesh.position, p.color, { count: 3, speed: 0.7, size: 0.1, life: 0.32, up: 0, gravity: 0, spread: 0.4 });
      }
      if (t >= 1) {
        this.scene.remove(p.mesh);
        p.mesh.geometry.dispose();
        p.mesh.material.dispose();
        p.mesh.children.forEach((c) => { c.geometry.dispose(); c.material.dispose(); });
        this.projectiles.splice(i, 1);
        p.resolve();
      }
    }
  }

  clear() {
    for (const list of [this.bursts, this.rings, this.beams, this.slashes, this.projectiles]) {
      for (const item of list) {
        const obj = item.points || item.mesh;
        if (obj) {
          this.scene.remove(obj);
          obj.geometry?.dispose();
          if (Array.isArray(obj.material)) obj.material.forEach((m) => m.dispose());
          else obj.material?.dispose();
        }
        item.resolve?.();
      }
      list.length = 0;
    }
    this.floaterLayer.innerHTML = '';
  }
}

const TYPE_PITCH = {
  ember: 180, verdant: 240, tide: 320, volt: 420, lumen: 520, umbra: 140,
};

export class GameAudio {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.ambient = null;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.32;
    this.master.connect(this.ctx.destination);
    this.startAmbient();
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master) this.master.gain.setTargetAtTime(muted ? 0 : 0.32, this.ctx.currentTime, 0.05);
  }

  tone({ freq = 440, dur = 0.18, type = 'sine', gain = 0.2, slide = 0, delay = 0, filter = 0 }) {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    let node = osc;
    if (filter) {
      const f = this.ctx.createBiquadFilter();
      f.type = 'lowpass';
      f.frequency.value = filter;
      osc.connect(f);
      node = f;
    }
    node.connect(g);
    g.connect(this.master);
    osc.start(t);
    osc.stop(t + dur + 0.02);
  }

  noise({ dur = 0.2, gain = 0.2, delay = 0, lowpass = 1400, highpass = 0 }) {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime + delay;
    const len = Math.max(1, Math.floor(this.ctx.sampleRate * dur));
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / len);
    const src = this.ctx.createBufferSource();
    src.buffer = buf;
    const f = this.ctx.createBiquadFilter();
    f.type = 'lowpass';
    f.frequency.value = lowpass;
    const hp = this.ctx.createBiquadFilter();
    hp.type = 'highpass';
    hp.frequency.value = highpass;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(gain, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(f);
    f.connect(hp);
    hp.connect(g);
    g.connect(this.master);
    src.start(t);
    src.stop(t + dur + 0.02);
  }

  click() {
    this.tone({ freq: 620, dur: 0.06, type: 'triangle', gain: 0.09, slide: -120 });
  }

  hover() {
    this.tone({ freq: 880, dur: 0.035, type: 'sine', gain: 0.03 });
  }

  select() {
    this.tone({ freq: 420, dur: 0.09, type: 'triangle', gain: 0.11 });
    this.tone({ freq: 630, dur: 0.12, type: 'triangle', gain: 0.09, delay: 0.06 });
  }

  confirm() {
    [392, 523, 659].forEach((f, i) => this.tone({ freq: f, dur: 0.22, type: 'triangle', gain: 0.1, delay: i * 0.07 }));
  }

  cry(type, seed = 1) {
    if (!this.ctx || this.muted) return;
    const base = (TYPE_PITCH[type] || 260) * (0.9 + ((seed % 17) / 17) * 0.3);
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const osc2 = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    const f = this.ctx.createBiquadFilter();
    osc.type = type === 'volt' ? 'square' : type === 'umbra' ? 'sawtooth' : 'triangle';
    osc2.type = 'sine';
    osc.frequency.setValueAtTime(base * 1.6, t);
    osc.frequency.exponentialRampToValueAtTime(base * 0.7, t + 0.32);
    osc2.frequency.setValueAtTime(base * 0.8, t);
    osc2.frequency.exponentialRampToValueAtTime(base * 1.15, t + 0.35);
    f.type = 'lowpass';
    f.frequency.setValueAtTime(2400, t);
    f.frequency.exponentialRampToValueAtTime(500, t + 0.4);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.14, t + 0.03);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.45);
    osc.connect(f);
    osc2.connect(f);
    f.connect(g);
    g.connect(this.master);
    osc.start(t); osc2.start(t);
    osc.stop(t + 0.48); osc2.stop(t + 0.48);
    this.noise({ dur: 0.18, gain: 0.04, lowpass: 900, delay: 0.02 });
  }

  attack(group, type) {
    if (group === 'physical') {
      this.noise({ dur: 0.22, gain: 0.16, lowpass: 900, highpass: 120 });
      this.tone({ freq: 110, dur: 0.2, type: 'square', gain: 0.1, slide: -50, filter: 500 });
    } else if (group === 'special') {
      this.tone({ freq: TYPE_PITCH[type] || 300, dur: 0.3, type: 'sawtooth', gain: 0.09, slide: 500, filter: 2200 });
      this.noise({ dur: 0.3, gain: 0.07, lowpass: 3000, highpass: 600 });
    } else {
      [523, 659, 784].forEach((f, i) => this.tone({ freq: f, dur: 0.28, type: 'sine', gain: 0.06, delay: i * 0.05 }));
    }
  }

  hit(mult = 1) {
    const m = Math.min(1.6, Math.max(0.7, mult));
    this.noise({ dur: 0.26, gain: 0.2 * m, lowpass: 1200, highpass: 60 });
    this.tone({ freq: 90, dur: 0.24, type: 'square', gain: 0.12 * m, slide: -40, filter: 600 });
    if (mult > 1.2) this.tone({ freq: 780, dur: 0.18, type: 'triangle', gain: 0.07, delay: 0.02 });
  }

  miss() {
    this.tone({ freq: 330, dur: 0.18, type: 'sine', gain: 0.06, slide: -120 });
  }

  heal() {
    [523, 659, 784, 1047].forEach((f, i) => this.tone({ freq: f, dur: 0.3, type: 'sine', gain: 0.06, delay: i * 0.055 }));
  }

  buff() {
    [392, 523, 659, 784].forEach((f, i) => this.tone({ freq: f, dur: 0.26, type: 'triangle', gain: 0.05, delay: i * 0.05 }));
  }

  debuff() {
    [440, 370, 311, 262].forEach((f, i) => this.tone({ freq: f, dur: 0.22, type: 'triangle', gain: 0.045, delay: i * 0.05 }));
  }

  faint() {
    this.tone({ freq: 300, dur: 0.7, type: 'sawtooth', gain: 0.1, slide: -240, filter: 900 });
    this.noise({ dur: 0.5, gain: 0.06, lowpass: 500 });
  }

  sendOut() {
    this.tone({ freq: 220, dur: 0.3, type: 'triangle', gain: 0.1, slide: 440 });
    this.noise({ dur: 0.25, gain: 0.05, lowpass: 2000 });
  }

  victory() {
    [523, 659, 784, 1047, 1319].forEach((f, i) => this.tone({ freq: f, dur: 0.6, type: 'triangle', gain: 0.09, delay: i * 0.13 }));
    this.tone({ freq: 262, dur: 1.6, type: 'sine', gain: 0.08, delay: 0.1 });
  }

  defeat() {
    [330, 294, 262, 196].forEach((f, i) => this.tone({ freq: f, dur: 0.8, type: 'sawtooth', gain: 0.07, delay: i * 0.18, filter: 700 }));
  }

  startAmbient() {
    if (!this.ctx || this.ambient) return;
    const t = this.ctx.currentTime;
    const g = this.ctx.createGain();
    g.gain.value = 0.018;
    const f = this.ctx.createBiquadFilter();
    f.type = 'lowpass';
    f.frequency.value = 420;
    const oscs = [55, 82.4, 110.5].map((freq) => {
      const o = this.ctx.createOscillator();
      o.type = 'sine';
      o.frequency.value = freq;
      o.connect(f);
      o.start(t);
      return o;
    });
    const lfo = this.ctx.createOscillator();
    const lg = this.ctx.createGain();
    lfo.frequency.value = 0.07;
    lg.gain.value = 120;
    lfo.connect(lg);
    lg.connect(f.frequency);
    lfo.start(t);
    f.connect(g);
    g.connect(this.master);
    this.ambient = { oscs, lfo, g };
  }
}

import { typeMultiplier } from './data.js';

export function stageMult(stage) {
  return stage >= 0 ? (2 + stage) / 2 : 2 / (2 - stage);
}

export function effectiveStat(creature, stat) {
  let value = creature.stats[stat] * stageMult(creature.stages[stat] || 0);
  if (stat === 'spe' && creature.status === 'chill') value *= 0.5;
  return Math.max(1, value);
}

export function effectiveSpeed(creature) {
  return effectiveStat(creature, 'spe');
}

export function critChance(creature) {
  return 1 / 16 + (creature.ability.key === 'crit' ? 0.1 : 0);
}

export function calcDamage(attacker, defender, move, rng = Math.random) {
  if (!move.power) return { damage: 0, typeMult: 1, crit: false, missed: false };
  const acc = move.accuracy;
  if (rng() * 100 > acc) return { damage: 0, typeMult: 1, crit: false, missed: true };
  const physical = move.group === 'physical';
  const atk = effectiveStat(attacker, physical ? 'atk' : 'spa');
  const def = effectiveStat(defender, physical ? 'def' : 'spd');
  let base = (((2 * 50) / 5 + 2) * move.power * (atk / def)) / 50 + 2;
  const mult = typeMultiplier(move.type, defender.type);
  base *= mult;
  if (physical && attacker.status === 'burn') base *= 0.5;
  if (attacker.ability.key === 'typeDamage' && move.type === attacker.type) base *= 1.2;
  if (attacker.ability.key === 'lowHpDamage' && defender.hp < defender.maxHp * 0.5) base *= 1.25;
  if (defender.ability.key === 'reduce') base *= 0.88;
  const crit = rng() < critChance(attacker);
  if (crit) base *= 1.5;
  base *= 0.88 + rng() * 0.12;
  return {
    damage: Math.max(1, Math.round(base)),
    typeMult: mult,
    crit,
    missed: false,
  };
}

export function estimateDamage(attacker, defender, move) {
  if (!move.power) return 0;
  const physical = move.group === 'physical';
  const atk = effectiveStat(attacker, physical ? 'atk' : 'spa');
  const def = effectiveStat(defender, physical ? 'def' : 'spd');
  let base = (((2 * 50) / 5 + 2) * move.power * (atk / def)) / 50 + 2;
  base *= typeMultiplier(move.type, defender.type);
  if (physical && attacker.status === 'burn') base *= 0.5;
  if (attacker.ability.key === 'typeDamage' && move.type === attacker.type) base *= 1.2;
  if (defender.ability.key === 'reduce') base *= 0.88;
  return base * 0.94;
}

function statusMoveScore(attacker, defender, move) {
  let score = 0;
  for (const e of move.effects) {
    if (e.kind === 'heal') {
      const missing = 1 - attacker.hp / attacker.maxHp;
      score += missing > 0.25 ? 30 + missing * 80 : -15;
    } else if (e.kind === 'barrier') {
      score += attacker.barrier > 0 ? 2 : 26;
    } else if (e.kind === 'buff') {
      const stage = attacker.stages[e.stat] || 0;
      score += stage >= 4 ? -6 : 12 + (e.stages || 1) * 6 - stage * 3;
    } else if (e.kind === 'debuff') {
      const stage = defender.stages[e.stat] || 0;
      score += stage <= -4 ? -6 : 10 + (e.stages || 1) * 4;
    } else if (e.kind === 'status') {
      score += defender.status ? -22 : 22 + (1 - defender.hp / defender.maxHp) * 14;
    } else if (e.kind === 'cleanse') {
      score += attacker.status ? 26 : -12;
    }
  }
  return score;
}

export function chooseAiMove(attacker, defender, rng = Math.random) {
  const usable = attacker.moves.filter((m) => m.pp > 0);
  if (!usable.length) return null;
  let best = usable[0];
  let bestScore = -Infinity;
  for (const move of usable) {
    let score = 0;
    if (move.group === 'status') {
      score = statusMoveScore(attacker, defender, move) * 0.9;
      // Don't waste a turn on setup when the target is nearly dead and we can KO.
      const bestDamage = usable.filter((m) => m.power).map((m) => estimateDamage(attacker, defender, m));
      if (bestDamage.length && Math.max(...bestDamage) >= defender.hp && move.group === 'status') score -= 35;
    } else {
      const dmg = estimateDamage(attacker, defender, move);
      const pct = dmg / defender.hp;
      score = Math.min(120, pct * 100) * 0.95;
      if (dmg >= defender.hp) score += 70;
      score *= 0.72 + typeMultiplier(move.type, defender.type) * 0.34;
      score *= move.accuracy / 100;
      if (attacker.ability.key === 'typeDamage' && move.type === attacker.type) score *= 1.08;
    }
    score *= 0.86 + rng() * 0.28;
    if (score > bestScore) {
      bestScore = score;
      best = move;
    }
  }
  return best;
}

export function chooseAiSwitch(team, opponent) {
  const alive = team.filter((c) => !c.fainted);
  if (!alive.length) return null;
  let best = alive[0];
  let bestScore = -Infinity;
  for (const c of alive) {
    let score = 0;
    score += typeMultiplier(c.type, opponent.type) * 18;
    score += (1 / typeMultiplier(opponent.type, c.type)) * 8;
    score += c.hp / c.maxHp * 14;
    score += Math.random() * 4;
    if (score > bestScore) {
      bestScore = score;
      best = c;
    }
  }
  return best;
}

export function applyStageChange(creature, stat, stages) {
  const before = creature.stages[stat] || 0;
  creature.stages[stat] = Math.max(-6, Math.min(6, before + stages));
  return creature.stages[stat] - before;
}

export function hpRatio(creature) {
  return Math.max(0, creature.hp / creature.maxHp);
}

export function hpColor(ratio) {
  if (ratio > 0.5) return '#5ee08a';
  if (ratio > 0.22) return '#f5c451';
  return '#ff5d5d';
}

:root {
  --bg: #05070c;
  --panel: rgba(8, 12, 19, 0.86);
  --panel-solid: #0a0e16;
  --line: rgba(242, 212, 146, 0.16);
  --line-soft: rgba(255, 255, 255, 0.08);
  --gold: #f2d492;
  --gold-soft: #fff2c8;
  --gold-deep: #b98a36;
  --text: #ece9e1;
  --muted: #98a2b3;
  --muted-dim: #6f7887;
  --phys: #ff9a62;
  --spec: #b98cff;
  --stat: #56e0c0;
  --danger: #ff5d5d;
  --display: 'Palatino Linotype', 'Book Antiqua', Palatino, Georgia, 'Times New Roman', serif;
  --ui: 'Trebuchet MS', 'Segoe UI', system-ui, -apple-system, sans-serif;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--text);
  font-family: var(--ui);
  -webkit-font-smoothing: antialiased;
  overscroll-behavior: none;
}

body {
  user-select: none;
}

button,
input {
  font-family: inherit;
}

button {
  color: inherit;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
}

#scene {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
}

.hidden {
  display: none !important;
}

kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 15px;
  height: 16px;
  padding: 0 4px;
  margin-left: 3px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-bottom-color: rgba(255, 255, 255, 0.3);
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.05);
  color: var(--muted);
  font-size: 8.5px;
  font-family: var(--ui);
  letter-spacing: 0;
}

.screen-fx {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 5;
}

#vignette {
  background:
    radial-gradient(ellipse at 50% 45%, transparent 30%, rgba(0, 0, 0, 0.32) 78%, rgba(0, 0, 0, 0.72) 100%),
    linear-gradient(180deg, rgba(0, 0, 0, 0.22), transparent 22%, transparent 76%, rgba(0, 0, 0, 0.28));
}

#flash {
  background: #fff;
  opacity: 0;
  transition: opacity 0.08s ease-out;
  z-index: 6;
}

#flash.on {
  opacity: 0.45;
  transition: none;
}

/* ══════════════════ LOADER ══════════════════ */
#sceneLoading {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 22px;
  background: #05070c;
  color: var(--gold);
  font-size: 10px;
  letter-spacing: 0.42em;
  transition: opacity 0.6s ease;
}

#sceneLoading.fade {
  opacity: 0;
  pointer-events: none;
}

.loader-ring {
  width: 54px;
  height: 54px;
  border: 1px solid rgba(242, 212, 146, 0.2);
  border-top-color: var(--gold);
  border-radius: 50%;
  animation: spin 1.1s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

/* ══════════════════ SHARED BUTTONS ══════════════════ */
.primary-btn {
  position: relative;
  border: 0;
  padding: 15px 24px;
  background: linear-gradient(135deg, #fff0c0 0%, #e7c273 45%, #b98a36 100%);
  color: #17120a;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.22em;
  cursor: pointer;
  clip-path: polygon(0 0, calc(100% - 11px) 0, 100% 11px, 100% 100%, 11px 100%, 0 calc(100% - 11px));
  transition: filter 0.2s, transform 0.2s, box-shadow 0.2s;
  box-shadow: 0 8px 30px rgba(226, 187, 105, 0.18);
}

.primary-btn span {
  display: inline-block;
  margin-left: 10px;
  transition: transform 0.2s;
}

.primary-btn:hover:not(:disabled) {
  filter: brightness(1.1);
  transform: translateY(-1px);
  box-shadow: 0 12px 38px rgba(226, 187, 105, 0.3);
}

.primary-btn:hover:not(:disabled) span {
  transform: translateX(4px);
}

.primary-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
  filter: grayscale(0.6);
}

.ghost-btn {
  border: 1px solid rgba(242, 212, 146, 0.32);
  background: transparent;
  color: var(--gold);
  padding: 13px 22px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.2em;
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s;
  clip-path: polygon(0 0, calc(100% - 9px) 0, 100% 9px, 100% 100%, 9px 100%, 0 calc(100% - 9px));
}

.ghost-btn:hover {
  background: rgba(242, 212, 146, 0.08);
  border-color: var(--gold);
}

.link-btn {
  border: 0;
  background: none;
  color: var(--gold);
  font-size: 9px;
  letter-spacing: 0.22em;
  cursor: pointer;
  padding: 4px;
  border-bottom: 1px solid rgba(242, 212, 146, 0.35);
}

.link-btn:hover {
  color: #fff;
  border-bottom-color: #fff;
}

.icon-btn {
  width: 30px;
  height: 30px;
  border: 1px solid var(--line-soft);
  background: rgba(255, 255, 255, 0.03);
  color: var(--gold);
  cursor: pointer;
  font-size: 14px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: border-color 0.2s, background 0.2s;
}

.icon-btn:hover {
  border-color: var(--gold);
  background: rgba(242, 212, 146, 0.08);
}

.icon-btn.muted {
  color: var(--muted-dim);
  text-decoration: line-through;
}

/* ══════════════════ TITLE ══════════════════ */
.screen {
  position: fixed;
  inset: 0;
  z-index: 20;
  animation: screenIn 0.5s ease both;
}

@keyframes screenIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.title-screen {
  display: flex;
  align-items: center;
  padding: 3vh 5vw;
  background:
    linear-gradient(90deg, rgba(4, 6, 10, 0.97) 0%, rgba(4, 6, 10, 0.88) 34%, rgba(4, 6, 10, 0.34) 64%, rgba(4, 6, 10, 0.02) 100%),
    radial-gradient(ellipse at 80% 50%, transparent 20%, rgba(4, 6, 10, 0.35) 80%);
}

.title-glow {
  position: absolute;
  width: 44vw;
  height: 44vw;
  right: 6vw;
  top: 50%;
  transform: translateY(-50%);
  background: radial-gradient(circle, rgba(242, 212, 146, 0.12), transparent 62%);
  filter: blur(20px);
  pointer-events: none;
}

.title-inner {
  position: relative;
  z-index: 2;
  width: min(680px, 58vw);
  max-height: 94vh;
  overflow-y: auto;
  padding-right: 10px;
  scrollbar-width: none;
}

.title-inner::-webkit-scrollbar {
  display: none;
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--gold);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.38em;
  text-transform: uppercase;
}

.eyebrow span {
  display: block;
  width: 30px;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--gold));
}

.eyebrow span:last-child {
  background: linear-gradient(90deg, var(--gold), transparent);
}

.title-inner h1 {
  margin: 16px 0 18px;
  font-family: var(--display);
  font-weight: 400;
  font-size: clamp(58px, 8.4vw, 116px);
  line-height: 0.8;
  letter-spacing: 0.015em;
  color: var(--gold-soft);
  text-shadow: 0 8px 60px rgba(242, 212, 146, 0.16);
}

.title-inner h1 span {
  display: block;
  margin-left: 0.06em;
  margin-top: 0.12em;
  font-size: 0.68em;
  font-weight: 400;
  letter-spacing: 0.13em;
  background: linear-gradient(180deg, #fff6d8 0%, #f0c96d 48%, #a97a28 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 4px 24px rgba(240, 201, 109, 0.18));
}

.tagline {
  margin: 0;
  max-width: 470px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.75;
  letter-spacing: 0.02em;
}

.seed-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  margin-top: 30px;
}

.seed-row > label {
  color: var(--muted-dim);
  font-size: 8.5px;
  font-weight: 700;
  letter-spacing: 0.26em;
}

.seed-control {
  display: flex;
  border: 1px solid var(--line);
  background: rgba(0, 0, 0, 0.35);
}

.seed-control input {
  width: 132px;
  padding: 12px 12px;
  border: 0;
  background: transparent;
  color: var(--gold-soft);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.26em;
  text-transform: uppercase;
  outline: none;
}

.seed-control input::placeholder {
  color: var(--muted-dim);
}

.seed-control button {
  width: 38px;
  border: 0;
  border-left: 1px solid var(--line);
  background: rgba(242, 212, 146, 0.05);
  color: var(--gold);
  font-size: 18px;
  cursor: pointer;
  transition: background 0.2s, transform 0.3s;
}

.seed-control button:hover {
  background: rgba(242, 212, 146, 0.14);
  transform: rotate(90deg);
}

.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-top: 38px;
}

.feature {
  position: relative;
  padding: 14px 14px 15px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-top: 1px solid rgba(242, 212, 146, 0.22);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.008));
  backdrop-filter: blur(8px);
}

.feature-icon {
  color: var(--gold);
  font-size: 17px;
  margin-bottom: 7px;
}

.feature h3 {
  margin: 0 0 5px;
  color: var(--gold-soft);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.16em;
}

.feature p {
  margin: 0;
  color: var(--muted-dim);
  font-size: 10px;
  line-height: 1.5;
}

.title-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-top: 28px;
  padding-top: 14px;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  color: var(--muted-dim);
  font-size: 8px;
  letter-spacing: 0.22em;
}

.title-side {
  position: absolute;
  right: 4vw;
  bottom: 9vh;
  z-index: 2;
  text-align: right;
  text-shadow: 0 2px 16px rgba(0, 0, 0, 0.8);
}

.showcase-label {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 7px;
  color: var(--gold);
  font-size: 8px;
  letter-spacing: 0.26em;
}

.live-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #6ee7a8;
  box-shadow: 0 0 10px #6ee7a8;
  animation: pulse 1.8s ease-in-out infinite;
}

@keyframes pulse {
  0%,
  100% {
    opacity: 0.4;
    transform: scale(0.8);
  }
  50% {
    opacity: 1;
    transform: scale(1.15);
  }
}

.showcase-name {
  margin-top: 6px;
  font-family: var(--display);
  font-size: 26px;
  letter-spacing: 0.04em;
  color: var(--gold-soft);
}

.showcase-meta {
  margin-top: 2px;
  color: var(--muted);
  font-size: 9px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.corner-mark {
  position: absolute;
  left: 5vw;
  bottom: 18px;
  color: rgba(255, 255, 255, 0.18);
  font-size: 7.5px;
  letter-spacing: 0.34em;
}

/* ══════════════════ TEAM SELECT ══════════════════ */
.select-screen {
  display: flex;
  flex-direction: column;
  padding: 3.2vh 4vw 20px;
  overflow-y: auto;
  background:
    linear-gradient(180deg, rgba(3, 6, 11, 0.86) 0%, rgba(3, 6, 11, 0.16) 34%, rgba(3, 6, 11, 0.12) 56%, rgba(3, 6, 11, 0.9) 88%, rgba(3, 6, 11, 0.98) 100%);
}

.select-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 30px;
  width: 100%;
  max-width: 1220px;
  margin: 0 auto;
}

.select-head h2 {
  margin: 8px 0 6px;
  font-family: var(--display);
  font-weight: 400;
  font-size: clamp(38px, 4.5vw, 64px);
  line-height: 0.95;
  letter-spacing: 0.02em;
  color: var(--gold-soft);
}

.select-head h2 em {
  color: var(--gold);
  font-style: italic;
}

.select-head p {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  letter-spacing: 0.02em;
}

.select-seed {
  display: grid;
  grid-template-columns: auto auto;
  gap: 4px 12px;
  text-align: right;
  flex-shrink: 0;
}

.select-seed span {
  color: var(--muted-dim);
  font-size: 8px;
  letter-spacing: 0.22em;
}

.select-seed strong {
  color: var(--gold);
  font-size: 10px;
  letter-spacing: 0.12em;
  max-width: 260px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.team-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  width: 100%;
  max-width: 1120px;
  margin: 22px auto 0;
}

.team-card {
  position: relative;
  display: flex;
  flex-direction: column;
  text-align: left;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, 0.09);
  background: linear-gradient(180deg, rgba(15, 20, 30, 0.94), rgba(7, 10, 16, 0.97));
  color: var(--text);
  cursor: pointer;
  overflow: hidden;
  transition: transform 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease;
  clip-path: polygon(0 0, calc(100% - 14px) 0, 100% 14px, 100% 100%, 0 100%);
}

.team-card:hover {
  transform: translateY(-4px);
  border-color: rgba(242, 212, 146, 0.45);
  box-shadow: 0 18px 50px rgba(0, 0, 0, 0.45);
}

.team-card.selected {
  transform: translateY(-8px);
  border-color: var(--gold);
  box-shadow: 0 0 0 1px rgba(242, 212, 146, 0.25), 0 22px 60px rgba(242, 212, 146, 0.12);
}

.team-card.selected::after {
  content: 'LEAD';
  position: absolute;
  top: 12px;
  right: 12px;
  z-index: 3;
  padding: 4px 7px;
  background: var(--gold);
  color: #17120a;
  font-size: 7.5px;
  font-weight: 700;
  letter-spacing: 0.2em;
}

.tc-art {
  position: relative;
  height: 132px;
  overflow: hidden;
  background: #05070b;
}

.tc-art img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  opacity: 0.94;
}

.tc-art::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 48%, rgba(7, 10, 16, 0.92) 100%);
}

.tc-type {
  position: absolute;
  left: 12px;
  bottom: 10px;
  z-index: 2;
  padding: 3px 7px;
  border: 1px solid var(--tc, var(--gold));
  color: var(--tc, var(--gold));
  background: rgba(5, 7, 12, 0.6);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

.tc-arch {
  position: absolute;
  right: 12px;
  bottom: 10px;
  z-index: 2;
  color: var(--muted);
  font-size: 8px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.tc-body {
  padding: 12px 14px 14px;
}

.tc-title {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.tc-title h3 {
  margin: 0;
  font-family: var(--display);
  font-weight: 400;
  font-size: 25px;
  letter-spacing: 0.02em;
  color: var(--gold-soft);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.tc-title span {
  color: var(--muted-dim);
  font-size: 8.5px;
  letter-spacing: 0.1em;
  flex-shrink: 0;
}

.tc-species {
  margin-top: 1px;
  color: var(--muted);
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.tc-ability {
  margin-top: 9px;
  padding-left: 8px;
  border-left: 2px solid var(--tc, var(--gold));
}

.tc-ability span {
  color: var(--gold-soft);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.tc-ability p {
  margin: 1px 0 0;
  color: var(--muted-dim);
  font-size: 9px;
  line-height: 1.35;
}

.tc-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px 12px;
  margin-top: 10px;
}

.tc-stat {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 7.5px;
  color: var(--muted-dim);
  letter-spacing: 0.08em;
}

.tc-stat > span {
  width: 20px;
  flex-shrink: 0;
}

.tc-stat b {
  width: 22px;
  text-align: right;
  color: var(--muted);
  font-size: 7.5px;
  font-weight: 400;
}

.tc-bar {
  flex: 1;
  height: 3px;
  background: rgba(255, 255, 255, 0.07);
  overflow: hidden;
}

.tc-bar i {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, var(--tc, var(--gold)), rgba(255, 255, 255, 0.75));
  opacity: 0.75;
}

.tc-moves {
  display: grid;
  gap: 3px;
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}

.tc-move-row {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.tc-move-row .dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  flex-shrink: 0;
}

.tc-move-row .dot.physical {
  background: var(--phys);
}
.tc-move-row .dot.special {
  background: var(--spec);
}
.tc-move-row .dot.status {
  background: var(--stat);
}

.tc-move-row span:last-child {
  color: var(--muted);
  font-size: 8.5px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  letter-spacing: 0.02em;
}

.select-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  width: 100%;
  max-width: 1120px;
  margin: auto auto 0;
  padding-top: 18px;
}

.warden-preview {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.warden-label {
  color: var(--muted-dim);
  font-size: 7.5px;
  letter-spacing: 0.26em;
}

.warden-name {
  color: #ffb3a3;
  font-family: var(--display);
  font-size: 19px;
}

.warden-sub {
  color: var(--muted);
  font-size: 8.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.warden-pips {
  display: flex;
  gap: 4px;
  margin-top: 5px;
}

.warden-pips i {
  width: 16px;
  height: 4px;
  background: #ff6b5a;
  transform: skewX(-24deg);
  box-shadow: 0 0 8px rgba(255, 107, 90, 0.45);
}

.select-hint {
  color: var(--muted-dim);
  font-size: 9px;
  letter-spacing: 0.1em;
}

/* ══════════════════ HUD ══════════════════ */
#hud {
  position: fixed;
  inset: 0;
  z-index: 20;
  pointer-events: none;
}

.hud-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 22px;
}

.combatant {
  position: relative;
  width: min(350px, 29vw);
  padding: 11px 14px 9px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  background: linear-gradient(180deg, rgba(9, 13, 20, 0.9), rgba(5, 8, 13, 0.82));
  backdrop-filter: blur(12px);
  clip-path: polygon(0 0, calc(100% - 11px) 0, 100% 11px, 100% 100%, 0 100%);
  animation: hudIn 0.6s ease both;
}

.combatant::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 2px;
  background: var(--t, var(--gold));
  box-shadow: 0 0 14px var(--t, var(--gold));
}

@keyframes hudIn {
  from {
    opacity: 0;
    transform: translateY(-10px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.enemy-panel {
  border-top-color: rgba(255, 120, 100, 0.28);
}

.player-panel {
  border-top-color: rgba(242, 212, 146, 0.32);
}

.combatant-head {
  display: flex;
  align-items: center;
  gap: 7px;
}

.type-chip {
  padding: 2px 6px;
  border: 1px solid var(--t, var(--gold));
  color: var(--t, var(--gold));
  font-size: 7.5px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  background: rgba(0, 0, 0, 0.25);
}

.combatant-name {
  font-family: var(--display);
  font-size: 20px;
  letter-spacing: 0.02em;
  color: var(--gold-soft);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.level {
  margin-left: auto;
  color: var(--muted-dim);
  font-size: 8px;
  letter-spacing: 0.1em;
  flex-shrink: 0;
}

.hp-track {
  position: relative;
  height: 9px;
  margin-top: 7px;
  background: #05070b;
  border: 1px solid rgba(255, 255, 255, 0.1);
  overflow: hidden;
}

.hp-ghost,
.hp-fill {
  position: absolute;
  inset: 0;
  transform-origin: left center;
  transition: width 0.5s cubic-bezier(0.2, 0.8, 0.2, 1);
}

.hp-ghost {
  background: rgba(255, 255, 255, 0.18);
  transition-duration: 0.9s;
}

.hp-fill {
  background: var(--hp, #5ee08a);
  box-shadow: 0 0 10px var(--hp, #5ee08a);
}

.hp-fill::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.28), transparent 55%);
}

.hp-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-top: 4px;
  min-height: 15px;
}

.hp-text {
  color: var(--muted);
  font-size: 8.5px;
  letter-spacing: 0.08em;
  font-variant-numeric: tabular-nums;
}

.status-chips {
  display: flex;
  gap: 3px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.chip {
  padding: 1px 5px;
  border: 1px solid rgba(255, 255, 255, 0.13);
  background: rgba(255, 255, 255, 0.04);
  color: var(--muted);
  font-size: 7px;
  letter-spacing: 0.06em;
  white-space: nowrap;
}

.chip.status {
  border-color: var(--c, var(--gold));
  color: var(--c, var(--gold));
}

.chip.barrier {
  border-color: #7dd3fc;
  color: #7dd3fc;
}

.chip.stage {
  border-color: rgba(242, 212, 146, 0.4);
  color: var(--gold);
}

.ability-line {
  margin-top: 5px;
  color: var(--muted-dim);
  font-size: 8px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.team-pips {
  display: flex;
  gap: 4px;
  margin-top: 6px;
}

.team-pips i {
  width: 15px;
  height: 3px;
  background: rgba(255, 255, 255, 0.14);
  transform: skewX(-24deg);
  transition: background 0.3s, box-shadow 0.3s;
}

.team-pips i.alive {
  background: var(--t, var(--gold));
  box-shadow: 0 0 6px var(--t, var(--gold));
  opacity: 0.75;
}

.team-pips i.current {
  opacity: 1;
  background: #fff;
  box-shadow: 0 0 8px #fff;
}

.team-pips i.fainted {
  background: rgba(255, 255, 255, 0.08);
  opacity: 0.4;
}

.duel-info {
  text-align: center;
  padding-top: 5px;
  flex-shrink: 0;
}

.duel-kicker {
  color: var(--gold);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.36em;
}

.duel-round {
  margin-top: 3px;
  font-family: var(--display);
  font-size: 13px;
  letter-spacing: 0.16em;
  color: var(--gold-soft);
}

.duel-room {
  margin-top: 2px;
  color: var(--muted-dim);
  font-size: 8px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  max-width: 240px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.battle-log {
  position: fixed;
  left: 22px;
  top: 145px;
  width: 300px;
  max-height: 150px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 8px 10px;
  background: linear-gradient(90deg, rgba(5, 8, 13, 0.62), transparent);
  border-left: 1px solid rgba(242, 212, 146, 0.16);
  mask-image: linear-gradient(180deg, transparent 0, #000 12%, #000 100%);
  font-size: 9.5px;
  line-height: 1.35;
  color: var(--muted);
}

.battle-log .log-line {
  animation: logIn 0.3s ease both;
}

.battle-log .log-line.player {
  color: #ffdca8;
}
.battle-log .log-line.enemy {
  color: #ffb3a3;
}
.battle-log .log-line.good {
  color: #7ff0b0;
}
.battle-log .log-line.bad {
  color: #ff8c8c;
}
.battle-log .log-line.system {
  color: var(--muted-dim);
}

@keyframes logIn {
  from {
    opacity: 0;
    transform: translateX(-6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

/* ══════════════════ COMMAND DOCK ══════════════════ */
#dock {
  position: fixed;
  left: 50%;
  bottom: 12px;
  transform: translateX(-50%);
  z-index: 30;
  width: min(1120px, calc(100vw - 26px));
  padding: 11px 15px 9px;
  background: linear-gradient(180deg, rgba(11, 15, 23, 0.94), rgba(5, 8, 13, 0.97));
  border: 1px solid rgba(242, 212, 146, 0.14);
  box-shadow: 0 -8px 60px rgba(0, 0, 0, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  backdrop-filter: blur(18px);
  clip-path: polygon(0 0, calc(100% - 13px) 0, 100% 13px, 100% 100%, 13px 100%, 0 calc(100% - 13px));
  animation: dockIn 0.55s ease both;
}

@keyframes dockIn {
  from {
    opacity: 0;
    transform: translate(-50%, 18px);
  }
  to {
    opacity: 1;
    transform: translate(-50%, 0);
  }
}

.dock-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.dock-title {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--gold);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.26em;
}

.dock-dot {
  width: 5px;
  height: 5px;
  background: var(--gold);
  border-radius: 50%;
  box-shadow: 0 0 9px var(--gold);
  animation: pulse 1.6s ease-in-out infinite;
}

.dock-tools {
  display: flex;
  align-items: center;
  gap: 6px;
}

.tool-btn {
  height: 26px;
  padding: 0 10px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.025);
  color: var(--muted);
  font-size: 8.5px;
  letter-spacing: 0.16em;
  cursor: pointer;
  transition: color 0.2s, border-color 0.2s, background 0.2s;
}

.tool-btn:hover:not(:disabled) {
  color: var(--gold);
  border-color: rgba(242, 212, 146, 0.5);
  background: rgba(242, 212, 146, 0.06);
}

.tool-btn:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.group-tabs {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 7px;
  margin: 9px 0 8px;
}

.group-tab {
  position: relative;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 7px 10px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-bottom: 2px solid transparent;
  background: rgba(255, 255, 255, 0.015);
  color: var(--muted-dim);
  cursor: pointer;
  transition: all 0.2s;
  font-size: 9px;
  letter-spacing: 0.18em;
}

.group-tab .gt-icon {
  font-size: 12px;
  line-height: 1;
  color: var(--g);
  opacity: 0.5;
  transition: opacity 0.2s, text-shadow 0.2s;
}

.group-tab .gt-name {
  font-weight: 700;
}

.group-tab .gt-count {
  margin-left: auto;
  min-width: 17px;
  padding: 1px 4px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: var(--muted-dim);
  font-size: 8px;
  letter-spacing: 0;
  text-align: center;
}

.group-tab:hover {
  color: var(--text);
  border-color: rgba(255, 255, 255, 0.15);
}

.group-tab.active {
  color: #fff;
  border-color: color-mix(in srgb, var(--g) 45%, transparent);
  border-bottom-color: var(--g);
  background: linear-gradient(180deg, color-mix(in srgb, var(--g) 16%, transparent), rgba(255, 255, 255, 0.01));
  box-shadow: inset 0 -10px 24px color-mix(in srgb, var(--g) 8%, transparent);
}

.group-tab.active .gt-icon {
  opacity: 1;
  text-shadow: 0 0 10px var(--g);
}

.group-tab.active .gt-count {
  border-color: color-mix(in srgb, var(--g) 50%, transparent);
  color: var(--g);
}

.move-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.move-card {
  position: relative;
  text-align: left;
  min-height: 96px;
  padding: 9px 12px 9px 13px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-left: 2px solid var(--g);
  background: linear-gradient(110deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.008));
  color: var(--text);
  cursor: pointer;
  overflow: hidden;
  transition: transform 0.18s, border-color 0.18s, background 0.18s, box-shadow 0.18s;
}

.move-card::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 0% 50%, color-mix(in srgb, var(--g) 14%, transparent), transparent 60%);
  opacity: 0;
  transition: opacity 0.2s;
  pointer-events: none;
}

.move-card:hover:not(:disabled) {
  transform: translateY(-2px);
  border-color: color-mix(in srgb, var(--g) 55%, transparent);
  border-left-color: var(--g);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

.move-card:hover:not(:disabled)::after {
  opacity: 1;
}

.move-card:disabled {
  opacity: 0.38;
  cursor: not-allowed;
  filter: saturate(0.5);
}

.move-card.physical {
  --g: var(--phys);
}
.move-card.special {
  --g: var(--spec);
}
.move-card.status {
  --g: var(--stat);
}

.mc-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  position: relative;
  z-index: 1;
}

.type-pill {
  padding: 1px 6px;
  border: 1px solid color-mix(in srgb, var(--t, var(--g)) 60%, transparent);
  color: var(--t, var(--g));
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.mc-pp {
  color: var(--muted-dim);
  font-size: 8px;
  letter-spacing: 0.06em;
  font-variant-numeric: tabular-nums;
}

.mc-name {
  position: relative;
  z-index: 1;
  margin: 3px 0 2px;
  font-family: var(--display);
  font-size: 19px;
  letter-spacing: 0.015em;
  color: var(--gold-soft);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.mc-meta {
  position: relative;
  z-index: 1;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  color: var(--muted-dim);
  font-size: 7.5px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.mc-meta .power {
  color: var(--g);
}

.mc-desc {
  position: relative;
  z-index: 1;
  margin: 5px 0 0;
  color: var(--muted);
  font-size: 9.5px;
  line-height: 1.35;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.dock-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 7px;
  padding-top: 6px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  color: var(--muted-dim);
  font-size: 7.5px;
  letter-spacing: 0.08em;
}

#activeSummary {
  color: var(--gold);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 50%;
}

/* ══════════════════ FLOATERS / BANNER / TOAST ══════════════════ */
#floaters {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 60;
}

.floater {
  position: absolute;
  transform: translate(-50%, -50%);
  font-family: var(--display);
  font-size: 32px;
  font-weight: 700;
  letter-spacing: 0.01em;
  color: #fff;
  text-shadow: 0 2px 0 rgba(0, 0, 0, 0.55), 0 0 18px currentColor;
  animation: floatUp 1.5s cubic-bezier(0.15, 0.7, 0.2, 1) forwards;
  white-space: nowrap;
  will-change: transform, opacity;
}

.floater.crit {
  font-size: 46px;
  color: var(--gold-soft);
}

.floater.heal {
  color: #7ff0b0;
}

.floater.miss {
  color: #c7cfdd;
  font-size: 24px;
  letter-spacing: 0.18em;
}

.floater.status {
  font-size: 18px;
  letter-spacing: 0.14em;
}

.floater.small {
  font-size: 15px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

@keyframes floatUp {
  0% {
    opacity: 0;
    transform: translate(-50%, -30%) scale(0.65);
  }
  14% {
    opacity: 1;
    transform: translate(-50%, -55%) scale(1.12);
  }
  30% {
    transform: translate(-50%, -65%) scale(1);
  }
  100% {
    opacity: 0;
    transform: translate(-50%, -170%) scale(1);
  }
}

#banner {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
  z-index: 55;
  background: radial-gradient(ellipse at center, rgba(4, 6, 10, 0.5), transparent 55%);
}

.banner-inner {
  text-align: center;
  animation: bannerIn 2.2s ease both;
}

.banner-kicker {
  color: var(--gold);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.46em;
  text-transform: uppercase;
}

.banner-title {
  margin: 8px 0 4px;
  font-family: var(--display);
  font-size: clamp(34px, 4.6vw, 58px);
  letter-spacing: 0.06em;
  background: linear-gradient(180deg, #fff7dd, #f0c96d 55%, #a97a28);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 8px 28px rgba(0, 0, 0, 0.65));
}

.banner-sub {
  color: var(--muted);
  font-size: 10px;
  letter-spacing: 0.28em;
  text-transform: uppercase;
}

@keyframes bannerIn {
  0% {
    opacity: 0;
    transform: scale(1.08);
    filter: blur(8px);
  }
  12% {
    opacity: 1;
    transform: scale(1);
    filter: blur(0);
  }
  75% {
    opacity: 1;
  }
  100% {
    opacity: 0;
  }
}

#toast {
  position: fixed;
  top: 17%;
  left: 50%;
  transform: translateX(-50%);
  z-index: 56;
  padding: 9px 18px;
  border: 1px solid var(--line);
  border-left: 2px solid var(--gold);
  background: rgba(6, 9, 14, 0.9);
  color: var(--gold-soft);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  backdrop-filter: blur(10px);
  animation: toastIn 1.8s ease forwards;
  white-space: nowrap;
}

#toast.good {
  border-left-color: #6ee7a8;
  color: #9df5c4;
}
#toast.bad {
  border-left-color: #ff6b5a;
  color: #ffb3a3;
}

@keyframes toastIn {
  0% {
    opacity: 0;
    transform: translate(-50%, -8px);
  }
  12%,
  80% {
    opacity: 1;
    transform: translate(-50%, 0);
  }
  100% {
    opacity: 0;
    transform: translate(-50%, -8px);
  }
}

#hintBar {
  position: fixed;
  left: 50%;
  bottom: 248px;
  transform: translateX(-50%);
  z-index: 45;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 7px 10px 7px 14px;
  border: 1px solid var(--line);
  background: rgba(7, 10, 16, 0.9);
  color: var(--muted);
  font-size: 9.5px;
  letter-spacing: 0.06em;
  backdrop-filter: blur(10px);
  white-space: nowrap;
  animation: toastIn 0.4s ease both;
}

#hintBar b {
  color: var(--gold);
}

#hintClose {
  border: 0;
  background: none;
  color: var(--muted-dim);
  cursor: pointer;
  font-size: 11px;
  padding: 2px 4px;
}

/* ══════════════════ MODALS ══════════════════ */
.modal {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: rgba(2, 4, 8, 0.78);
  backdrop-filter: blur(7px);
  animation: screenIn 0.25s ease both;
}

.modal-card {
  width: min(900px, 100%);
  max-height: 88vh;
  overflow-y: auto;
  padding: 22px;
  background: linear-gradient(180deg, rgba(13, 18, 27, 0.99), rgba(6, 9, 14, 0.99));
  border: 1px solid rgba(242, 212, 146, 0.2);
  box-shadow: 0 30px 100px rgba(0, 0, 0, 0.7);
  clip-path: polygon(0 0, calc(100% - 16px) 0, 100% 16px, 100% 100%, 16px 100%, 0 calc(100% - 16px));
}

.modal-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 18px;
}

.modal-kicker {
  color: var(--gold);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.32em;
}

.modal-head h3 {
  margin: 4px 0 0;
  font-family: var(--display);
  font-weight: 400;
  font-size: 32px;
  color: var(--gold-soft);
}

.close-btn {
  width: 32px;
  height: 32px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-size: 13px;
  transition: all 0.2s;
  flex-shrink: 0;
}

.close-btn:hover {
  border-color: var(--gold);
  color: var(--gold);
}

.switch-card {
  width: min(880px, 100%);
}

.switch-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.switch-option {
  text-align: left;
  padding: 13px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-left: 2px solid var(--t, var(--gold));
  background: rgba(255, 255, 255, 0.02);
  color: var(--text);
  cursor: pointer;
  transition: all 0.2s;
}

.switch-option:hover {
  background: rgba(242, 212, 146, 0.05);
  border-color: var(--gold);
}

.switch-option .so-top {
  display: flex;
  align-items: center;
  gap: 6px;
}

.switch-option .so-name {
  font-family: var(--display);
  font-size: 20px;
  color: var(--gold-soft);
}

.switch-option .so-type {
  margin-left: auto;
  color: var(--t, var(--gold));
  font-size: 7.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.switch-option .so-species {
  margin-top: 1px;
  color: var(--muted-dim);
  font-size: 8px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.so-hp {
  height: 5px;
  margin-top: 8px;
  background: rgba(255, 255, 255, 0.07);
}

.so-hp i {
  display: block;
  height: 100%;
  background: var(--hp, #5ee08a);
}

.so-meta {
  display: flex;
  justify-content: space-between;
  margin-top: 4px;
  color: var(--muted);
  font-size: 8px;
  letter-spacing: 0.06em;
}

.so-ability {
  margin-top: 7px;
  color: var(--muted-dim);
  font-size: 8.5px;
  line-height: 1.35;
}

.modal-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-top: 18px;
  padding-top: 14px;
  border-top: 1px solid rgba(255, 255, 255, 0.07);
  color: var(--muted-dim);
  font-size: 9px;
  letter-spacing: 0.06em;
}

.codex-card {
  width: min(980px, 100%);
}

.codex-body {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 26px;
}

.codex-section h4 {
  margin: 0 0 8px;
  color: var(--gold);
  font-size: 9px;
  letter-spacing: 0.24em;
  text-transform: uppercase;
}

.codex-section p {
  margin: 0 0 10px;
  color: var(--muted);
  font-size: 10.5px;
  line-height: 1.55;
}

.type-wheel {
  display: grid;
  gap: 4px;
}

.type-row {
  display: grid;
  grid-template-columns: 56px 1fr;
  gap: 8px;
  align-items: center;
  padding: 5px 7px;
  border-left: 2px solid var(--c);
  background: rgba(255, 255, 255, 0.02);
  font-size: 9px;
  color: var(--muted);
}

.type-row b {
  color: var(--c);
  font-size: 8px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.type-row span em {
  color: var(--gold-soft);
  font-style: normal;
}

.type-row span s {
  color: var(--muted-dim);
}

.controls-grid {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 5px 12px;
  font-size: 9.5px;
  color: var(--muted);
  margin-bottom: 14px;
}

.controls-grid b {
  color: var(--gold-soft);
  font-weight: 400;
}

.roster-list {
  display: grid;
  gap: 8px;
}

.roster-item {
  padding: 7px 9px;
  border-left: 2px solid var(--t);
  background: rgba(255, 255, 255, 0.02);
}

.roster-item .ri-top {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: 10px;
}

.roster-item .ri-top b {
  font-family: var(--display);
  font-size: 15px;
  font-weight: 400;
  color: var(--gold-soft);
}

.roster-item .ri-top span {
  color: var(--t);
  font-size: 8px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.roster-item .ri-moves {
  margin-top: 3px;
  color: var(--muted-dim);
  font-size: 8.5px;
  line-height: 1.4;
}

/* ══════════════════ END SCREEN ══════════════════ */
.end-screen {
  display: flex;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(ellipse at 50% 45%, rgba(242, 212, 146, 0.08), transparent 52%),
    rgba(3, 5, 9, 0.86);
  backdrop-filter: blur(5px);
}

.end-card {
  width: min(660px, 92vw);
  padding: 40px 42px 32px;
  text-align: center;
  background: linear-gradient(180deg, rgba(13, 18, 27, 0.98), rgba(6, 9, 14, 0.99));
  border: 1px solid rgba(242, 212, 146, 0.24);
  box-shadow: 0 40px 120px rgba(0, 0, 0, 0.7);
  clip-path: polygon(0 0, calc(100% - 18px) 0, 100% 18px, 100% 100%, 18px 100%, 0 calc(100% - 18px));
  animation: endIn 0.7s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

@keyframes endIn {
  from {
    opacity: 0;
    transform: translateY(24px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.end-kicker {
  color: var(--gold);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.44em;
}

.end-card h2 {
  margin: 10px 0 6px;
  font-family: var(--display);
  font-weight: 400;
  font-size: clamp(40px, 5.4vw, 66px);
  line-height: 0.95;
  background: linear-gradient(180deg, #fff8e2, #f0c96d 52%, #a97a28);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.end-card > p {
  margin: 0 auto;
  max-width: 460px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.65;
}

.end-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  margin: 24px 0 14px;
  background: rgba(255, 255, 255, 0.06);
}

.end-stat {
  padding: 12px 6px;
  background: rgba(8, 11, 17, 0.96);
}

.end-stat span {
  display: block;
  color: var(--muted-dim);
  font-size: 7.5px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

.end-stat b {
  display: block;
  margin-top: 3px;
  color: var(--gold-soft);
  font-family: var(--display);
  font-size: 22px;
  font-weight: 400;
}

.end-seed {
  color: var(--muted-dim);
  font-size: 8px;
  letter-spacing: 0.22em;
  margin-bottom: 20px;
}

.end-seed strong {
  color: var(--gold);
}

.end-actions {
  display: flex;
  justify-content: center;
  gap: 10px;
}

/* ══════════════════ RESPONSIVE ══════════════════ */
@media (max-width: 1100px) {
  .title-inner {
    width: 64vw;
  }
  .combatant {
    width: min(330px, 31vw);
  }
  .battle-log {
    width: 250px;
  }
}

@media (max-width: 860px) {
  .title-screen {
    align-items: flex-start;
    padding: 7vh 6vw 3vh;
    background:
      linear-gradient(180deg, rgba(4, 6, 10, 0.96) 0%, rgba(4, 6, 10, 0.82) 40%, rgba(4, 6, 10, 0.38) 70%, rgba(4, 6, 10, 0.7) 100%),
