import { RNG } from './rng.js';
import { GROUPS, GROUP_ORDER, STATUS_INFO, TYPES, TYPE_ORDER, typeRelation } from './data.js';
import { hpColor, hpRatio } from './battle.js';

const artCache = new Map();

function hexA(hex, alpha) {
  const h = hex.replace('#', '');
  const r = parseInt(h.slice(0, 2), 16);
  const g = parseInt(h.slice(2, 4), 16);
  const b = parseInt(h.slice(4, 6), 16);
  return `rgba(${r},${g},${b},${alpha})`;
}

export function creatureArt(creature) {
  if (artCache.has(creature.id)) return artCache.get(creature.id);
  const rng = new RNG(creature.seed + ':sigil');
  const c = document.createElement('canvas');
  c.width = 720;
  c.height = 300;
  const g = c.getContext('2d');
  const type = TYPES[creature.type];
  const cx = 470;
  const cy = 150;

  const bg = g.createLinearGradient(0, 0, 720, 300);
  bg.addColorStop(0, '#05070c');
  bg.addColorStop(0.55, type.palette.dark);
  bg.addColorStop(1, '#05070c');
  g.fillStyle = bg;
  g.fillRect(0, 0, 720, 300);

  const glow = g.createRadialGradient(cx, cy, 4, cx, cy, 300);
  glow.addColorStop(0, hexA(type.color, 0.55));
  glow.addColorStop(0.28, hexA(type.color, 0.16));
  glow.addColorStop(0.7, hexA(type.deep, 0.08));
  glow.addColorStop(1, 'rgba(0,0,0,0)');
  g.fillStyle = glow;
  g.fillRect(0, 0, 720, 300);

  // Sweeping rays
  g.save();
  g.translate(cx, cy);
  for (let i = 0; i < 18; i++) {
    const a = (i / 18) * Math.PI * 2 + rng.float(-0.04, 0.04);
    const spread = 0.025 + rng.float(0, 0.04);
    g.beginPath();
    g.moveTo(0, 0);
    g.arc(0, 0, 340, a, a + spread);
    g.closePath();
    g.fillStyle = hexA(i % 3 === 0 ? type.soft : type.color, rng.float(0.015, 0.055));
    g.fill();
  }
  g.restore();

  // Concentric rings
  for (let i = 0; i < 5; i++) {
    g.strokeStyle = hexA(i % 2 ? type.color : type.soft, 0.28 - i * 0.035);
    g.lineWidth = i === 0 ? 2 : 1;
    g.beginPath();
    g.arc(cx, cy, 44 + i * 24, 0, Math.PI * 2);
    g.stroke();
  }

  // Procedural polygon
  const sides = 3 + (creature.seed % 5);
  const radius = 78 + (creature.seed % 26);
  g.strokeStyle = hexA(type.soft, 0.9);
  g.lineWidth = 2.2;
  g.beginPath();
  for (let i = 0; i <= sides; i++) {
    const a = (i / sides) * Math.PI * 2 - Math.PI / 2 + (creature.seed % 10) * 0.02;
    const x = cx + Math.cos(a) * radius;
    const y = cy + Math.sin(a) * radius;
    if (i === 0) g.moveTo(x, y);
    else g.lineTo(x, y);
  }
  g.stroke();

  g.strokeStyle = hexA(type.color, 0.55);
  g.lineWidth = 1.2;
  for (let i = 0; i < sides; i++) {
    const a = (i / sides) * Math.PI * 2 - Math.PI / 2;
    const a2 = ((i + 2) / sides) * Math.PI * 2 - Math.PI / 2;
    g.beginPath();
    g.moveTo(cx + Math.cos(a) * radius, cy + Math.sin(a) * radius);
    g.lineTo(cx + Math.cos(a2) * radius, cy + Math.sin(a2) * radius);
    g.stroke();
  }

  // Type glyph
  g.save();
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  g.font = '600 76px Georgia, serif';
  g.fillStyle = hexA(type.soft, 0.92);
  g.shadowColor = type.color;
  g.shadowBlur = 28;
  g.fillText(type.glyph, cx, cy + 2);
  g.restore();

  // Outer rune ticks
  for (let i = 0; i < 30; i++) {
    const a = (i / 30) * Math.PI * 2;
    const r = 178 + (i % 3) * 8;
    const x = cx + Math.cos(a) * r;
    const y = cy + Math.sin(a) * r;
    g.save();
    g.translate(x, y);
    g.rotate(a);
    g.strokeStyle = hexA(type.color, rng.float(0.2, 0.55));
    g.lineWidth = 1.3;
    g.beginPath();
    if (i % 3 === 0) {
      g.moveTo(-4, -7);
      g.lineTo(4, 0);
      g.lineTo(-4, 7);
    } else {
      g.moveTo(-5, 0);
      g.lineTo(5, 0);
    }
    g.stroke();
    g.restore();
  }

  // Star specks
  for (let i = 0; i < 46; i++) {
    g.fillStyle = hexA(i % 4 ? type.soft : '#ffffff', rng.float(0.08, 0.55));
    const x = rng.float(20, 700);
    const y = rng.float(10, 290);
    const r = rng.float(0.4, 1.8);
    g.beginPath();
    g.arc(x, y, r, 0, Math.PI * 2);
    g.fill();
  }

  // Left-edge name plate gradient
  const shade = g.createLinearGradient(0, 0, 420, 0);
  shade.addColorStop(0, 'rgba(5,7,12,0.85)');
  shade.addColorStop(1, 'rgba(5,7,12,0)');
  g.fillStyle = shade;
  g.fillRect(0, 0, 420, 300);

  const url = c.toDataURL('image/jpeg', 0.82);
  artCache.set(creature.id, url);
  return url;
}

function statBar(label, value, max, color) {
  const pct = Math.max(4, Math.min(100, (value / max) * 100));
  return `<div class="tc-stat"><span>${label}</span><div class="tc-bar"><i style="width:${pct}%;--tc:${color}"></i></div><b>${value}</b></div>`;
}

export function teamCardMarkup(creature, index) {
  const type = TYPES[creature.type];
  const movesByGroup = GROUP_ORDER.map((group) => {
    const moves = creature.moves.filter((m) => m.group === group);
    return `<div class="tc-move-row"><span class="dot ${group}"></span><span>${moves.map((m) => m.name).join(' · ')}</span></div>`;
  }).join('');

  return `
    <button class="team-card" data-index="${index}" style="--tc:${type.color}" aria-label="Select ${creature.name}">
      <div class="tc-art">
        <img src="${creatureArt(creature)}" alt="" />
        <span class="tc-type" style="--tc:${type.color}">${type.name}</span>
        <span class="tc-arch">${creature.archetypeLabel}</span>
      </div>
      <div class="tc-body">
        <div class="tc-title"><h3>${creature.name}</h3><span>LV. 50</span></div>
        <div class="tc-species">${creature.species}</div>
        <div class="tc-ability" style="--tc:${type.color}">
          <span>${creature.ability.name}</span>
          <p>${creature.ability.desc}</p>
        </div>
        <div class="tc-stats">
          ${statBar('HP', creature.maxHp, 200, type.color)}
          ${statBar('ATK', creature.stats.atk, 175, type.color)}
          ${statBar('SPA', creature.stats.spa, 175, type.color)}
          ${statBar('SPE', creature.stats.spe, 175, type.color)}
        </div>
        <div class="tc-moves">${movesByGroup}</div>
      </div>
    </button>`;
}

export function panelMarkup(creature, team, activeIndex, isEnemy) {
  const type = TYPES[creature.type];
  const ratio = hpRatio(creature);
  const chips = [];
  if (creature.status) {
    const s = STATUS_INFO[creature.status];
    chips.push(`<span class="chip status" style="--c:${s.color}">${s.icon} ${s.name}</span>`);
  }
  if (creature.barrier > 0) chips.push(`<span class="chip barrier">◈ ${Math.round(creature.barrier)}</span>`);
  for (const stat of ['atk', 'def', 'spa', 'spd', 'spe']) {
    const stage = creature.stages[stat] || 0;
    if (stage !== 0) {
      const arrow = stage > 0 ? '▲' : '▼';
      chips.push(`<span class="chip stage">${stat.toUpperCase()} ${arrow}${Math.abs(stage)}</span>`);
    }
  }
  const pips = team
    .map((c, i) => `<i class="${c.fainted ? 'fainted' : 'alive'}${i === activeIndex ? ' current' : ''}"></i>`)
    .join('');
  const hpPercent = Math.max(0, ratio * 100);
  return `
    <div class="combatant-head">
      <span class="type-chip" style="--t:${type.color}">${type.name}</span>
      <span class="combatant-name">${creature.name}</span>
      <span class="level">LV. 50${isEnemy ? ' · WARDEN' : ''}</span>
    </div>
    <div class="hp-track">
      <div class="hp-ghost" style="width:${hpPercent}%"></div>
      <div class="hp-fill" style="width:${hpPercent}%;--hp:${hpColor(ratio)}"></div>
    </div>
    <div class="hp-meta">
      <span class="hp-text">${Math.max(0, Math.ceil(creature.hp))} / ${creature.maxHp}</span>
      <span class="status-chips">${chips.slice(0, 4).join('')}</span>
    </div>
    <div class="ability-line" title="${creature.ability.desc}">${creature.ability.name} — ${creature.ability.desc}</div>
    <div class="team-pips">${pips}</div>`;
}

export function moveCardMarkup(move, index, disabled) {
  const type = TYPES[move.type];
  const power = move.group === 'status' ? 'STATUS' : `PWR ${move.power}`;
  return `
    <button class="move-card ${move.group}" data-move="${index}" style="--t:${type.color}" ${disabled ? 'disabled' : ''}>
      <div class="mc-top">
        <span class="type-pill" style="--t:${type.color}">${type.name}</span>
        <span class="mc-pp">PP ${move.pp}/${move.maxPp}</span>
      </div>
      <div class="mc-name">${move.name}</div>
      <div class="mc-meta">
        <span class="power">${power}</span>
        <span>ACC ${move.accuracy}</span>
        <span>${move.priority > 0 ? '+PRIORITY' : move.flavor}</span>
      </div>
      <p class="mc-desc">${move.desc}</p>
    </button>`;
}

export function switchOptionMarkup(creature, index) {
  const type = TYPES[creature.type];
  const ratio = hpRatio(creature);
  return `
    <button class="switch-option" data-index="${index}" style="--t:${type.color};--hp:${hpColor(ratio)}">
      <div class="so-top">
        <span class="so-name">${creature.name}</span>
        <span class="so-type">${type.name}</span>
      </div>
      <div class="so-species">${creature.species} · ${creature.archetypeLabel}</div>
      <div class="so-hp"><i style="width:${ratio * 100}%"></i></div>
      <div class="so-meta"><span>${Math.ceil(creature.hp)} / ${creature.maxHp} HP</span><span>${creature.status ? STATUS_INFO[creature.status].name : 'READY'}</span></div>
      <div class="so-ability">${creature.ability.name} — ${creature.ability.desc}</div>
    </button>`;
}

export function codexMarkup(run) {
  const typeRows = TYPE_ORDER.map((key) => {
    const t = TYPES[key];
    const rel = typeRelation(key);
    return `<div class="type-row" style="--c:${t.color}">
      <b>${t.glyph} ${t.name}</b>
      <span>strong vs <em>${TYPES[rel.strong].name}</em> · weak vs <s>${TYPES[rel.weak].name}</s></span>
    </div>`;
  }).join('');

  const roster = run
    ? run.playerTeam.map((c) => {
        const type = TYPES[c.type];
        const moves = GROUP_ORDER.map((group) => {
          const list = c.moves.filter((m) => m.group === group).map((m) => m.name).join(' · ');
          return `<b style="color:${GROUPS[group].color}">${GROUPS[group].label}</b> ${list}`;
        }).join('<br>');
        return `<div class="roster-item" style="--t:${type.color}">
          <div class="ri-top"><b>${c.name}</b><span>${type.name} · ${c.archetypeLabel}</span></div>
          <div class="ri-moves">${moves}</div>
        </div>`;
      }).join('')
    : '<p>Enter a seed to forge a trio and their full move sets.</p>';

  return `
    <div class="codex-section">
      <h4>The Type Ring</h4>
      <p>Six elements form a closed ring. Each type deals 1.6× to the next type and 0.625× to the one before it. Same-type moves are neutral.</p>
      <div class="type-wheel">${typeRows}</div>
      <h4 style="margin-top:16px">Afflictions</h4>
      ${Object.values(STATUS_INFO).map((s) => `<p style="margin-bottom:5px"><b style="color:${s.color}">${s.icon} ${s.name}</b> — ${s.desc}</p>`).join('')}
    </div>
    <div class="codex-section">
      <h4>How to Duel</h4>
      <div class="controls-grid">
        <b>1 / 2</b><span>Use the first or second move in the selected group</span>
        <b>Q / E</b><span>Cycle Physical, Special and Status move groups</span>
        <b>B</b><span>Open the swap menu (costs your action)</span>
        <b>C</b><span>Open this codex</span>
        <b>M</b><span>Toggle sound</span>
      </div>
      <p>Physical moves scale with Attack and Defense. Special moves scale with Spirit and Ward. Status moves apply buffs, barriers, healing or afflictions. A creature may only carry one affliction at a time.</p>
      <p>Defeat all three of the Warden's creatures to clear the rift. Fainted creatures stay down until the run ends.</p>
      <h4 style="margin-top:16px">Your Trio</h4>
      <div class="roster-list">${roster}</div>
    </div>`;
}

import * as THREE from 'three';
import { GROUPS, STATUS_INFO, TYPES } from './data.js';
import {
  applyStageChange, calcDamage, chooseAiMove, chooseAiSwitch, effectiveSpeed,
} from './battle.js';
import { switchOptionMarkup } from './ui.js';

const ZERO_STAGES = () => ({ atk: 0, def: 0, spa: 0, spd: 0, spe: 0 });

export const battleMethods = {
  get pActive() {
    return this.battle ? this.battle.playerTeam[this.battle.playerActive] : null;
  },

  get eActive() {
    return this.battle ? this.battle.enemyTeam[this.battle.enemyActive] : null;
  },

  getModel(creature) {
    return this.models.get(creature.id);
  },

  homePos(creature) {
    const home = this.homes.get(creature.id);
    if (home) return home.clone();
    const model = this.getModel(creature);
    return model ? model.root.position.clone() : new THREE.Vector3();
  },

  headPos(creature) {
    const model = this.getModel(creature);
    const home = this.homePos(creature);
    if (!model) return home;
    const scale = model.root.scale.y || 1;
    return home.add(new THREE.Vector3(0, model.height * scale * 0.92, 0));
  },

  chestPos(creature) {
    const model = this.getModel(creature);
    const home = this.homePos(creature);
    if (!model) return home;
    const scale = model.root.scale.y || 1;
    return home.add(new THREE.Vector3(0, model.height * scale * 0.52, 0));
  },

  async resolveTurn(moveIndex) {
    if (this.state !== 'battle' || this.busy || this.modalOpen) return;
    const player = this.pActive;
    const enemy = this.eActive;
    if (!player || !enemy || player.fainted || enemy.fainted) return;
    const playerMove = player.moves[moveIndex];
    if (!playerMove || playerMove.pp <= 0) return;
    const enemyMove = chooseAiMove(enemy, player);
    this.busy = true;
    this.setTurn('RESOLVING');
    this.updateUI();

    const actions = [
      { side: 'player', creature: player, target: enemy, move: playerMove },
      { side: 'enemy', creature: enemy, target: player, move: enemyMove },
    ].filter((a) => a.move);

    actions.sort((a, b) => {
      const pri = (b.move.priority || 0) - (a.move.priority || 0);
      if (pri !== 0) return pri;
      const sa = effectiveSpeed(a.creature);
      const sb = effectiveSpeed(b.creature);
      if (sa !== sb) return sb - sa;
      return Math.random() - 0.5;
    });

    for (const action of actions) {
      if (this.state !== 'battle') return;
      if (action.creature.fainted || action.target.fainted) continue;
      await this.executeAction(action);
      if (this.state !== 'battle') return;
      if (action.target.fainted) break;
    }
    if (this.state !== 'battle') return;
    await this.afterActions();
  },

  async executeAction({ side, creature, target, move }) {
    if (!move || creature.fainted || target.fainted) return;
    if (creature.status === 'chill' && Math.random() < 0.2) {
      this.log(`${creature.name} is too chilled to move!`, 'bad');
      this.effects.aura(this.chestPos(creature), '#7dd3fc', { count: 14, radius: 0.8 });
      this.audio.miss();
      await this.sleep(700);
      return;
    }
    if (move.pp <= 0) {
      this.log(`${creature.name} has no power left for ${move.name}!`, 'bad');
      return;
    }
    move.pp -= 1;
    this.updateUI();
    this.log(`${creature.name} used ${move.name}!`, side);
    this.showToast(move.name);
    this.audio.attack(move.group, move.type);

    if (move.group === 'status') {
      await this.animateStatus(creature, target, move, side);
      if (Math.random() * 100 > move.accuracy) {
        this.effects.floater(this.headPos(target), 'MISS', 'miss');
        this.log(`${creature.name}'s ${move.name} missed!`, 'bad');
        this.audio.miss();
        await this.sleep(450);
        return;
      }
      let applied = false;
      for (const effect of move.effects) {
        if (effect.chance !== undefined && Math.random() > effect.chance) continue;
        const ok = await this.applyEffect(creature, target, effect, side);
        applied = applied || ok;
      }
      if (!applied) {
        this.log('But nothing happened!', 'system');
        this.showToast('NO EFFECT', 'bad');
      }
      this.updateUI();
      await this.sleep(420);
      return;
    }

    const result = calcDamage(creature, target, move);
    await this.animateAttack(creature, target, move, side);

    if (result.missed) {
      this.effects.floater(this.headPos(target), 'MISS', 'miss');
      this.log(`${creature.name}'s attack missed!`, 'bad');
      this.audio.miss();
      this.updateUI();
      await this.sleep(420);
      return;
    }

    await this.applyDamage(creature, target, move, result, side);

    if (!target.fainted && move.effects && move.effects.length) {
      for (const effect of move.effects) {
        if (effect.chance !== undefined && Math.random() > effect.chance) continue;
        await this.applyEffect(creature, target, effect, side);
      }
    }
    this.updateUI();
    await this.sleep(380);
  },

  async animateAttack(attacker, target, move, side) {
    const model = this.getModel(attacker);
    if (!model) return;
    const home = this.homePos(attacker);
    const targetHome = this.homePos(target);
    const dir = targetHome.clone().sub(home).setY(0).normalize();
    const baseScale = attacker.scale;
    const sign = side === 'player' ? 1 : -1;
    const color = TYPES[move.type].color;

    if (move.group === 'physical') {
      await this.tween(0.11, (p) => {
        model.root.position.copy(home).addScaledVector(dir, -0.22 * p);
        model.root.rotation.z = -sign * 0.06 * p;
      });
      await this.tween(0.13, (p) => {
        model.root.position.copy(home).addScaledVector(dir, 0.95 * p);
        model.root.rotation.z = sign * 0.12 * p;
      });
      this.effects.slash(this.chestPos(target), color, sign);
      this.shake = Math.max(this.shake, 0.5);
      await this.sleep(100);
      await this.tween(0.24, (p) => {
        model.root.position.copy(home).addScaledVector(dir, 0.95 * (1 - p));
        model.root.rotation.z = sign * 0.12 * (1 - p);
      });
    } else {
      await this.tween(0.16, (p) => {
        model.root.position.copy(home).add(new THREE.Vector3(0, 0.18 * p, 0));
        model.root.scale.setScalar(baseScale * (1 + 0.05 * p));
      });
      const from = this.chestPos(attacker);
      const to = this.chestPos(target);
      await this.effects.projectile(from, to, color, { duration: 0.52, size: 0.2, arc: 1.4 });
      this.effects.burst(to, color, { count: 36, speed: 4.6, size: 0.16, life: 0.7 });
      this.effects.ring(to, color, { radius: 1.5, life: 0.5 });
      this.shake = Math.max(this.shake, 0.65);
      await this.tween(0.18, (p) => {
        model.root.position.copy(home).add(new THREE.Vector3(0, 0.18 * (1 - p), 0));
        model.root.scale.setScalar(baseScale * (1.05 - 0.05 * p));
      });
    }
    model.root.position.copy(home);
    model.root.rotation.set(0, model.root.rotation.y, 0);
    model.root.scale.setScalar(baseScale);
  },

  async animateStatus(creature, target, move, side) {
    const model = this.getModel(creature);
    if (!model) return;
    const home = this.homePos(creature);
    const baseScale = creature.scale;
    const type = TYPES[move.type];
    const targetEffects = move.effects.filter((e) => e.target === 'foe');
    const color = targetEffects.length ? TYPES[move.type].color : '#7ff0b0';
    this.effects.aura(this.chestPos(creature), type.color, { count: 24, radius: 1.0, life: 1.2 });
    this.effects.ring(home.clone().add(new THREE.Vector3(0, 0.03, 0)), type.color, { flat: true, radius: 1.5, life: 0.8 });
    if (targetEffects.length) {
      this.effects.aura(this.chestPos(target), color, { count: 16, radius: 0.7, life: 0.9 });
    }
    await this.tween(0.38, (p) => {
      model.root.scale.setScalar(baseScale * (1 + Math.sin(p * Math.PI) * 0.07));
    });
    model.root.scale.setScalar(baseScale);
    await this.sleep(260);
  },

  async applyEffect(user, target, effect, side) {
    const targetCreature = effect.target === 'foe' ? target : user;
    const model = this.getModel(targetCreature);
    if (!model || targetCreature.fainted) return false;
    const typeColor = TYPES[user.type].color;
    const head = this.headPos(targetCreature);

    if (effect.kind === 'buff') {
      const changed = applyStageChange(user, effect.stat, effect.stages);
      if (!changed) return false;
      this.effects.aura(this.chestPos(user), '#ffe08a', { count: 18, radius: 0.8 });
      this.effects.floater(head, `${effect.stat.toUpperCase()} ▲${effect.stages}`, 'status', '#ffe08a');
      this.log(`${user.name}'s ${this.statName(effect.stat)} rose!`, 'good');
      if (user.ability.key === 'boostSpeed' && effect.stat !== 'spe') {
        const extra = applyStageChange(user, 'spe', 1);
        if (extra) {
          this.effects.floater(head.clone().add(new THREE.Vector3(0, 0.35, 0)), 'SPE ▲1', 'status', '#ffe08a');
          this.log(`${user.ability.name} also raised Speed!`, 'good');
        }
      }
      this.audio.buff();
      this.updateUI();
      await this.sleep(220);
      return true;
    }

    if (effect.kind === 'debuff') {
      const changed = applyStageChange(target, effect.stat, -effect.stages);
      if (!changed) return false;
      this.effects.aura(this.chestPos(target), '#a78bfa', { count: 16, radius: 0.8 });
      this.effects.floater(head, `${effect.stat.toUpperCase()} ▼${effect.stages}`, 'status', '#c4b5fd');
      this.log(`${target.name}'s ${this.statName(effect.stat)} fell!`, 'good');
      this.audio.debuff();
      this.updateUI();
      await this.sleep(220);
      return true;
    }

    if (effect.kind === 'heal') {
      const before = targetCreature.hp;
      const amount = Math.max(1, Math.round(targetCreature.maxHp * effect.amount));
      targetCreature.hp = Math.min(targetCreature.maxHp, targetCreature.hp + amount);
      const healed = targetCreature.hp - before;
      if (healed <= 0) return false;
      this.effects.aura(this.chestPos(targetCreature), '#7ff0b0', { count: 24, radius: 0.9, life: 1.3 });
      this.effects.floater(head, `+${healed}`, 'heal');
      this.log(`${targetCreature.name} restored ${healed} HP.`, 'good');
      this.audio.heal();
      this.updateUI();
      await this.sleep(320);
      return true;
    }

    if (effect.kind === 'barrier') {
      const amount = Math.round(targetCreature.maxHp * effect.amount);
      const before = targetCreature.barrier;
      targetCreature.barrier = Math.max(targetCreature.barrier, amount);
      if (targetCreature.barrier <= before) return false;
      this.effects.aura(this.chestPos(targetCreature), '#7dd3fc', { count: 20, radius: 1.0 });
      this.effects.ring(this.homePos(targetCreature), '#7dd3fc', { flat: true, radius: 1.2, life: 0.7 });
      this.effects.floater(head, `BARRIER ${targetCreature.barrier}`, 'status', '#7dd3fc');
      this.log(`${targetCreature.name} raised a barrier!`, 'good');
      this.audio.buff();
      this.updateUI();
      await this.sleep(280);
      return true;
    }

    if (effect.kind === 'status') {
      if (targetCreature.status) {
        this.log(`${targetCreature.name} already has an affliction.`, 'system');
        return false;
      }
      targetCreature.status = effect.status;
      const info = STATUS_INFO[effect.status];
      this.effects.aura(this.chestPos(targetCreature), info.color, { count: 22, radius: 0.9, life: 1.1 });
      this.effects.floater(head, `${info.icon} ${info.name.toUpperCase()}`, 'status', info.color);
      this.log(`${targetCreature.name} is ${info.name.toLowerCase()}ed!`, 'good');
      this.audio.debuff();
      this.updateUI();
      await this.sleep(320);
      return true;
    }

    if (effect.kind === 'cleanse') {
      if (!targetCreature.status) return false;
      targetCreature.status = null;
      this.effects.aura(this.chestPos(targetCreature), '#e8f7ff', { count: 20, radius: 0.9 });
      this.effects.floater(head, 'CURED', 'status', '#e8f7ff');
      this.log(`${targetCreature.name} was cured.`, 'good');
      this.audio.heal();
      this.updateUI();
      await this.sleep(250);
      return true;
    }
    return false;
  },

  async applyDamage(attacker, defender, move, result, side) {
    let damage = result.damage;
    let absorbed = 0;
    if (defender.barrier > 0) {
      absorbed = Math.min(defender.barrier, Math.round(damage * 0.55));
      defender.barrier -= absorbed;
      damage -= absorbed;
    }
    defender.hp = Math.max(0, defender.hp - damage);
    if (side === 'player') this.battle.damageDealt += damage;
    else this.battle.damageTaken += damage;

    const head = this.headPos(defender);
    const typeColor = TYPES[move.type].color;
    if (damage > 0) {
      this.effects.floater(head, `-${damage}`, result.crit ? 'crit' : '', typeColor);
    }
    if (absorbed > 0) {
      this.effects.floater(head.clone().add(new THREE.Vector3(0, 0.42, 0)), `BLOCKED ${absorbed}`, 'small', '#7dd3fc');
      this.log(`The barrier absorbed ${absorbed} damage.`, 'system');
    }
    if (result.crit) {
      this.effects.floater(head.clone().add(new THREE.Vector3(0, 0.85, 0)), 'CRITICAL', 'small', '#ffe08a');
      this.log('A critical hit!', 'good');
    }
    if (result.typeMult > 1.2) {
      this.log("It's super effective!", 'good');
      this.showToast('SUPER EFFECTIVE', 'good');
    } else if (result.typeMult < 0.9) {
      this.log("It's not very effective...", 'bad');
    }

    const model = this.getModel(defender);
    if (model) {
      model.flash('#ffffff', 0.95);
      this.hitShake(defender);
    }
    this.effects.burst(this.chestPos(defender), typeColor, { count: 20, speed: 3.2, size: 0.12, life: 0.5 });
    this.effects.ring(this.chestPos(defender), typeColor, { radius: 1.1, life: 0.4 });
    this.shake = Math.max(this.shake, 0.7);
    this.audio.hit(result.typeMult);
    this.updateUI();

    if (attacker.ability.key === 'lifesteal' && damage > 0 && !attacker.fainted) {
      const heal = Math.max(1, Math.round(damage * 0.15));
      const before = attacker.hp;
      attacker.hp = Math.min(attacker.maxHp, attacker.hp + heal);
      if (attacker.hp > before) {
        this.effects.floater(this.headPos(attacker), `+${attacker.hp - before}`, 'heal');
        this.log(`${attacker.ability.name} restored ${attacker.hp - before} HP.`, 'good');
        this.updateUI();
      }
    }

    if (defender.hp <= 0) await this.knockOut(defender);
  },

  hitShake(creature) {
    const model = this.getModel(creature);
    if (!model) return;
    const home = this.homePos(creature);
    this.tween(0.32, (p) => {
      const amp = Math.sin(p * Math.PI * 9) * 0.14 * (1 - p);
      model.root.position.copy(home).add(new THREE.Vector3(amp, 0, amp * 0.45));
    }).then(() => {
      if (!creature.fainted) model.root.position.copy(home);
    });
  },

  async knockOut(creature) {
    if (creature.fainted) return;
    creature.fainted = true;
    creature.hp = 0;
    creature.barrier = 0;
    creature.status = null;
    this.log(`${creature.name} fainted!`, 'bad');
    this.audio.faint();
    this.updateUI();
    const model = this.getModel(creature);
    if (model) {
      const home = this.homePos(creature);
      const dir = creature.side === 'player' ? 1 : -1;
      await this.tween(0.8, (p) => {
        model.root.rotation.z = dir * 1.32 * p;
        model.root.position.copy(home).add(new THREE.Vector3(0, -p * 0.25, 0));
        model.setOpacity(1 - p * 0.82);
      });
      model.root.visible = false;
      model.root.rotation.set(0, model.root.rotation.y, 0);
      model.root.position.copy(home);
      model.setOpacity(1);
    }
    this.updateUI();
    await this.sleep(350);
  },

  async endOfTurnEffects() {
    const actives = [this.pActive, this.eActive].filter(Boolean);
    for (const creature of actives) {
      if (this.state !== 'battle') return;
      if (creature.fainted) continue;
      const model = this.getModel(creature);
      if (!model) continue;

      if (creature.ability.key === 'heal' && creature.hp < creature.maxHp) {
        const amount = Math.max(1, Math.round(creature.maxHp * 0.06));
        const before = creature.hp;
        creature.hp = Math.min(creature.maxHp, creature.hp + amount);
        if (creature.hp > before) {
          this.effects.aura(this.chestPos(creature), '#7ff0b0', { count: 14, radius: 0.8 });
          this.effects.floater(this.headPos(creature), `+${creature.hp - before}`, 'heal');
          this.log(`${creature.ability.name} restored ${creature.hp - before} HP.`, 'good');
          this.updateUI();
          await this.sleep(240);
        }
      }

      if (creature.status === 'regen' && creature.hp < creature.maxHp) {
        const amount = Math.max(1, Math.round(creature.maxHp / 8));
        const before = creature.hp;
        creature.hp = Math.min(creature.maxHp, creature.hp + amount);
        if (creature.hp > before) {
          this.effects.aura(this.chestPos(creature), '#7ff0b0', { count: 16, radius: 0.9 });
          this.effects.floater(this.headPos(creature), `+${creature.hp - before}`, 'heal');
          this.log(`Regen restored ${creature.hp - before} HP to ${creature.name}.`, 'good');
          this.updateUI();
          await this.sleep(240);
        }
      }

      if (creature.status === 'burn' || creature.status === 'poison') {
        const info = STATUS_INFO[creature.status];
        const amount = creature.status === 'burn'
          ? Math.max(1, Math.round(creature.maxHp / 16))
          : Math.max(1, Math.round(creature.maxHp / 10));
        creature.hp = Math.max(0, creature.hp - amount);
        this.effects.aura(this.chestPos(creature), info.color, { count: 12, radius: 0.8 });
        this.effects.floater(this.headPos(creature), `-${amount}`, '', info.color);
        this.log(`${creature.name} is hurt by ${info.name.toLowerCase()}!`, 'bad');
        model.flash(info.color, 0.6);
        this.audio.hit(0.65);
        this.updateUI();
        await this.sleep(360);
        if (creature.hp <= 0) await this.knockOut(creature);
      }

      if (creature.ability.key === 'statusCure' && creature.status && !creature.fainted) {
        if (Math.random() < 0.3) {
          creature.status = null;
          this.effects.aura(this.chestPos(creature), '#e8f7ff', { count: 16, radius: 0.8 });
          this.effects.floater(this.headPos(creature), 'CURED', 'status', '#e8f7ff');
          this.log(`${creature.ability.name} cured ${creature.name}.`, 'good');
          this.updateUI();
          await this.sleep(220);
        }
      }
    }
  },

  async afterActions() {
    if (this.state !== 'battle') return;
    if (this.battle.playerTeam.every((c) => c.fainted)) {
      await this.endBattle(false);
      return;
    }
    if (this.battle.enemyTeam.every((c) => c.fainted)) {
      await this.endBattle(true);
      return;
    }

    await this.endOfTurnEffects();
    if (this.state !== 'battle') return;

    if (this.battle.playerTeam.every((c) => c.fainted)) {
      await this.endBattle(false);
      return;
    }
    if (this.battle.enemyTeam.every((c) => c.fainted)) {
      await this.endBattle(true);
      return;
    }

    const playerFainted = this.pActive.fainted;
    const enemyFainted = this.eActive.fainted;
    if (enemyFainted) await this.sendNextEnemy();
    if (playerFainted) {
      this.openSwitch(true);
      return;
    }

    this.battle.round += 1;
    this.busy = false;
    this.updateUI();
    this.setTurn('YOUR MOVE');
    this.log(`— Round ${this.battle.round} —`, 'system');
  },

  async sendNextEnemy() {
    const next = chooseAiSwitch(this.battle.enemyTeam, this.pActive);
    if (!next) return false;
    const index = this.battle.enemyTeam.indexOf(next);
    this.battle.enemyActive = index;
    next.stages = ZERO_STAGES();
    const model = this.enemyModels[index];
    if (!model) return false;
    this.placeModel(model, this.ENEMY_SPOT, this.ENEMY_ROT, true);
    this.log(`${this.run.warden.name} sent out ${next.name}!`, 'enemy');
    this.updateUI();
    await this.sendOutAnim(model, next);
    await this.sleep(420);
    return true;
  },

  async sendOutAnim(model, creature) {
    const home = this.homePos(creature);
    const baseScale = creature.scale;
    model.root.visible = true;
    model.setOpacity(0);
    model.root.scale.setScalar(baseScale * 0.2);
    this.effects.ring(home.clone().add(new THREE.Vector3(0, 0.04, 0)), TYPES[creature.type].color, { flat: true, radius: 1.4, life: 0.7 });
    this.effects.aura(this.chestPos(creature), TYPES[creature.type].color, { count: 18, radius: 0.8, life: 0.8 });
    this.audio.sendOut();
    this.audio.cry(creature.type, creature.seed);
    await this.tween(0.42, (p) => {
      model.root.scale.setScalar(baseScale * (0.2 + p * 0.8));
      model.setOpacity(Math.min(1, p * 1.5));
    });
    model.root.scale.setScalar(baseScale);
    model.setOpacity(1);
  },

  async recallAnim(model) {
    if (!model) return;
    const baseScale = model.root.scale.y || 1;
    await this.tween(0.28, (p) => {
      model.root.scale.setScalar(baseScale * (1 - p * 0.8));
      model.setOpacity(1 - p);
    });
    model.root.visible = false;
    model.root.scale.setScalar(baseScale);
    model.setOpacity(1);
  },

  openSwitch(forced = false) {
    if (this.state !== 'battle' || this.modalOpen) return;
    if (!forced && this.busy) return;
    const team = this.battle.playerTeam;
    const options = team
      .map((c, index) => ({ c, index }))
      .filter(({ c, index }) => !c.fainted && index !== this.battle.playerActive);
    if (!options.length) {
      if (forced) this.endBattle(false);
      return;
    }
    this.switchForced = forced;
    this.busy = true;
    this.modalOpen = true;
    this.dom.switchGrid.innerHTML = options.map(({ c, index }) => switchOptionMarkup(c, index)).join('');
    this.dom.switchNote.textContent = forced
      ? 'Your creature fainted. Choose the next one to enter the rift.'
      : 'Switching uses your action for the round. The Warden will attack.';
    this.dom.switchCancel.classList.toggle('hidden', forced);
    this.dom.switchModal.classList.remove('hidden');
    this.audio.click();
    this.updateUI();
  },

  closeSwitch() {
    if (this.switchForced) return;
    this.dom.switchModal.classList.add('hidden');
    this.modalOpen = false;
    this.busy = false;
    this.switchForced = false;
    this.updateUI();
    this.audio.click();
  },

  async switchTo(index) {
    if (this.state !== 'battle') return;
    const team = this.battle.playerTeam;
    const target = team[index];
    if (!target || target.fainted || index === this.battle.playerActive) return;
    const forced = this.switchForced;
    this.dom.switchModal.classList.add('hidden');
    this.modalOpen = false;
    this.switchForced = false;
    this.audio.click();

    if (forced) {
      this.busy = true;
      this.battle.playerActive = index;
      target.stages = ZERO_STAGES();
      const model = this.playerModels[index];
      this.placeModel(model, this.PLAYER_SPOT, this.PLAYER_ROT, true);
      this.log(`Go, ${target.name}!`, 'player');
      this.updateUI();
      await this.sendOutAnim(model, target);
      this.battle.round += 1;
      this.busy = false;
      this.updateUI();
      this.setTurn('YOUR MOVE');
      this.log(`— Round ${this.battle.round} —`, 'system');
      return;
    }

    this.busy = true;
    this.updateUI();
    const old = this.pActive;
    const oldModel = this.getModel(old);
    if (oldModel && !old.fainted) {
      this.log(`You recalled ${old.name}.`, 'player');
      await this.recallAnim(oldModel);
    }
    this.battle.playerActive = index;
    target.stages = ZERO_STAGES();
    const model = this.playerModels[index];
    this.placeModel(model, this.PLAYER_SPOT, this.PLAYER_ROT, true);
    this.log(`Go, ${target.name}!`, 'player');
    this.updateUI();
    await this.sendOutAnim(model, target);

    const enemy = this.eActive;
    const enemyMove = enemy && !enemy.fainted ? chooseAiMove(enemy, target) : null;
    if (enemyMove) {
      await this.executeAction({ side: 'enemy', creature: enemy, target, move: enemyMove });
    }
    if (this.state === 'battle') await this.afterActions();
  },

  async endBattle(victory) {
    if (this.state === 'end') return;
    this.state = 'end';
    this.busy = true;
    this.modalOpen = false;
    this.dom.switchModal.classList.add('hidden');
    this.dom.codexModal.classList.add('hidden');
    this.dom.hintBar.classList.add('hidden');
    this.updateUI();
    this.setTurn('DUEL OVER');
    this.log(victory ? `${this.run.warden.name} has been defeated!` : 'Your trio has fallen...', victory ? 'good' : 'bad');
    this.showBanner(
      victory ? 'RIFT CLEARED' : 'RIFT CLAIMED',
      victory ? 'CHAMPION' : 'DEFEAT',
      victory ? this.run.room.name : this.run.warden.name,
      2400,
    );
    if (victory) {
      this.audio.victory();
      const model = this.getModel(this.pActive);
      if (model) {
        const base = this.pActive.scale;
        this.tween(1.2, (p) => {
          const bounce = Math.abs(Math.sin(p * Math.PI * 3)) * (1 - p) * 0.35;
          model.root.position.y = this.homePos(this.pActive).y + bounce;
          model.root.scale.setScalar(base * (1 + Math.sin(p * Math.PI) * 0.05));
        });
      }
    } else {
      this.audio.defeat();
    }
    clearTimeout(this.endTimer);
    this.endTimer = setTimeout(() => this.showEndScreen(victory), 1900);
  },
};

import * as THREE from 'three';
import './style.css';
import { generateRun, generateShowcase, restoreTeam } from './generate.js';
import { createCreatureModel } from './model.js';
import { createRoom, createSelectStage } from './room.js';
import { Effects } from './effects.js';
import { GameAudio } from './audio.js';
import { RNG, randomSeed } from './rng.js';
import { GROUPS, GROUP_ORDER, TYPES } from './data.js';
import { effectiveSpeed } from './battle.js';
import { battleMethods } from './battle-flow.js';
import {
  codexMarkup, moveCardMarkup, panelMarkup, switchOptionMarkup, teamCardMarkup,
} from './ui.js';

const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => Array.from(root.querySelectorAll(sel));
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const easeOutCubic = (p) => 1 - Math.pow(1 - p, 3);

const PLAYER_SPOT = new THREE.Vector3(-3.35, 0, 2.55);
const ENEMY_SPOT = new THREE.Vector3(3.35, 0, -2.0);
const PLAYER_ROT = Math.atan2(ENEMY_SPOT.x - PLAYER_SPOT.x, ENEMY_SPOT.z - PLAYER_SPOT.z);
const ENEMY_ROT = Math.atan2(PLAYER_SPOT.x - ENEMY_SPOT.x, PLAYER_SPOT.z - ENEMY_SPOT.z);

export class RiftGame {
  constructor() {
    this.dom = {
      canvas: $('#scene'),
      loading: $('#sceneLoading'),
      flash: $('#flash'),
      titleScreen: $('#titleScreen'),
      selectScreen: $('#selectScreen'),
      endScreen: $('#endScreen'),
      hud: $('#hud'),
      dock: $('#dock'),
      seedInput: $('#seedInput'),
      diceBtn: $('#diceBtn'),
      beginBtn: $('#beginBtn'),
      howBtn: $('#howBtn'),
      showcaseName: $('#showcaseName'),
      showcaseMeta: $('#showcaseMeta'),
      teamCards: $('#teamCards'),
      selectSeed: $('#selectSeed'),
      selectRoom: $('#selectRoom'),
      wardenName: $('#wardenName'),
      wardenSub: $('#wardenSub'),
      deployBtn: $('#deployBtn'),
      enemyPanel: $('#enemyPanel'),
      playerPanel: $('#playerPanel'),
      roundNum: $('#roundNum'),
      duelRoom: $('#duelRoom'),
      battleLog: $('#battleLog'),
      groupTabs: $('#groupTabs'),
      moveGrid: $('#moveGrid'),
      turnLabel: $('#turnLabel'),
      activeSummary: $('#activeSummary'),
      switchBtn: $('#switchBtn'),
      codexBtn: $('#codexBtn'),
      muteBtn: $('#muteBtn'),
      switchModal: $('#switchModal'),
      switchGrid: $('#switchGrid'),
      switchNote: $('#switchNote'),
      switchCancel: $('#switchCancel'),
      codexModal: $('#codexModal'),
      codexBody: $('#codexBody'),
      floaters: $('#floaters'),
      banner: $('#banner'),
      bannerKicker: $('#banner .banner-kicker'),
      bannerTitle: $('#banner .banner-title'),
      bannerSub: $('#banner .banner-sub'),
      toast: $('#toast'),
      hintBar: $('#hintBar'),
      hintText: $('#hintText'),
      hintClose: $('#hintClose'),
      endKicker: $('#endKicker'),
      endTitle: $('#endTitle'),
      endText: $('#endText'),
      endStats: $('#endStats'),
      endSeed: $('#endSeed'),
      rematchBtn: $('#rematchBtn'),
      newRiftBtn: $('#newRiftBtn'),
    };

    this.renderer = new THREE.WebGLRenderer({
      canvas: this.dom.canvas,
      antialias: true,
      powerPreference: 'high-performance',
    });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.5));
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.12;

    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color('#05070c');
    this.scene.fog = new THREE.FogExp2('#05070c', 0.018);
    this.camera = new THREE.PerspectiveCamera(42, window.innerWidth / window.innerHeight, 0.1, 140);
    this.camera.position.set(7.1, 4.6, 11.4);
    this.cameraLook = new THREE.Vector3(0.6, 1.75, 0);
    this.camera.lookAt(this.cameraLook);
    this.camRig = { pos: new THREE.Vector3(7.1, 4.6, 11.4), target: new THREE.Vector3(0.6, 1.75, 0) };

    this.effects = new Effects(this.scene, this.camera, this.dom.floaters);
    this.audio = new GameAudio();
    this.clock = new THREE.Clock();

    this.models = new Map();
    this.homes = new Map();
    this.playerModels = [];
    this.enemyModels = [];
    this.tweens = [];
    this.state = 'boot';
    this.busy = false;
    this.modalOpen = false;
    this.switchForced = false;
    this.currentGroup = 'physical';
    this.selectedLead = null;
    this.run = null;
    this.room = null;
    this.stage = null;
    this.battle = null;
    this.showcaseModel = null;
    this.seed = '';
    this.time = 0;
    this.shake = 0;
    this.bannerTimer = null;
    this.toastTimer = null;
    this.hintTimer = null;
    this.endTimer = null;

    this.PLAYER_SPOT = PLAYER_SPOT;
    this.ENEMY_SPOT = ENEMY_SPOT;
    this.PLAYER_ROT = PLAYER_ROT;
    this.ENEMY_ROT = ENEMY_ROT;

    this.bindEvents();
    this.resize();
    const params = new URLSearchParams(window.location.search);
    const initialSeed = this.normalizeSeed(params.get('seed') || randomSeed());
    this.dom.seedInput.value = initialSeed;
    this.loadTitle(initialSeed);
    this.animate();
    setTimeout(() => {
      this.dom.loading.classList.add('fade');
      setTimeout(() => this.dom.loading.classList.add('hidden'), 700);
    }, 500);
  }

  normalizeSeed(raw) {
    const cleaned = String(raw || '').toUpperCase().replace(/[^A-Z0-9-]/g, '').slice(0, 16);
    return cleaned || randomSeed();
  }

  sleep(ms) {
    return sleep(ms);
  }

  tween(duration, fn) {
    return new Promise((resolve) => {
      this.tweens.push({ age: 0, duration: Math.max(0.001, duration), fn, resolve });
    });
  }

  updateTweens(dt) {
    const list = this.tweens;
    this.tweens = [];
    for (const tw of list) {
      tw.age += dt;
      const raw = Math.min(1, tw.age / tw.duration);
      tw.fn(easeOutCubic(raw), raw);
      if (raw < 1) this.tweens.push(tw);
      else tw.resolve();
    }
  }

  /* ══════════════ SCENE / TITLE ══════════════ */
  loadTitle(seed) {
    this.state = 'title';
    this.busy = false;
    this.modalOpen = false;
    this.cleanupScene();
    this.seed = this.normalizeSeed(seed);
    this.titleSeed = this.seed;
    this.dom.seedInput.value = this.seed;
    this.dom.titleScreen.classList.remove('hidden');
    this.dom.selectScreen.classList.add('hidden');
    this.dom.endScreen.classList.add('hidden');
    this.dom.hud.classList.add('hidden');
    this.dom.dock.classList.add('hidden');
    this.dom.battleLog.innerHTML = '';

    const roomConfig = generateRun(this.seed).room;
    this.room = createRoom(this.scene, roomConfig);
    this.scene.fog = new THREE.FogExp2(roomConfig.theme.fog, roomConfig.fogDensity);
    this.scene.background = new THREE.Color(roomConfig.theme.bg);

    const showcase = generateShowcase(this.seed);
    const model = createCreatureModel(showcase);
    model.root.position.set(1.9, 0.02, 0.4);
    model.root.rotation.y = -0.25;
    this.scene.add(model.root);
    this.showcaseModel = model;
    this.models.set(showcase.id, model);

    this.dom.showcaseName.textContent = showcase.name;
    this.dom.showcaseMeta.textContent = `${TYPES[showcase.type].name} · ${showcase.species} · ${showcase.archetypeLabel}`;

    this.camera.position.set(7.1, 4.6, 11.4);
    this.cameraLook.set(0.6, 1.75, 0);
    this.camRig.pos.copy(this.camera.position);
    this.camRig.target.copy(this.cameraLook);
    this.camera.lookAt(this.cameraLook);
    this.audio.setMuted(this.audio.muted);
  }

  cleanupScene() {
    clearTimeout(this.endTimer);
    clearTimeout(this.hintTimer);
    this.tweens = [];
    this.effects.clear();
    for (const model of this.models.values()) {
      model.dispose();
      model.root.removeFromParent();
    }
    this.models.clear();
    this.homes.clear();
    this.playerModels = [];
    this.enemyModels = [];
    this.showcaseModel = null;
    if (this.room) {
      this.room.dispose();
      this.room = null;
    }
    if (this.stage) {
      this.stage.dispose();
      this.stage = null;
    }
    this.battle = null;
    this.busy = false;
    this.modalOpen = false;
    this.switchForced = false;
  }

  enterRift(rawSeed) {
    if (!['title', 'end'].includes(this.state)) return;
    this.audio.init();
    this.audio.confirm();
    const seed = this.normalizeSeed(rawSeed || this.dom.seedInput.value);
    this.cleanupScene();
    this.seed = seed;
    this.dom.seedInput.value = seed;
    this.run = generateRun(seed);

    this.scene.fog = new THREE.FogExp2(this.run.room.theme.fog, this.run.room.fogDensity);
    this.scene.background = new THREE.Color(this.run.room.theme.bg);
    this.room = createRoom(this.scene, this.run.room);
    this.stage = createSelectStage(this.scene, this.run.room);

    this.playerModels = this.run.playerTeam.map((creature, index) => {
      const model = createCreatureModel(creature);
      const pedestal = this.stage.pedestals[index];
      model.root.position.set(pedestal.group.position.x, 0.79, pedestal.group.position.z);
      model.root.rotation.y = 0;
      model.root.scale.setScalar(creature.scale);
      this.scene.add(model.root);
      this.models.set(creature.id, model);
      this.homes.set(creature.id, model.root.position.clone());
      return model;
    });

    this.selectedLead = null;
    this.busy = false;
    this.modalOpen = false;
    this.state = 'select';
    this.currentGroup = 'physical';
    this.dom.titleScreen.classList.add('hidden');
    this.dom.endScreen.classList.add('hidden');
    this.dom.selectScreen.classList.remove('hidden');
    this.dom.hud.classList.add('hidden');
    this.dom.dock.classList.add('hidden');
    this.dom.deployBtn.disabled = true;
    this.buildSelectUI();
    this.updateCameraRig();
    window.history.replaceState(null, '', `?seed=${encodeURIComponent(seed)}`);
  }

  buildSelectUI() {
    this.dom.selectSeed.textContent = this.run.seed;
    this.dom.selectRoom.textContent = this.run.room.name;
    this.dom.wardenName.textContent = this.run.warden.name;
    this.dom.wardenSub.textContent = this.run.warden.title;
    this.dom.teamCards.innerHTML = this.run.playerTeam.map((c, i) => teamCardMarkup(c, i)).join('');
    for (const card of $$('.team-card', this.dom.teamCards)) {
      card.addEventListener('click', () => this.selectLead(Number(card.dataset.index)));
    }
    for (const pedestal of this.stage.pedestals) pedestal.selected = false;
  }

  selectLead(index) {
    if (this.state !== 'select') return;
    this.selectedLead = index;
    this.audio.init();
    this.audio.select();
    for (const card of $$('.team-card', this.dom.teamCards)) {
      card.classList.toggle('selected', Number(card.dataset.index) === index);
    }
    this.dom.deployBtn.disabled = false;
    this.playerModels.forEach((model, i) => {
      const creature = this.run.playerTeam[i];
      const target = creature.scale * (i === index ? 1.16 : 1);
      this.tween(0.35, (p) => {
        const current = model.root.scale.x;
        model.root.scale.setScalar(current + (target - current) * Math.min(1, p * 0.22));
      });
      if (this.stage) this.stage.pedestals[i].selected = i === index;
    });
  }

  deploy() {
    if (this.state !== 'select' || this.selectedLead === null) return;
    this.audio.init();
    this.audio.confirm();
    const lead = this.selectedLead;
    this.dom.selectScreen.classList.add('hidden');
    this.dom.hud.classList.remove('hidden');
    this.dom.dock.classList.remove('hidden');
    this.dom.battleLog.innerHTML = '';
    this.dom.roundNum.textContent = '1';
    this.dom.duelRoom.textContent = this.run.room.name;
    this.state = 'battle';
    this.busy = false;
    this.currentGroup = 'physical';

    this.battle = {
      playerTeam: this.run.playerTeam,
      enemyTeam: this.run.enemyTeam,
      playerActive: lead,
      enemyActive: 0,
      round: 1,
      damageDealt: 0,
      damageTaken: 0,
      startedAt: Date.now(),
    };

    this.buildEnemyModels();
    if (this.stage) {
      this.stage.dispose();
      this.stage = null;
    }

    this.playerModels.forEach((model, index) => {
      if (index === lead) {
        this.placeModel(model, this.PLAYER_SPOT, this.PLAYER_ROT, true);
      } else {
        model.root.visible = false;
      }
    });
    this.placeModel(this.enemyModels[0], this.ENEMY_SPOT, this.ENEMY_ROT, true);
    this.updateCameraRig();
    this.updateUI();
    this.log(`${this.run.warden.name} accepts your challenge.`, 'enemy');
    this.log(`Go, ${this.pActive.name}!`, 'player');
    this.showBanner('RIFT DUEL', this.run.room.name, this.run.warden.title, 2400);
    this.showHint('<b>Pick a move group</b>, then a move. <b>Q/E</b> cycles groups · <b>B</b> swaps creatures · <b>C</b> opens the codex.');
    this.sendOutAnim(this.playerModels[lead], this.pActive);
    setTimeout(() => {
      if (this.state !== 'battle') return;
      this.sendOutAnim(this.enemyModels[0], this.eActive);
      this.log(`${this.run.warden.name} sent out ${this.eActive.name}!`, 'enemy');
    }, 450);
    setTimeout(() => {
      if (this.state !== 'battle') return;
      this.setTurn('YOUR MOVE');
      this.updateUI();
    }, 1500);
    this.setTurn('DEPLOYING');
  }

  buildEnemyModels() {
    this.enemyModels = this.run.enemyTeam.map((creature) => {
      const model = createCreatureModel(creature);
      model.root.visible = false;
      this.scene.add(model.root);
      this.models.set(creature.id, model);
      return model;
    });
  }

  placeModel(model, position, rotation, visible = true) {
    if (!model) return;
    model.root.position.copy(position);
    model.root.rotation.set(0, rotation, 0);
    model.root.scale.setScalar(model.creature.scale);
    model.root.visible = visible;
    model.setOpacity(1);
    this.homes.set(model.creature.id, position.clone());
  }

  resetModel(model, creature, position, rotation, visible) {
    if (!model) return;
    model.root.position.copy(position);
    model.root.rotation.set(0, rotation, 0);
    model.root.scale.setScalar(creature.scale);
    model.root.visible = visible;
    model.setOpacity(1);
    this.homes.set(creature.id, position.clone());
  }

  /* ══════════════ UI ══════════════ */
  updateUI() {
    if (!this.battle || !['battle', 'end'].includes(this.state)) return;
    this.renderCombatant(this.dom.enemyPanel, this.eActive, this.battle.enemyTeam, this.battle.enemyActive, true);
    this.renderCombatant(this.dom.playerPanel, this.pActive, this.battle.playerTeam, this.battle.playerActive, false);
    this.dom.roundNum.textContent = String(this.battle.round);
    this.renderMoves();
    const bench = this.battle.playerTeam.filter((c, i) => !c.fainted && i !== this.battle.playerActive).length;
    this.dom.switchBtn.disabled = this.busy || bench === 0;
    const active = this.pActive;
    this.dom.activeSummary.textContent = active ? `${active.name} · ${active.ability.name}` : '';
  }

  renderCombatant(panel, creature, team, activeIndex, isEnemy) {
    if (!panel || !creature) return;
    const type = TYPES[creature.type];
    panel.style.setProperty('--t', type.color);
    const ratio = Math.max(0, creature.hp / creature.maxHp);
    const previous = panel.dataset.hp ? Number(panel.dataset.hp) : ratio;
    panel.innerHTML = panelMarkup(creature, team, activeIndex, isEnemy);
    panel.dataset.hp = String(ratio);
    const fill = $('.hp-fill', panel);
    const ghost = $('.hp-ghost', panel);
    if (fill) fill.style.width = `${Math.max(0, previous) * 100}%`;
    if (ghost) ghost.style.width = `${Math.max(0, previous) * 100}%`;
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        if (fill) fill.style.width = `${ratio * 100}%`;
        if (ghost) ghost.style.width = `${ratio * 100}%`;
      });
    });
  }

  renderMoves() {
    if (!this.battle) return;
    const active = this.pActive;
    if (!active) return;
    for (const tab of $$('.group-tab', this.dom.groupTabs)) {
      const group = tab.dataset.group;
      tab.classList.toggle('active', group === this.currentGroup);
      const usable = active.moves.filter((m) => m.group === group && m.pp > 0).length;
      const count = $(`[data-count="${group}"]`, this.dom.groupTabs);
      if (count) count.textContent = String(usable);
      tab.style.opacity = usable === 0 ? '0.45' : '';
    }
    const moves = active.moves
      .map((move, index) => ({ move, index }))
      .filter(({ move }) => move.group === this.currentGroup);
    const disabled = this.busy || this.state !== 'battle';
    if (!moves.length) {
      this.dom.moveGrid.innerHTML = '<div style="padding:20px;color:var(--muted-dim);font-size:10px;letter-spacing:.1em">No moves in this group.</div>';
    } else {
      this.dom.moveGrid.innerHTML = moves
        .map(({ move, index }) => moveCardMarkup(move, index, disabled || move.pp <= 0))
        .join('');
    }
  }

  setTurn(text) {
    this.dom.turnLabel.textContent = text;
  }

  log(text, kind = 'system') {
    if (!this.dom.battleLog) return;
    const line = document.createElement('div');
    line.className = `log-line ${kind}`;
    line.textContent = text;
    this.dom.battleLog.appendChild(line);
    while (this.dom.battleLog.children.length > 7) this.dom.battleLog.firstElementChild.remove();
  }

  showBanner(kicker, title, sub, duration = 2100) {
    clearTimeout(this.bannerTimer);
    this.dom.bannerKicker.textContent = kicker;
    this.dom.bannerTitle.textContent = title;
    this.dom.bannerSub.textContent = sub || '';
    this.dom.banner.classList.remove('hidden');
    this.bannerTimer = setTimeout(() => this.dom.banner.classList.add('hidden'), duration);
  }

  showToast(text, kind = '') {
    clearTimeout(this.toastTimer);
    this.dom.toast.textContent = text;
    this.dom.toast.className = kind;
    this.dom.toast.classList.remove('hidden');
    void this.dom.toast.offsetWidth;
    this.toastTimer = setTimeout(() => this.dom.toast.classList.add('hidden'), 1800);
  }

  showHint(html) {
    clearTimeout(this.hintTimer);
    this.dom.hintText.innerHTML = html;
    this.dom.hintBar.classList.remove('hidden');
    this.hintTimer = setTimeout(() => this.dom.hintBar.classList.add('hidden'), 12000);
  }

  hideHint() {
    clearTimeout(this.hintTimer);
    this.dom.hintBar.classList.add('hidden');
  }

  statName(stat) {
    return { atk: 'Attack', def: 'Defense', spa: 'Spirit', spd: 'Ward', spe: 'Speed' }[stat] || stat;
  }

  /* ══════════════ CAMERA / LOOP ══════════════ */
  updateCameraRig() {
    if (this.state === 'title') {
      this.camRig.pos.set(
        7.1 + Math.sin(this.time * 0.09) * 0.5,
        4.6 + Math.sin(this.time * 0.13) * 0.1,
        11.4 + Math.cos(this.time * 0.07) * 0.22,
      );
      this.camRig.target.set(0.6, 1.78, 0);
    } else if (this.state === 'select') {
      this.camRig.pos.set(Math.sin(this.time * 0.18) * 0.12, 4.95, 11.75);
      this.camRig.target.set(0, 1.95, -1.3);
    } else if (this.state === 'battle') {
      this.camRig.pos.set(0.7 + Math.sin(this.time * 0.24) * 0.13, 5.2 + Math.sin(this.time * 0.31) * 0.05, 13.4);
      this.camRig.target.set(0, 1.78, -0.4);
    } else if (this.state === 'end') {
      this.camRig.pos.set(1.2, 4.8, 14.2);
      this.camRig.target.set(0, 1.9, 0);
    }
  }

  animate = () => {
    requestAnimationFrame(this.animate);
    const dt = Math.min(this.clock.getDelta(), 0.05);
    this.time += dt;
    this.updateTweens(dt);
    if (this.room) this.room.update(this.time, dt);
    if (this.stage) this.stage.update(this.time);
    for (const model of this.models.values()) {
      if (model.root.visible) model.update(this.time, dt);
    }
    this.effects.update(dt);
    this.updateCameraRig();
    const lerp = 1 - Math.exp(-dt * 3.4);
    this.camera.position.lerp(this.camRig.pos, lerp);
    this.cameraLook.lerp(this.camRig.target, lerp);
    this.shake *= Math.exp(-dt * 8);
    const shakeX = Math.sin(this.time * 91) * this.shake * 0.07;
    const shakeY = Math.cos(this.time * 77) * this.shake * 0.05;
    this.camera.position.x += shakeX;
    this.camera.position.y += shakeY;
    this.camera.lookAt(this.cameraLook);
    this.renderer.render(this.scene, this.camera);
  };

  resize() {
    const width = window.innerWidth;
    const height = window.innerHeight;
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.5));
    this.renderer.setSize(width, height);
    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();
  }

  /* ══════════════ EVENTS ══════════════ */
  bindEvents() {
    window.addEventListener('resize', () => this.resize());

    this.dom.beginBtn.addEventListener('click', () => this.enterRift());
    this.dom.diceBtn.addEventListener('click', () => {
      if (this.state !== 'title') return;
      this.audio.init();
      this.audio.click();
      const seed = randomSeed();
      this.loadTitle(seed);
    });
    this.dom.seedInput.addEventListener('keydown', (event) => {
      if (event.key === 'Enter') {
        if (this.state === 'title') this.enterRift();
      }
    });
    this.dom.seedInput.addEventListener('input', () => {
      this.dom.seedInput.value = this.dom.seedInput.value.toUpperCase().replace(/[^A-Z0-9-]/g, '').slice(0, 16);
    });
    this.dom.howBtn.addEventListener('click', () => this.openCodex());
    this.dom.deployBtn.addEventListener('click', () => this.deploy());

    this.dom.groupTabs.addEventListener('click', (event) => {
      const tab = event.target.closest('.group-tab');
      if (!tab || this.state !== 'battle' || this.busy) return;
      this.currentGroup = tab.dataset.group;
      this.audio.init();
      this.audio.click();
      this.renderMoves();
    });

    this.dom.moveGrid.addEventListener('click', (event) => {
      const card = event.target.closest('.move-card');
      if (!card || card.disabled) return;
      this.audio.init();
      this.audio.click();
      this.resolveTurn(Number(card.dataset.move));
    });

    this.dom.switchBtn.addEventListener('click', () => this.openSwitch(false));
    this.dom.codexBtn.addEventListener('click', () => this.openCodex());
    this.dom.muteBtn.addEventListener('click', () => this.toggleMute());
    this.dom.hintClose.addEventListener('click', () => this.hideHint());
    this.dom.switchCancel.addEventListener('click', () => this.closeSwitch());
    this.dom.switchGrid.addEventListener('click', (event) => {
      const option = event.target.closest('.switch-option');
      if (!option) return;
      this.switchTo(Number(option.dataset.index));
    });

    for (const btn of $$('[data-close]')) {
      btn.addEventListener('click', () => {
        if (btn.dataset.close === 'switch') this.closeSwitch();
        else this.closeCodex();
      });
    }

    this.dom.endScreen.addEventListener('click', (event) => {
      if (event.target.closest('#rematchBtn')) this.rematch();
      if (event.target.closest('#newRiftBtn')) this.newRift();
    });

    this.dom.canvas.addEventListener('click', (event) => this.onCanvasClick(event));

    window.addEventListener('keydown', (event) => this.onKeyDown(event));
  }

  onCanvasClick(event) {
    if (this.state !== 'select') return;
    const rect = this.dom.canvas.getBoundingClientRect();
    const pointer = new THREE.Vector2(
      ((event.clientX - rect.left) / rect.width) * 2 - 1,
      -((event.clientY - rect.top) / rect.height) * 2 + 1,
    );
    const raycaster = new THREE.Raycaster();
    raycaster.setFromCamera(pointer, this.camera);
    const roots = this.playerModels.map((m) => m.root);
    const hits = raycaster.intersectObjects(roots, true);
    if (!hits.length) return;
    let node = hits[0].object;
    while (node && !roots.includes(node)) node = node.parent;
    if (!node) return;
    const index = this.playerModels.findIndex((m) => m.root === node);
    if (index >= 0) this.selectLead(index);
  }

  onKeyDown(event) {
    if (event.target.tagName === 'INPUT') return;
    if (event.key === 'Escape') {
      if (!this.dom.codexModal.classList.contains('hidden')) this.closeCodex();
      else if (!this.dom.switchModal.classList.contains('hidden') && !this.switchForced) this.closeSwitch();
      return;
    }
    if (this.modalOpen) return;
    if (event.key === 'm' || event.key === 'M') {
      this.toggleMute();
      return;
    }
    if (this.state === 'title') {
      if (event.key === 'Enter') this.enterRift();
      return;
    }
    if (this.state === 'select') {
      if (['1', '2', '3'].includes(event.key)) this.selectLead(Number(event.key) - 1);
      if (event.key === 'Enter' && !this.dom.deployBtn.disabled) this.deploy();
      return;
    }
    if (this.state === 'end') {
      if (event.key === 'Enter') this.newRift();
      return;
    }
    if (this.state !== 'battle' || this.busy) return;

    if (event.key === 'q' || event.key === 'Q') {
      this.cycleGroup(-1);
    } else if (event.key === 'e' || event.key === 'E') {
      this.cycleGroup(1);
    } else if (event.key === 'b' || event.key === 'B') {
      this.openSwitch(false);
    } else if (event.key === 'c' || event.key === 'C') {
      this.openCodex();
    } else if (event.key === '1' || event.key === '2') {
      const moves = this.pActive.moves
        .map((move, index) => ({ move, index }))
        .filter(({ move }) => move.group === this.currentGroup && move.pp > 0);
      const slot = Number(event.key) - 1;
      if (moves[slot]) {
        this.audio.init();
        this.resolveTurn(moves[slot].index);
      }
    }
  }

  cycleGroup(direction) {
    if (this.state !== 'battle' || this.busy) return;
    const index = GROUP_ORDER.indexOf(this.currentGroup);
    this.currentGroup = GROUP_ORDER[(index + direction + GROUP_ORDER.length) % GROUP_ORDER.length];
    this.audio.init();
    this.audio.click();
    this.renderMoves();
  }

  toggleMute() {
    this.audio.init();
    this.audio.setMuted(!this.audio.muted);
    this.dom.muteBtn.classList.toggle('muted', this.audio.muted);
    this.dom.muteBtn.title = this.audio.muted ? 'Unmute (M)' : 'Mute (M)';
    if (!this.audio.muted) this.audio.click();
  }

  /* ══════════════ CODEX ══════════════ */
  openCodex() {
    if (this.modalOpen) return;
    this.audio.init();
    this.audio.click();
    this.dom.codexBody.innerHTML = codexMarkup(this.run);
    this.dom.codexModal.classList.remove('hidden');
    this.modalOpen = true;
  }

  closeCodex() {
    this.dom.codexModal.classList.add('hidden');
    this.modalOpen = false;
    this.audio.click();
  }

  /* ══════════════ END / REMATCH ══════════════ */
  showEndScreen(victory) {
    if (this.state !== 'end') return;
    this.dom.endScreen.classList.remove('hidden');
    this.dom.hud.classList.add('hidden');
    this.dom.dock.classList.add('hidden');
    this.dom.hintBar.classList.add('hidden');
    const survivors = this.battle.playerTeam.filter((c) => !c.fainted).length;
    const felled = this.battle.enemyTeam.filter((c) => c.fainted).length;
    this.dom.endKicker.textContent = victory ? 'RIFT CLEARED' : 'RIFT LOST';
    this.dom.endTitle.textContent = victory ? 'CHAMPION OF THE RIFT' : 'THE RIFT CLAIMS YOU';
    this.dom.endText.textContent = victory
      ? `${this.run.warden.name} falls. Your procedural trio carves its names into the arena — and the next seed is already waiting.`
      : `${this.run.warden.name} holds the arena. The seed is not spent: rematch with the same trio, or forge an entirely new rift.`;
    this.dom.endStats.innerHTML = [
      ['ROUNDS', this.battle.round],
      ['DAMAGE DEALT', Math.round(this.battle.damageDealt)],
      ['DAMAGE TAKEN', Math.round(this.battle.damageTaken)],
      ['SURVIVORS', `${survivors} / 3`],
      ['FOES FELLED', `${felled} / 3`],
      ['SEED', this.run.seed],
    ].map(([label, value]) => `<div class="end-stat"><span>${label}</span><b>${value}</b></div>`).join('');
    this.dom.endSeed.textContent = this.run.seed;
    this.dom.rematchBtn.classList.remove('hidden');
    this.audio.setMuted(this.audio.muted);
  }

  rematch() {
    if (this.state !== 'end') return;
    this.audio.init();
    this.audio.confirm();
    clearTimeout(this.endTimer);
    restoreTeam(this.run.playerTeam);
    restoreTeam(this.run.enemyTeam);
    this.battle = {
      playerTeam: this.run.playerTeam,
      enemyTeam: this.run.enemyTeam,
      playerActive: 0,
      enemyActive: 0,
      round: 1,
      damageDealt: 0,
      damageTaken: 0,
      startedAt: Date.now(),
    };
    this.playerModels.forEach((model, index) => {
      this.resetModel(model, this.run.playerTeam[index], this.PLAYER_SPOT, this.PLAYER_ROT, index === 0);
    });
    this.enemyModels.forEach((model, index) => {
      this.resetModel(model, this.run.enemyTeam[index], this.ENEMY_SPOT, this.ENEMY_ROT, index === 0);
    });
    this.dom.endScreen.classList.add('hidden');
    this.dom.hud.classList.remove('hidden');
    this.dom.dock.classList.remove('hidden');
    this.dom.battleLog.innerHTML = '';
    this.state = 'battle';
    this.busy = false;
    this.currentGroup = 'physical';
    this.modalOpen = false;
    this.dom.roundNum.textContent = '1';
    this.dom.duelRoom.textContent = this.run.room.name;
    this.updateUI();
    this.setTurn('YOUR MOVE');
    this.log('The rift resets. A rematch begins.', 'system');
    this.showBanner('REMATCH', this.run.room.name, this.run.warden.name, 2000);
    this.audio.cry(this.pActive.type, this.pActive.seed);
    setTimeout(() => this.audio.cry(this.eActive.type, this.eActive.seed), 350);
    this.updateCameraRig();
  }

  newRift() {
    if (this.state !== 'end') return;
    clearTimeout(this.endTimer);
    const seed = randomSeed();
    this.dom.endScreen.classList.add('hidden');
    this.dom.seedInput.value = seed;
    this.enterRift(seed);
  }
}

